window.__BOOK_a_arte_da_guerra_sun_tzu = [{"type":"image","src":"_sistema/biblioteca_data/images/a_arte_da_guerra_sun_tzu/img_p1_269.jpeg","page":1,"width":380,"height":650},{"type":"image","src":"_sistema/biblioteca_data/images/a_arte_da_guerra_sun_tzu/img_p2_3.jpeg","page":2,"width":154,"height":30},{"type":"paragraph","text":"SUN TZU","page":2},{"type":"paragraph","text":"A ARTE DA GUERRA","page":2},{"type":"paragraph","text":"TRADUZIDO DO CHINÊS PARA O FRANCÊS","page":2},{"type":"paragraph","text":"PELO PADRE AMIOT EM 1772","page":2},{"type":"paragraph","text":"TRADUZIDO DO FRANCÊS POR","page":2},{"type":"paragraph","text":"SUELI BARROS CASSAL www.lpm.com.br","page":2},{"type":"paragraph","text":"Coleção L&PM Pocket, vol. 207 Título original: L' arl de Ia guerre Tradução: Sueli Barros Cassal Capa: Ivan Pinheiro Machado Revisão: Renato Deitas Produção: Já Saldanha e Lúcia Bohrer ISBN: 85.254.1059-4 T999a Tzu, Sun","page":3},{"type":"paragraph","text":"A arte da guerra / Sun Tzu; tradução de Sueli Barros Cassal. -- Porto Alegre: L&PM, 2006.","page":3},{"type":"paragraph","text":"152p. ; 18 cm (Coleção L&PM Pocket) 1. Estratégia militar-Guerra. 2.Guerra-Estratégia militar. 1. Título. 11.Série.","page":3},{"type":"paragraph","text":"CDU 335.4","page":3},{"type":"paragraph","text":"Catalogação elaborada por lzabel A. Medo, CRB 10/329. © L&PM Editores, 2000 Todos os direitos desta edição reservados à L&PM Editores PORTOALEGRE:Rua Comendador Coruja 314, loja 9 - 90220-180","page":3},{"type":"paragraph","text":"Floresta - RS / Fone: 51.3225.5777 PEDIDOS& DEPTO.COMERCIALv:endas@lpm.com.br FALE CONOSCO:info@lpm.com.br www.lpm.com.br Impresso no Brasil Outono de 2006","page":3},{"type":"heading","id":"h_suntzu_0","lvl":1,"title":"Índice Geral","page":4},{"type":"paragraph","text":"ÍNDICE","page":4},{"type":"paragraph","text":"A ARTE DA GUERRA ............................................................................................................... 5","page":4},{"type":"paragraph","text":"O MAIS ANTIGO TRATADO MILITAR DO MUNDO............................................................ 5","page":4},{"type":"paragraph","text":"VIDA DE SUN TZU, SEGUNDO O COMENTARISTA SE-MA TS’IEN (CERCA DE 100","page":4},{"type":"paragraph","text":"A. C.)............................................................................................................................................. 7","page":4},{"type":"paragraph","text":"CAPÍTULO I...............................................................................................................................12","page":4},{"type":"paragraph","text":"DA AVALIAÇÃO ...................................................................................................................12","page":4},{"type":"paragraph","text":"CAPÍTULO II .............................................................................................................................16","page":4},{"type":"paragraph","text":"DO COMANDO DA GUERRA............................................................................................16","page":4},{"type":"paragraph","text":"CAPÍTULO lII.............................................................................................................................19","page":4},{"type":"paragraph","text":"DA ARTE DE VENCER SEM DESEMBAINHAR A ESPADA .......................................19","page":4},{"type":"paragraph","text":"CAPÍTULO IV............................................................................................................................24","page":4},{"type":"paragraph","text":"DA ARTE DE MANOBRAR AS TROPAS.........................................................................24","page":4},{"type":"paragraph","text":"CAPÍTULO V.............................................................................................................................28","page":4},{"type":"paragraph","text":"DO CONFRONTO DIRETO E INDIRETO........................................................................28","page":4},{"type":"paragraph","text":"CAPÍTULO VI............................................................................................................................31","page":4},{"type":"paragraph","text":"DO CHEIO E DO VAZIO.....................................................................................................31","page":4},{"type":"paragraph","text":"CAPÍTULO VII...........................................................................................................................37","page":4},{"type":"paragraph","text":"DA ARTE DO CONFRONTO..............................................................................................37","page":4},{"type":"paragraph","text":"CAPÍTULO VIII..........................................................................................................................42","page":4},{"type":"paragraph","text":"DA ARTE DAS MUDANÇAS ..............................................................................................42","page":4},{"type":"paragraph","text":"CAPÍTULO IX............................................................................................................................48","page":4},{"type":"paragraph","text":"DA IMPORTÂNCIA DA GEOGRAFIA...............................................................................48","page":4},{"type":"paragraph","text":"CAPÍTULO X.............................................................................................................................55","page":4},{"type":"paragraph","text":"DA TOPOGRAFIA................................................................................................................55","page":4},{"type":"paragraph","text":"CAPÍTULO XI............................................................................................................................61","page":4},{"type":"paragraph","text":"DOS NOVE TIPOS DE TERRENOS.................................................................................61","page":4},{"type":"paragraph","text":"CAPÍTULO XII...........................................................................................................................72","page":4},{"type":"paragraph","text":"DA PIROTECNIA..................................................................................................................72","page":4},{"type":"paragraph","text":"CAPÍTULO XIII..........................................................................................................................75","page":4},{"type":"paragraph","text":"DA ARTE DE SEMEAR A DISCÓRDIA............................................................................75","page":4},{"type":"heading","id":"h_suntzu_1","lvl":1,"title":"O Mais Antigo Tratado Militar do Mundo","page":5},{"type":"paragraph","text":"A ARTE DA GUERRA","page":5},{"type":"paragraph","text":"O MAIS ANTIGO TRATADO MILITAR DO MUNDO","page":5},{"type":"paragraph","text":"Pouco importa saber se Sun Tzu existiu ou é uma figura lendária. O fato é que um texto que remonta à turbulenta época dos Estados Guerreiros da","page":5},{"type":"paragraph","text":"China, há quase dois mil anos, chegou até nós, trazendo as ideias de um filosofo estrategista que certamente comandou e venceu muitas batalhas, se","page":5},{"type":"paragraph","text":"acreditarmos no comentarista Se-Ma Ts’ien, do século I a.C, cujo texto apresentamos mais adiante.","page":5},{"type":"paragraph","text":"A tradução que ora publicamos é uma da muitas versões existentes. Ela foi feita pelo missionário jesuíta Amiot em 1772, sendo a primeira versão que","page":5},{"type":"paragraph","text":"se conhece no Ocidente. O Padre Amiot deixou de lado os comentários que foram acrescentados aos versículos, ao longo do tempo, por vários","page":5},{"type":"paragraph","text":"comentadores chineses. A tradução para o inglês de Lionel Giles e Samuel B.","page":5},{"type":"paragraph","text":"Griffith contemplam esses comentários – lendas, fábulas, exemplos históricos, explicações, interpretações – que estabelecem um dialogo hipertextual com","page":5},{"type":"paragraph","text":"Sun Tzu.","page":5},{"type":"paragraph","text":"Compulsando-se a variedade de versões existentes, observa-se que o texto tornou-se um palimpsesto que, dois milênios depois, ainda conserva seu","page":5},{"type":"paragraph","text":"fulcro original e sua dicção aforismática e oracular.","page":5},{"type":"paragraph","text":"Embora as táticas bélicas tenham mudado desde a época de Sun Tzu, esse tratado teria influenciado, segundo a Enciclopédia Britânica, certos","page":5},{"type":"paragraph","text":"estrategistas modernos como Mao Tsé-tung, em sua luta contra os japoneses e os chineses nacionalistas.","page":5},{"type":"paragraph","text":"Hoje, o livro parece destinado a secundar outra guerra: a das empresas no mundo dos negócios. Assim, o livro migrou das estantes do estrategista","page":5},{"type":"paragraph","text":"para as do economista e do administrador.","page":5},{"type":"paragraph","text":"Qual é a originalidade, desse que é o mais antigo tratado de guerra? É que é melhor ganhar a guerra antes mesmo de desembainhar a espada. O","page":5},{"type":"paragraph","text":"inimigo não deve ser aniquilado, mas, de preferência, deve ser vencido quando seus domínios ainda estiverem intatos. Muitas vezes, a vitória arduamente","page":5},{"type":"paragraph","text":"conquistada guarda um sabor amargo de derrota, mesmo para os próprios vencedores.","page":6},{"type":"paragraph","text":"Com seu caráter sentencioso, Sun Tzu forja a figura de um general super homem cujas qualidades são o segredo, a dissimulação, a astúcia e a","page":6},{"type":"paragraph","text":"surpresa. Esse general deve evitar cinco defeitos básicos: a precipitação, a hesitação, a irascibilidade, a preocupação com as aparências e a excessiva","page":6},{"type":"paragraph","text":"complacência. Para vencer, deve conhecer perfeitamente a terra (a geografia, o terreno) e os homens (tanto a si mesmo quanto o inimigo). O resto é uma","page":6},{"type":"paragraph","text":"questão de cálculo. Eis a arte da guerra.","page":6},{"type":"paragraph","text":"Em tempos de guerras generalizadas e sub-reptícias como os que vivemos (da guerra dos sexos à das empresas), vale a lição do livro: a primeira","page":6},{"type":"paragraph","text":"batalha que devemos travar é com nós mesmos.","page":6},{"type":"paragraph","text":"Lendo o trecho a seguir em que Sun Tzu interpela o general, há ou não motivos para refletirmos?","page":6},{"type":"paragraph","text":"“Lembra-te que defendes não interesses pessoais, mas os do teu país.","page":6},{"type":"paragraph","text":"Tuas virtudes e teus vícios, tuas qualidades e teus defeitos influem igualmente no ânimo daqueles que representas. Teus menores erros têm sempre nefastas","page":6},{"type":"paragraph","text":"conseqüências. Geralmente, os grandes são irreparáveis e funestos. É difícil sustentar um reino que terás levado à beira da ruína. Depois de destruí-lo, é","page":6},{"type":"paragraph","text":"impossível reerguê-lo. Tampouco se ressuscitam os mortos.”","page":6},{"type":"paragraph","text":"Sueli Barros Cassal","page":6},{"type":"heading","id":"h_suntzu_2","lvl":1,"title":"Vida de Sun Tzu","page":7},{"type":"paragraph","text":"VIDA DE SUN TZU, SEGUNDO O COMENTARISTA SE-MA TS’IEN","page":7},{"type":"paragraph","text":"(CERCA DE 100 A. C.)","page":7},{"type":"paragraph","text":"Sun Tzu, súdito do rei de Wu, foi o homem mais versado que jamais existiu na arte militar. A obra que escreveu e os notáveis feitos que praticou","page":7},{"type":"paragraph","text":"são uma prova de sua profunda capacidade e de sua experiência bélica. Antes mesmo de ter conquistado a grande reputação que o distinguiu em todas as","page":7},{"type":"paragraph","text":"províncias que integram hoje o Império, seu mérito era conhecido me todos os lugares adjacentes à sua pátria.","page":7},{"type":"paragraph","text":"O rei Wu tinha algumas contendas com o rei Tchu. Eles estavam prestes a se engalfinharem numa guerra aberta e, de ambas as partes, corriam os","page":7},{"type":"paragraph","text":"preparativos. Sun Tzu não quis ficar de braços cruzados. Persuadido de que o personagem de espectador não fora talhado para si, apresentou-se ao rei de","page":7},{"type":"paragraph","text":"Wu, solicitando ingresso em suas hostes. O rei, feliz por um homem de tal mérito tomar seu partido, acolheu-o de bom grado. Quis vê-lo e interrogá-lo","page":7},{"type":"paragraph","text":"pessoalmente.","page":7},{"type":"paragraph","text":"- Sun Tzu - disse-lhe o rei -, li a obra que escreveste sobre a arte militar, e fiquei muito contente; mas os preceitos que sugeres me parecem de difícil","page":7},{"type":"paragraph","text":"execução. Alguns deles me parecem absolutamente impraticáveis. Será que tu mesmo poderias executá-los? Há um abismo entre a teoria e a prática.","page":7},{"type":"paragraph","text":"Imaginamos os mais belos estratagemas quando estamos tranqüilos em nosso gabinete e só fazemos a guerra na imaginação. Tudo muda quando estamos","page":7},{"type":"paragraph","text":"no terreno. Geralmente, o que presumíamos fácil revela-se tarefa impossível.","page":7},{"type":"paragraph","text":"- Príncipe - respondeu Sun Tzu -, nada disse em meus escritos que já não tivesse praticado nos exércitos, mas o que ainda não disse é que estou em","page":7},{"type":"paragraph","text":"condições de fazer qualquer um colocar em prática minhas idéias, bem como posso treinar qualquer indivíduo para os exercícios militares, se for autorizado","page":7},{"type":"paragraph","text":"a tanto.","page":7},{"type":"paragraph","text":"- Compreendo - replicou o rei. – Queres dizer que instruirás facilmente, com tuas máximas, homens inteligentes, de índole prudente e corajosa; que","page":7},{"type":"paragraph","text":"formarás, sem muita dificuldade, para os exercícios militares homens afeitos ao trabalho, dóceis e cheios de boa vontade. Mas a maioria não é desse naipe.","page":7},{"type":"paragraph","text":"- Não importa - continuou Sun Tzu. - Disse \"qualquer um\", e não excluo ninguém de minha proposição. Incluo até os mais sediciosos, os mais covardes","page":8},{"type":"paragraph","text":"e os mais fracos.","page":8},{"type":"paragraph","text":"- Ouvindo-o falar - retomou o rei -, parece que incutirias até nas mulheres sentimentos que plasmam os guerreiros, que as treinarias para os","page":8},{"type":"paragraph","text":"exercícios das armas.","page":8},{"type":"paragraph","text":"- Sim, Príncipe - replicou Sun Tzu, com tom firme. - Rogo que Vossa","page":8},{"type":"paragraph","text":"Majestade acredite nisso.","page":8},{"type":"paragraph","text":"O rei, entediado pelos divertimentos ordinários da Corte, aproveitou a ocasião para obter um regalo diferente.","page":8},{"type":"paragraph","text":"- Tragam-me aqui - disse - minhas cento e oitenta mulheres.","page":8},{"type":"paragraph","text":"Ele foi obedecido, e as princesas apareceram. Entre elas, havia duas que o príncipe amava com devoção. Elas foram colocadas à frente das outras.","page":8},{"type":"paragraph","text":"- Veremos - disse o rei, sorrindo -, veremos, Sun Tzu, se manténs a tua palavra. Nomeio-te general dessas novas tropas. Só terás que escolher o lugar","page":8},{"type":"paragraph","text":"mais apropriado no palácio para exercitá-Ias às armas. Quando elas estiverem suficientemente treinadas, me avisarás e eu virei fazer justiça à tua habilidade","page":8},{"type":"paragraph","text":"e a teu talento.","page":8},{"type":"paragraph","text":"O general, sentindo todo o ridículo do papel que lhe impingiam, não se desconcertou, mostrando-se, ao contrário, muito satisfeito da honra que o rei","page":8},{"type":"paragraph","text":"lhe fazia, não somente permitindo que visse suas mulheres, mas ainda colocando-as sob seu comando.","page":8},{"type":"paragraph","text":"- Executarei a tarefa a contento, Majestade - replicou ele, com segurança. - Espero que, em breve, Vossa Majestade tenha ocasião de","page":8},{"type":"paragraph","text":"rejubilar-se com os meus serviços, convencendo-se de que Sun Tzu não é homem de se vangloriar.","page":8},{"type":"paragraph","text":"O rei retirou-se para seus aposentos, e o guerreiro não pensou em mais nada senão em executar a tarefa. Solicitou armas e todo o equipamento militar","page":8},{"type":"paragraph","text":"para seus soldados. Depois de tudo pronto, conduziu suas tropas a uma das alas do palácio que lhe pareceu mais adequada a seus propósitos.","page":8},{"type":"paragraph","text":"Então, Sun Tzu dirigiu a palavra às favoritas:","page":8},{"type":"paragraph","text":"- Vocês estão sob meu comando e sob minhas ordens. Devem me escutar atentamente e me obedecer em tudo o que ordenar. Essa é a regra","page":8},{"type":"paragraph","text":"militar fundamental. Evitem infringi-Ia. A partir de amanhã, farão o exercício diante do rei, e deverão estar prontas.","page":9},{"type":"paragraph","text":"Depois dessas palavras, cingiu-as com o boldrié e lhes colocou uma alabarda na mão. Dividiu-as em dois grupos, colocando na frente as favoritas.","page":9},{"type":"paragraph","text":"Depois desse arranjo, começou as instruções nestes termos:","page":9},{"type":"paragraph","text":"- Sabem distinguir a frente das costas, e a mão direita da mão esquerda? Respondam!","page":9},{"type":"paragraph","text":"Só recebeu como resposta algumas gargalhadas. Mas como permanecesse silencioso e sério, as concubinas responderam em uníssono:","page":9},{"type":"paragraph","text":"- Sim, sem dúvida.","page":9},{"type":"paragraph","text":"- Assim, prestem muita atenção ao que vou lhes dizer. Quando o tambor der um único golpe, permaneçam na posição atual, prestando atenção ao que","page":9},{"type":"paragraph","text":"está em sua frente. Ouvindo dois golpes, virem-se, de forma que a frente ocupe o lugar da mão direita. Quando soarem três golpes, virem-se de forma que a","page":9},{"type":"paragraph","text":"frente ocupe o lugar da mão esquerda. Quando o tambor der quatro golpes, devem virar-se e a frente deve ocupar o lugar das costas. O que acabo de dizer","page":9},{"type":"paragraph","text":"pode não ter ficado claro. Repito: Um único golpe de tambor significa \"Sentido!\"","page":9},{"type":"paragraph","text":"Dois golpes, \"direita, volver\". Três golpes, \"esquerda, volver\". Quatro golpes,","page":9},{"type":"paragraph","text":"\"meia volta\". Repetindo; a primeira ordem que darei será esta: primeiramente farei soar um único golpe. A esse sinal, ficarão prontas para o que vou ordenar.","page":9},{"type":"paragraph","text":"Alguns momentos depois, soarei dois golpes: então, todas juntas, virarão à direita, com gravidade. Em seguida, farei soar quatro golpes, e completarão a","page":9},{"type":"paragraph","text":"meia volta. Depois, retomarão à posição inicial e, como antes, ouvirão um único golpe. Compenetrem-se. Em seguida, farei soar, não dois, mas três golpes, e","page":9},{"type":"paragraph","text":"vocês volverão à esquerda. Ouvindo quatro golpes, completarão a meia volta.","page":9},{"type":"paragraph","text":"Compreenderam bem o que eu disse? Se têm alguma dificuldade, não hesitem em me comunicar e tentarei solucioná-Ia.","page":9},{"type":"paragraph","text":"- Estamos prontas, responderam as mulheres.","page":9},{"type":"paragraph","text":"- Assim sendo - retomou Sun Tzu -, vou começar. Não se esqueçam de que o som do tambor substitui a voz do general, pois é por seu intermédio que","page":9},{"type":"paragraph","text":"ele lhes dá ordens.","page":9},{"type":"paragraph","text":"Sun Tzu repetiu essa instrução três vezes. Depois, ordenou de novo seu pequeno exército. Em seguida, fez soar um golpe de tambor. A esse barulho,","page":9},{"type":"paragraph","text":"todas as princesas começaram a rir. Ele soou duas vezes, elas riram mais forte. O general, sem perder a compostura, dirigiu-lhes a palavra nestes","page":9},{"type":"paragraph","text":"termos:","page":10},{"type":"paragraph","text":"- Pode ser que não tenha me explicado claramente. Se aconteceu isso, a culpa é minha. Vou tentar remediar o fato, falando-Ihes de uma forma que","page":10},{"type":"paragraph","text":"esteja a seu alcance.","page":10},{"type":"paragraph","text":"Em seguida, repetiu três vezes a mesma instrução, usando outros termos.","page":10},{"type":"paragraph","text":"- Quero ver se agora serei melhor obedecido.","page":10},{"type":"paragraph","text":"Ele fez soar o tambor. Soaram dois golpes. Em virtude da situação estranha e grave em que se encontravam, as mulheres esqueceram que era","page":10},{"type":"paragraph","text":"preciso obedecer. Após terem tentado controlar o riso que as sufocava, soltaram as mais vivas gargalhadas.","page":10},{"type":"paragraph","text":"Sun Tzu não se desconcertou. No mesmo tom que lhes tinha falado antes, disse-Ihes:","page":10},{"type":"paragraph","text":"- Se eu não tivesse me explicado bem, ou se vocês não me tivessem afirmado, em coro, que tinham compreendido, não seriam culpadas. Mas lhes","page":10},{"type":"paragraph","text":"falei claramente, como vocês mesmas admitiram. Por que não obedeceram?","page":10},{"type":"paragraph","text":"Vocês merecem punição, e punição militar. No universo militar, aquele que não obedece às ordens do general merece a morte. Vocês morrerão.","page":10},{"type":"paragraph","text":"Depois desse preâmbulo, Sun Tzu ordenou que duas mulheres matassem as favoritas, que estavam à sua frente. No mesmo momento, um","page":10},{"type":"paragraph","text":"dos guardas das mulheres, percebendo que o guerreiro não estava brincando, correu para avisar o rei a respeito do que estava acontecendo. O rei despachou","page":10},{"type":"paragraph","text":"alguém para proibir que Sun Tzu matasse as duas favoritas, sem as quais não podia viver.","page":10},{"type":"paragraph","text":"O general escutou com respeito o emissário, mas não acedeu ao pedido do rei.","page":10},{"type":"paragraph","text":"- Diga ao rei - respondeu - que Sun Tzu o considera bastante sensato e justo para pensar que ele pudesse ter mudado de idéia, e queira realmente que","page":10},{"type":"paragraph","text":"eu aceda à contra-ordem recente. O príncipe faz a lei, mas não poderia dar ordens que aviltassem a dignidade com que me revestiu. Ele me encarregou de","page":10},{"type":"paragraph","text":"treinar suas cento e oitenta mulheres. Sagrou-me seu general: cabe a mim fazer o resto.Elas me desobedeceram, por isso morrerão.","page":10},{"type":"paragraph","text":"Mal tendo pronunciado essas últimas palavras, tirou o sabre e, com o mesmo sangue frio que mostrara até então, decapitou as duas favoritas, que","page":11},{"type":"paragraph","text":"comandavam as outras. Imediatamente, substituiu-as por outras, fez soar o tambor, como combinado. E, como se tivessem durante toda a vida exercido o","page":11},{"type":"paragraph","text":"ofício da guerra, as mulheres manobraram em silêncio e de forma impecável.","page":11},{"type":"paragraph","text":"Sun Tzu dirigiu-se ao emissário do rei:","page":11},{"type":"paragraph","text":"- Vá avisar o rei - disse - que suas mulheres sabem fazer o exercício; que posso levá-Ias à guerra, fazer com que enfrentem todo tipo de perigo, até","page":11},{"type":"paragraph","text":"mesmo atravessar a água e o fogo.","page":11},{"type":"paragraph","text":"O rei, informado de tudo, ficou desesperado.","page":11},{"type":"paragraph","text":"- Perdi - disse, suspirando - o que mais amava no mundo. Que esse estranho se retire em seu país. Não quero saber dele nem de seus serviços.","page":11},{"type":"paragraph","text":"Então, Sun Tzu disse:","page":11},{"type":"paragraph","text":"- O rei ama palavras vazias. Não é capaz de juntar o gesto à palavra.","page":11},{"type":"paragraph","text":"O tempo e as circunstâncias fizeram com que o rei fizesse o luto. Os inimigos estavam prestes a esmagá-Io. Então, convocou novamente Sun Tzu,","page":11},{"type":"paragraph","text":"nomeou-o general de seus exércitos e, por seu intermédio, destruiu o reinado de Tchu. Os vizinhos que antes mais o inquietavam, cheios de temor à menção","page":11},{"type":"paragraph","text":"dos belos feitos de Sun Tzu, não hesitaram em pedir proteção a um príncipe que tinha tal homem a seu serviço.","page":11},{"type":"heading","id":"h_suntzu_3","lvl":1,"title":"Capítulo I — Da Avaliação","page":12},{"type":"paragraph","text":"CAPÍTULO I","page":12},{"type":"paragraph","text":"DA AVALIAÇÃO","page":12},{"type":"paragraph","text":"Sun Tzu diz: A guerra tem importância crucial para o Estado. É o reino da vida e da morte. Dela depende a conservação ou a ruína do império. Urge","page":12},{"type":"paragraph","text":"bem regulá-Ia. Quem não reflete seriamente sobre o assunto evidencia uma indiferença condenável pela conservação ou pela perda do que mais se preza.","page":12},{"type":"paragraph","text":"Isso não deve ocorrer entre nós.","page":12},{"type":"paragraph","text":"A arte da guerra implica cinco fatores principais, que devem ser o objeto de nossa contínua meditação e de todo o nosso cuidado, como fazem os","page":12},{"type":"paragraph","text":"grandes artistas ao iniciarem uma obra-prima. Eles têm sempre em mente o objetivo a que visam, e aproveitam tudo o que vêem e ouvem, esforçando-se","page":12},{"type":"paragraph","text":"para adquirir novos conhecimentos e todos os subsídios que possam conduzi- los ao êxito.","page":12},{"type":"paragraph","text":"Se quisermos que a glória e o sucesso acompanhem nossas armas, jamais devemos perder de vista os seguintes fatores: a doutrina, o tempo, o","page":12},{"type":"paragraph","text":"espaço, o comando, a disciplina.","page":12},{"type":"paragraph","text":"A doutrina engendra a unidade de pensamento; inspira-nos uma mesma maneira de viver e de morrer, tornando-nos intrépidos e inquebrantáveis diante","page":12},{"type":"paragraph","text":"dos infortúnios e da morte.","page":12},{"type":"paragraph","text":"Se conhecermos bem o tempo, não ignoraremos os dois grandes princípios yin e yang, mediante os quais todas as coisas naturais se formam e","page":12},{"type":"paragraph","text":"dos quais todos os elementos recebem seus mais diversos influxos.","page":12},{"type":"paragraph","text":"Apreciaremos o tempo da interação desses princípios, para a produção do frio, do calor, da bonança ou da intempérie.","page":12},{"type":"paragraph","text":"O espaço, como o tempo, não é menos digno de nossa atenção. Se o estudarmos bem, teremos a noção do alto e do baixo; do longe e do perto; do","page":12},{"type":"paragraph","text":"largo e do estreito; do que permanece e do que não cessa de fluir.","page":12},{"type":"paragraph","text":"Entendo por comando a eqüidade, o amor pelos subordinados e pela humanidade em geral. O conhecimento de todos os recursos, a coragem, a","page":12},{"type":"paragraph","text":"determinação e o rigor são as qualidades que devem caracterizar aquele que investe a dignidade de general. São virtudes necessárias que devemos adquirir","page":12},{"type":"paragraph","text":"a qualquer preço. Somente elas podem tornar-nos aptos a marchar dignamente","page":13},{"type":"paragraph","text":"à frente dos outros.","page":13},{"type":"paragraph","text":"Aos conhecimentos acima mencionados convém acrescentar o de disciplina. Possuir a arte de ordenar as tropas; não ignorar nenhuma das leis","page":13},{"type":"paragraph","text":"da hierarquia e fazer com que sejam cumpridas com rigor; estar ciente dos deveres particulares de cada subalterno; conhecer os diferentes caminhos que","page":13},{"type":"paragraph","text":"levam a um mesmo lugar; não desdenhar o conhecimento exato e detalhado de todos os fatores que podem intervir; e informar-se de cada um deles em","page":13},{"type":"paragraph","text":"particular. Tudo isso somado constitui uma doutrina, cujo conhecimento prático não deve escapar à sagacidade nem à atenção de um general.","page":13},{"type":"paragraph","text":"Se tu - que a escolha do príncipe colocou à testa dos exércitos - calcares teus fundamentos de ciência militar sobre os cinco princípios que acabo de","page":13},{"type":"paragraph","text":"estabelecer, a vitória será teu galardão. Em compensação, sofrerás as mais abjetas derrotas se, por ignorância ou presunção, vieres a omiti-Ios ou a rejeitá-","page":13},{"type":"paragraph","text":"Ios.","page":13},{"type":"paragraph","text":"Esses conhecimentos te permitirão discernir, entre os príncipes que governam o mundo, aquele que ostenta mais doutrina e virtudes. Conhecerás","page":13},{"type":"paragraph","text":"grandes generais nos mais diversos reinos, de forma que poderás prever com segurança qual dos adversários será vencedor; e se tiveres que intervir na","page":13},{"type":"paragraph","text":"contenda, poderás certamente gabar-te da vitória.","page":13},{"type":"paragraph","text":"Esses mesmos conhecimentos farão com que prevejas os momentos mais propícios, pois o tempo e o espaço devem conjugar-se para orientar o","page":13},{"type":"paragraph","text":"movimento e os itinerários das tropas, cujas marchas regularás com precisão.","page":13},{"type":"paragraph","text":"Jamais comeces ou termines uma campanha fora do momento azado.","page":13},{"type":"paragraph","text":"Conhece o ponto forte e o fraco tanto dos que forem confiados a teus cuidados quanto dos inimigos. Informa-te da quantidade e do estado em que se","page":13},{"type":"paragraph","text":"encontram as munições e os víveres dos dois exércitos. Distribui recompensas com liberalidade, mas com critério. Não poupes castigos, quando necessários.","page":13},{"type":"paragraph","text":"Conquistados por tuas virtudes e tuas capacidades, os oficiais colocados sob tuas ordens te servirão tanto por prazer quanto por dever. Eles se","page":13},{"type":"paragraph","text":"espelharão em teu exemplo; o exemplo deles servirá para os subordinados, e os soldados rasos, por sua vez, tudo farão para te assegurar o mais glorioso","page":13},{"type":"paragraph","text":"sucesso.","page":13},{"type":"paragraph","text":"Estimado, respeitado, amado pelos teus, os povos vizinhos virão espontaneamente juntar-se aos estandartes do príncipe que serves, quer para","page":14},{"type":"paragraph","text":"viver sob suas leis, quer simplesmente para obter proteção.","page":14},{"type":"paragraph","text":"Ciente de tuas capacidades e limitações, não inicies nenhuma empreitada que não possas levar a cabo. Decifra, com a mesma argúcia, o","page":14},{"type":"paragraph","text":"longe e o perto, para que o que se desenrola sob teus olhos seja idêntico ao que deles está mais recôndito.","page":14},{"type":"paragraph","text":"Aproveita a dissensão entre os inimigos para atrair os descontentes para o teu campo, não regateando promessas, oferendas ou recompensas.","page":14},{"type":"paragraph","text":"Se teus inimigos forem mais poderosos e mais fortes, não os ataques.","page":14},{"type":"paragraph","text":"Evita cuidadosamente o que pode redundar num conflito generalizado.","page":14},{"type":"paragraph","text":"Dissimula sempre, com extremo cuidado, o estado de tuas forças.","page":14},{"type":"paragraph","text":"Haverá ocasiões em que te rebaixarás, e outras em que simularás medo. Finge ser fraco a fim de que teus inimigos, abrindo a porta para a","page":14},{"type":"paragraph","text":"presunção e para o orgulho, venham atacar-te em hora errada, ou sejam surpreendidos e derrotados vergonhosamente. Age de tal forma que teus","page":14},{"type":"paragraph","text":"inferiores jamais descubram teus projetos. Mantém tuas tropas sempre de prontidão, ocupadas e em movimento, para evitar que uma infame ociosidade","page":14},{"type":"paragraph","text":"as quebrante.","page":14},{"type":"paragraph","text":"Se vês algum interesse em meus planos, cria situações que contribuam para sua realização. Entendo por \"situação\" que o general aja eficientemente,","page":14},{"type":"paragraph","text":"em harmonia com o que é vantajoso e, dessa forma, demonstre controle e equilíbrio.","page":14},{"type":"paragraph","text":"Toda campanha militar repousa na dissimulação. Finge desordem.","page":14},{"type":"paragraph","text":"Jamais deixes de oferecer um engodo ao inimigo, para ludibriá-lo. Simula inferioridade para encorajar sua arrogância. Atiça sua raiva para melhor","page":14},{"type":"paragraph","text":"mergulhá-lo na confusão. Sua cobiça o arremeterá contra ti e, então, ele se estilhaçará.","page":14},{"type":"paragraph","text":"Apresta os preparativos quando teus adversários se concentrarem.","page":14},{"type":"paragraph","text":"Quando forem poderosos, evita-os.","page":14},{"type":"paragraph","text":"Mergulha o adversário em inextricáveis provações e prolonga seu esgotamento, mantendo-te a distância. Procura fortificar tuas alianças externas","page":14},{"type":"paragraph","text":"e consolidar tuas posições internas.","page":14},{"type":"paragraph","text":"Quão lamentável é arriscar tudo em um único combate, negligenciando a estratégia vitoriosa, e fazer com que o destino de tuas armas dependa de uma","page":15},{"type":"paragraph","text":"única batalha!","page":15},{"type":"paragraph","text":"Quando o inimigo estiver unido, divide-o. Ataca-o, quando ele estiver despreparado. Irrompe onde ele menos espera. Tais são as estratégias da","page":15},{"type":"paragraph","text":"vitória. Mas toma cuidado de não te servires delas antes da hora.","page":15},{"type":"paragraph","text":"O general deve basear-se em avaliações prévias. Elas apontam para a vitória quando demonstram que sua força é superior à do inimigo. Indicam a","page":15},{"type":"paragraph","text":"derrota quando demonstram inferioridade.","page":15},{"type":"paragraph","text":"Com numerosos cálculos, pode-se obter a vitória. Teme quando os cálculos forem escassos. E quão poucas chances de vencer tem aquele que","page":15},{"type":"paragraph","text":"nunca calcula!","page":15},{"type":"paragraph","text":"Graças a esse método, eu, Sun Tzu, avalio a situação e o desfecho se perfilará claramente.","page":15},{"type":"heading","id":"h_suntzu_4","lvl":1,"title":"Capítulo II — Do Comando da Guerra","page":16},{"type":"paragraph","text":"CAPÍTULO II","page":16},{"type":"paragraph","text":"DO COMANDO DA GUERRA","page":16},{"type":"paragraph","text":"Sun Tzu diz: Suponho que comeces tua campanha com um exército de cem mil homens, que dispões de dois mil carros, mil destinados à marcha, e os","page":16},{"type":"paragraph","text":"outros reservados para o transporte de suprimentos. Ademais, transportas com cuidado tudo o que pode servir para o reparo de armas e carros. Suponho que","page":16},{"type":"paragraph","text":"tens víveres e munições suficientes, que à tua volta haja, em toda a parte, provisões para a manutenção do exército. Suponho ainda que os artesãos e","page":16},{"type":"paragraph","text":"outros homens que não pertencem ao corpo dos soldados já o precederam ou marcham em teu séquito. Suponho também que os diferentes suprimentos,","page":16},{"type":"paragraph","text":"tanto para uso bélico quanto pessoal, estejam permanentemente ao abrigo da intempérie e de acidentes imprevistos.","page":16},{"type":"paragraph","text":"Suponho que tens mil onças de prata para distribuir diariamente às tropas, cujo soldo é sempre pago em dia e na mais rigorosa exatidão.","page":16},{"type":"paragraph","text":"Nesse caso, podes avançar direto contra o inimigo. Atacá-Io e vencê-Io será para ti a mesma coisa.","page":16},{"type":"paragraph","text":"Digo mais: Não adies o momento do combate, nem esperes que tuas armas se enferrujem e o fio de tuas espadas se embote. A vitória é o principal","page":16},{"type":"paragraph","text":"objetivo da guerra.","page":16},{"type":"paragraph","text":"Tratando-se de tomar uma cidade, apressa-te em sitiá-Ia, concentra nisso todas as tuas forças. Precipita-te. Se falhares, tuas tropas correm o risco","page":16},{"type":"paragraph","text":"de ficar muito tempo em campanha, o que será uma fonte de funestos infortúnios.","page":16},{"type":"paragraph","text":"Os cofres do príncipe que serves se esvaziarão, tuas armas - embotadas pela ferrugem - não poderão mais servir, o entusiasmo de teus soldados","page":16},{"type":"paragraph","text":"arrefecerá, sua coragem e força esmorecerão, as provisões se esgotarão e, talvez, tu mesmo fiques reduzido a uma situação desesperadora.","page":16},{"type":"paragraph","text":"Informados do estado dramático em que te encontras, teus inimigos emergirão lépidos, arremeterão contra ti e te esmagarão. Embora até então","page":16},{"type":"paragraph","text":"tenhas sido respeitado, doravante tua reputação estará maculada. Apesar de já teres dado mostras brilhantes de valor, o último revés apagará toda a glória","page":16},{"type":"paragraph","text":"acumulada.","page":16},{"type":"paragraph","text":"Repito: não poderás manter as tropas em campanha por muito tempo, sem acarretar grande prejuízo ao Estado e sem dar um golpe mortal em tua","page":17},{"type":"paragraph","text":"própria reputação.","page":17},{"type":"paragraph","text":"Aqueles que dominam os verdadeiros princípios da arte militar não atacam duas vezes. Tudo termina já na primeira campanha. Não consomem","page":17},{"type":"paragraph","text":"suprimentos em vão, durante anos consecutivos. Fazem com que suas tropas subsistam às expensas do inimigo e poupam ao Estado os imensos gastos em","page":17},{"type":"paragraph","text":"que este incorre quando tem que transportar provisões para lugares distantes.","page":17},{"type":"paragraph","text":"Tais generais não ignoram - e tu também deves estar ciente disso - que nada exaure mais um reino do que as despesas de guerra pois, quer o exército","page":17},{"type":"paragraph","text":"esteja nas fronteiras, quer em países longínquos, o povo sempre é penalizado.","page":17},{"type":"paragraph","text":"O custo de vida aumenta, as mercadorias escasseiam, e mesmo aqueles que, em tempos de paz, usufruem uma boa situação, em breve já não terão com o","page":17},{"type":"paragraph","text":"quê comprar.","page":17},{"type":"paragraph","text":"Ávido, o príncipe recolhe o tributo em espécie que cada família lhe deve; e a miséria vai se espraiando do seio das cidades até o campo.","page":17},{"type":"paragraph","text":"Das dez partes do necessário, tem-se que abrir mão de sete. Todos têm seu quinhão nos males comuns, inclusive o soberano. Couraças, elmos,","page":17},{"type":"paragraph","text":"flechas, arcos, escudos, carros, lanças, dardos, tudo isso estragará. Os cavalos, e até os bois que lavram as terras, definharão e, das dez partes de","page":17},{"type":"paragraph","text":"sua despesa ordinária, será constrangido a eliminar seis.","page":17},{"type":"paragraph","text":"Visando prevenir todos esses desastres, um hábil general faz tudo para abreviar as campanhas, e para abastecer-se às expensas do inimigo, custe o","page":17},{"type":"paragraph","text":"que custar.","page":17},{"type":"paragraph","text":"Se o exército inimigo tem uma medida de grão em seu campo, dispõe de vinte no teu. Se teu inimigo tem cento e vinte libras de forragem para seus","page":17},{"type":"paragraph","text":"cavalos, dispõe de duas mil e quatrocentas para os teus. Não percas nenhuma ocasião de importuná-lo. Faz com que ele pereça à míngua. Encontra meios","page":17},{"type":"paragraph","text":"para irritá-lo, para que ele caia em alguma armadilha. Diminui-lhe ao máximo as forças, desorientando-o, dizimando-lhe, de vez em quando, alguns","page":17},{"type":"paragraph","text":"soldados, saqueando seus comboios, seus equipamentos e tudo o que te poderá ser útil.","page":17},{"type":"paragraph","text":"Quando tuas tropas tiverem tomado do inimigo mais de dez carros, recompensa prodigamente tanto aqueles que conduziram a operação quanto","page":17},{"type":"paragraph","text":"os que a executaram. Junta esses carros aos teus, depois de eliminar as insígnias inimigas que por ventura nele estejam gravadas.","page":18},{"type":"paragraph","text":"Trata bem os prisioneiros, alimenta-os como se fossem teus próprios soldados. Na medida do possível, faz com que se sintam melhor sob tua égide","page":18},{"type":"paragraph","text":"do que em seu próprio campo, ou mesmo em sua pátria. Jamais os deixes ociosos. Tira partido de seus serviços, com as devidas precauções.","page":18},{"type":"paragraph","text":"Resumindo: conduz-te em relação a eles como se fossem tropas que se tivessem engajado livremente sob teus estandartes. Eis o que chamo ganhar","page":18},{"type":"paragraph","text":"uma batalha e tornar-se mais forte.","page":18},{"type":"paragraph","text":"Se fizeres exatamente o que acabo de indicar, os sucessos acompanharão todos os teus passos, em toda a parte serás vencedor.","page":18},{"type":"paragraph","text":"Pouparás a vida de teus soldados, fortalecerás os antigos domínios de teu país, acrescentando-lhe novos, aumentarás o esplendor e a glória do Estado e,","page":18},{"type":"paragraph","text":"tanto o príncipe quanto os súditos, te serão gratos pela doce tranqüilidade na qual correm doravante os seus dias.","page":18},{"type":"paragraph","text":"Na guerra, o essencial é a vitória e não campanhas prolongadas.","page":18},{"type":"paragraph","text":"O general que domina a arte da guerra é o árbitro do destino do povo e dos rumos da vitória.","page":18},{"type":"paragraph","text":"Que objetos podem ser mais dignos de tua atenção e de todos os teus esforços?","page":18},{"type":"heading","id":"h_suntzu_5","lvl":1,"title":"Capítulo III — Da Arte de Vencer sem Desembainhar a Espada","page":19},{"type":"paragraph","text":"CAPÍTULO lII","page":19},{"type":"paragraph","text":"DA ARTE DE VENCER SEM DESEMBAINHAR A ESPADA","page":19},{"type":"paragraph","text":"Sun Tzu diz: Eis algumas máximas de que deves impregnar-te antes de pensar em sitiar cidades ou ganhar batalhas.","page":19},{"type":"paragraph","text":"Conservar os domínios e todos os direitos do príncipe que serves deve ser o primeiro de teus cuidados. Só deves ampliá-Ios, usurpando o território","page":19},{"type":"paragraph","text":"inimigo, quando for imprescindível.","page":19},{"type":"paragraph","text":"Deves ocupar-te principalmente em assegurar a tranqüilidade das cidades de teu próprio país. Perturbar as cidades inimigas deve ser a hipótese","page":19},{"type":"paragraph","text":"mais desfavorável.","page":19},{"type":"paragraph","text":"Deves pensar em colocar ao abrigo todos os vilarejos amigos. Somente a necessidade pode arrastar-te a irromper nos vilarejos Inimigos.","page":19},{"type":"paragraph","text":"Deves impedir que os vilarejos e as choças dos camponeses sofram qualquer dano. Só uma extrema penúria pode levar-te a saquear e a devastar","page":19},{"type":"paragraph","text":"as instalações agrícolas de teus inimigos.","page":19},{"type":"paragraph","text":"Deves almejar como aquilo que há de mais perfeito, conservar intatos os domínios dos inimigos. Só deves destruí-Ias em caso de extrema necessidade.","page":19},{"type":"paragraph","text":"Se um general age assim, sua conduta ombreará com a dos mais virtuosos personagens. Ela se espelhará no Céu e na Terra, cujas obras buscam a","page":19},{"type":"paragraph","text":"produção e a conservação e não a destruição.","page":19},{"type":"paragraph","text":"Se essas máximas estiverem bem gravadas em teu coração, garanto o teu sucesso.","page":19},{"type":"paragraph","text":"Repito: a melhor política guerreira é tomar um Estado intato; uma política inferior consiste em arruiná-Io.","page":19},{"type":"paragraph","text":"É preferível aprisionar a destruir o exército inimigo; é melhor tomar um batalhão intato do que fulminá-Io.","page":19},{"type":"paragraph","text":"Cem combates tivesses que travar, cem vitórias seriam teu fruto.","page":19},{"type":"paragraph","text":"Não procures vencer teus inimigos à custa de combates e de vitórias.","page":19},{"type":"paragraph","text":"Esse é um caso em que o \"bom\" é melhor do que o \"excelente\". Quanto mais te elevares acima do \"bom\", mais te aproximarás do \"pernicioso\" e do \"ruim\".","page":19},{"type":"paragraph","text":"É preferível subjugar o inimigo sem travar combate. Nesse caso, quanto mais te elevares acima do bom, mais te aproximarás do incomparável e do","page":20},{"type":"paragraph","text":"excelente.","page":20},{"type":"paragraph","text":"Os grandes generais vencem descobrindo todos os artifícios do inimigo, sabotando-Ihes os projetos, semeando a discórdia entre seus partidários,","page":20},{"type":"paragraph","text":"mantendo-o sempre acossado, interceptando reforços estrangeiros, e impedindo-o de tomar qualquer decisão mais vantajosa para ele.","page":20},{"type":"paragraph","text":"Sun Tzu diz: é de suprema importância na guerra atacar a estratégia do inimigo.","page":20},{"type":"paragraph","text":"Sobressai-se em resolver as dificuldades quem as resolve antes que apareçam.","page":20},{"type":"paragraph","text":"Sobressai-se na conquista quem conquista o troféu antes que os temores de seu inimigo se concretizem.","page":20},{"type":"paragraph","text":"Ataca a estratégia do adversário na raiz. Depois, rompe suas alianças.","page":20},{"type":"paragraph","text":"Em seguida, ataca seu exército.","page":20},{"type":"paragraph","text":"A pior política consiste em atacar as cidades. Apenas consente nisso se não houver outra saída. Pensa no longo tempo necessário para preparar","page":20},{"type":"paragraph","text":"veículos, armas, equipamentos, e para construir rampas ao longo das muralhas.","page":20},{"type":"paragraph","text":"Se fores obrigado a sitiar uma cidade e a destruí-Ia, dispõe de tal sorte teus veículos, escudos e todas as máquinas necessárias para o assalto, para","page":20},{"type":"paragraph","text":"que tudo esteja pronto quando chegar a hora de atacar.","page":20},{"type":"paragraph","text":"Age para que a rendição não se prolongue por mais de três meses.","page":20},{"type":"paragraph","text":"Quando este prazo expirar, se ainda não tiveres atingido teus objetivos, certamente terás cometido alguns erros. Empenha-te em repará-Ios.","page":20},{"type":"paragraph","text":"Partindo para o assalto, à frente de tuas tropas, redobra os esforços.","page":20},{"type":"paragraph","text":"Imita a vigilância, a diligência, o entusiasmo e a tenacidade das formigas.","page":20},{"type":"paragraph","text":"Suponho que terás construído antecipadamente as trincheiras e outras obras necessárias, que terás edificado fortes para descobrir o que se passa no","page":20},{"type":"paragraph","text":"interior da cidade sitiada, e terás contornado todos os inconvenientes que tua prudência te recomenda. Apesar de todas essas precauções, se de três partes","page":20},{"type":"paragraph","text":"de teus soldados tiveres a infelicidade de perder uma, sem poderes alardear vitória, convence-te de que não atacaste bem.","page":20},{"type":"paragraph","text":"Um hábil general jamais se encontrará reduzido a tais extremos. Ele conhece a arte de humilhar os seus inimigos sem travar batalhas.","page":21},{"type":"paragraph","text":"Sem derramar uma gota de sangue, sem mesmo desembainhar a espada, consegue tomar as cidades.","page":21},{"type":"paragraph","text":"Sem colocar os pés em reinos estrangeiros, descobre o meio de conquistá-Ios.","page":21},{"type":"paragraph","text":"Sem operações prolongadas e sem perder um tempo considerável à testa de suas tropas, conquista uma glória imortal para seu príncipe,","page":21},{"type":"paragraph","text":"assegurando a felicidade de seus compatriotas e fazendo com que o universo lhe seja reconhecido pelo repouso e pela paz conquistados.","page":21},{"type":"paragraph","text":"Esse é o alvo que todos os comandantes devem buscar incessantemente e sem jamais esmorecer.","page":21},{"type":"paragraph","text":"O objetivo de um general hábil é apoderar-se do reino inimigo quando este está intato; assim suas tropas não se esgotarão e seu triunfo será","page":21},{"type":"paragraph","text":"completo. Esta é a arte da estratégia vitoriosa.","page":21},{"type":"paragraph","text":"Há uma infinidade de situações diferentes em que podes te encontrar em relação ao inimigo. Nem todas poderiam ser previstas de antemão; logo,","page":21},{"type":"paragraph","text":"evito maiores detalhes. Tua clarividência e tua experiência te sugerirão o que deves fazer, à medida que as circunstâncias se apresentem. Entretanto, vou","page":21},{"type":"paragraph","text":"dar-te alguns conselhos gerais, que poderás usar, se necessário.","page":21},{"type":"paragraph","text":"Se fores dez vezes mais numeroso que o inimigo, cerca-o de todos os lados; não deixes nenhuma passagem livre; age de forma que ele não possa","page":21},{"type":"paragraph","text":"evadir-se para acampar em outra parte, nem receber qualquer socorro.","page":21},{"type":"paragraph","text":"Se teu contingente for cinco vezes superior, dispõe teu exército de forma que ele possa atacar pelos quatro flancos simultaneamente, no momento","page":21},{"type":"paragraph","text":"oportuno.","page":21},{"type":"paragraph","text":"Se tens o dobro da força do inimigo, contenta-te em dividir teu exército em dois.","page":21},{"type":"paragraph","text":"Mas se, em ambas as partes, a quantidade de guerreiros é a mesma, só te resta aventurar-te ao combate.","page":21},{"type":"paragraph","text":"Se fores inferior, fica alerta. O menor erro pode ser fatal. Tenta colocar- te a salvo, e evita, se possível, entrar em choque com o adversário. A","page":21},{"type":"paragraph","text":"prudência e a firmeza de um punhado de pessoas pode conseguir extenuar e dominar mesmo um exército numeroso. Assim, és ao mesmo tempo capaz de","page":21},{"type":"paragraph","text":"te proteger e de obter uma vitória completa.","page":22},{"type":"paragraph","text":"Quem está à testa dos exércitos é o sustentáculo do Estado. Se agir corretamente, o reino será próspero. Ao contrário, se o comandante não tiver","page":22},{"type":"paragraph","text":"as qualidades necessárias para desempenhar dignamente seu cargo, o reino sofrerá inelutavelmente as conseqüências e talvez fique à beira do abismo.","page":22},{"type":"paragraph","text":"Um general só pode servir bem o Estado de um único modo, mas pode arruiná-Io de diversas maneiras.","page":22},{"type":"paragraph","text":"É preciso muito esforço e uma conduta calcada na bravura e na prudência para ser vitorioso: um só passo em falso põe tudo a perder. Um","page":22},{"type":"paragraph","text":"general pode cometer muitos erros. Se engajar as tropas no momento errado, fará com que ataquem quando não convém. Se não tem um conhecimento","page":22},{"type":"paragraph","text":"exato dos lugares onde deve conduzi-Ias; se lhes impõe acampamentos desastrosos; se as cansa inutilmente; se ordena que retrocedam sem","page":22},{"type":"paragraph","text":"necessidade; se ignora as necessidades dos que integram seu exército; se desconhece a ocupação a que cada um se dedicava antes de se alistar, a fim","page":22},{"type":"paragraph","text":"de tirar partido do talento individual de cada um; se desconhece o ponto forte e o fraco de seus subordinados; se não conta com a fidelidade dos mesmos; se","page":22},{"type":"paragraph","text":"não impõe a mais estrita disciplina; se carece do talento de bem governar; se é irresoluto e vacilante nas ocasiões em que urge ter pulso firme; se não","page":22},{"type":"paragraph","text":"recompensa adequadamente seus soldados quando de direito; se permite que estes sejam humilhados sem motivo pelos oficiais; se não sabe impedir as","page":22},{"type":"paragraph","text":"dissensões entre os chefes, um general que cometer tais erros tornará o exército capenga, esgotará homens, víveres e o reino, e se tornará a vítima","page":22},{"type":"paragraph","text":"infame de sua própria imperícia.","page":22},{"type":"paragraph","text":"Sun Tzu diz: No comando dos exércitos há sete males cruciais:","page":22},{"type":"paragraph","text":"I. Executar cegamente ordens tomadas na Corte, segundo o arbítrio do príncipe, sem se ater às circunstâncias.","page":22},{"type":"paragraph","text":"II. Tornar os oficiais confusos, despachando emissários que ignoram os assuntos militares.","page":22},{"type":"paragraph","text":"III. Misturar regras próprias à ordem civil e à ordem militar.","page":22},{"type":"paragraph","text":"IV. Confundir o rigor necessário ao governo do Estado e a flexibilidade que o comando das tropas requer.","page":22},{"type":"paragraph","text":"V. Dividir a responsabilidade.","page":22},{"type":"paragraph","text":"VI. Disseminar a suspeita, que engendra a desordem: um exército confuso conduz à vitória do inimigo.","page":23},{"type":"paragraph","text":"VII. Aguardar ordens em todas as circunstâncias. Isso equivale a esperar autorização de um superior para apagar o fogo: antes","page":23},{"type":"paragraph","text":"que a ordem chegue, as cinzas já estarão frias. No entanto, está escrito no código que se deve consultar o inspetor nesse assunto!","page":23},{"type":"paragraph","text":"É como se, ao edificar uma casa na beira de uma estrada, fôssemos pedir conselho aos passantes: o trabalho ainda não","page":23},{"type":"paragraph","text":"estaria terminado.","page":23},{"type":"paragraph","text":"Este é o meu ensinamento.","page":23},{"type":"paragraph","text":"Nomear um general é da alçada do soberano; decidir uma batalha cabe ao general. Um príncipe esclarecido deve escolher o homem que convém,","page":23},{"type":"paragraph","text":"revesti-Io de responsabilidades e aguardar os resultados.","page":23},{"type":"paragraph","text":"Para vencer os inimigos, cinco circunstâncias são necessárias:","page":23},{"type":"paragraph","text":"I. Saber quando combater e quando bater em retirada.","page":23},{"type":"paragraph","text":"II. Saber lidar com o pouco e o muito, segundo as circunstâncias.","page":23},{"type":"paragraph","text":"III. Compor habilmente suas fileiras.","page":23},{"type":"paragraph","text":"Mênsio diz: \"O momento oportuno não é tão importante quanto as vantagens do terreno; e tudo isso não é tão relevante quanto a","page":23},{"type":"paragraph","text":"harmonia das relações humanas\".","page":23},{"type":"paragraph","text":"IV. Preparar-se, prudentemente, para afrontar o inimigo potencial.","page":23},{"type":"paragraph","text":"Não prever, dando como pretexto a inferioridade do adversário, é o maior dos crimes. Estar preparado, independente de qualquer","page":23},{"type":"paragraph","text":"contingência, é a maior das virtudes.","page":23},{"type":"paragraph","text":"V. Evitar as ingerências do soberano em tudo que executar, para a glória de seus exércitos.","page":23},{"type":"paragraph","text":"Esses são os cinco caminhos da vitória.","page":23},{"type":"paragraph","text":"Conhece teu inimigo e conhece-te a ti mesmo; se tiveres cem combates a travar, cem vezes serás vitorioso.","page":23},{"type":"paragraph","text":"Se ignoras teu inimigo e conheces a ti mesmo, tuas chances de perder e de ganhar serão idênticas.","page":23},{"type":"paragraph","text":"Se ignoras ao mesmo tempo teu inimigo e a ti mesmo, só contarás teus combates por tuas derrotas.","page":23},{"type":"heading","id":"h_suntzu_6","lvl":1,"title":"Capítulo IV — Da Arte de Manobrar as Tropas","page":24},{"type":"paragraph","text":"CAPÍTULO IV","page":24},{"type":"paragraph","text":"DA ARTE DE MANOBRAR AS TROPAS","page":24},{"type":"paragraph","text":"Sun Tzu diz: Antigamente, os combatentes aguerridos primeiro se tornavam invencíveis. Depois, aguardavam que o inimigo ficasse vulnerável e","page":24},{"type":"paragraph","text":"jamais se engajavam em guerras que previam ter desfecho desfavorável.","page":24},{"type":"paragraph","text":"Antes de iniciarem o combate, asseguravam-se da vitória. Se a ocasião de investir contra o inimigo não era favorável, aguardavam tempos mais","page":24},{"type":"paragraph","text":"propícios.","page":24},{"type":"paragraph","text":"Tinham como princípio que só se pode ser vencido por erro próprio e que só se atinge a vitória por erro do inimigo.","page":24},{"type":"paragraph","text":"A garantia de nos tornarmos invencíveis está em nossas próprias mãos.","page":24},{"type":"paragraph","text":"Tornar o inimigo vulnerável só depende dele próprio.","page":24},{"type":"paragraph","text":"Conhecer os meios que asseguram a vitória não significa obtê-Ia.","page":24},{"type":"paragraph","text":"Assim, os hábeis generais sabiam primeiramente o que deviam temer ou esperar, e avançavam ou recuavam, lutavam ou se entrincheiravam, segundo o","page":24},{"type":"paragraph","text":"conhecimento que tinham, tanto a respeito das próprias tropas quanto das do inimigo. Acreditando-se superiores, não hesitavam em tomar a iniciativa.","page":24},{"type":"paragraph","text":"Acreditando-se inferiores, batiam em retirada e ficavam na defensiva.","page":24},{"type":"paragraph","text":"A invencibilidade está na defesa; a possibilidade de vitória, no ataque.","page":24},{"type":"paragraph","text":"Quem se defende mostra que sua força é insuficiente; quem ataca, mostra que é abundante.","page":24},{"type":"paragraph","text":"A arte de manter-se na defensiva não iguala a de combater com sucesso.","page":24},{"type":"paragraph","text":"Os generais hábeis na defesa devem esconder-se no âmago da terra.","page":24},{"type":"paragraph","text":"Os que querem brilhar no ataque devem elevar-se aos céus. Para colocar-se na defensiva contra o inimigo, é preciso esconder-se no seio da terra, como os","page":24},{"type":"paragraph","text":"veios d'água que não se sabe de onde manam e cuja ramificações são insondáveis. Assim, ocultarás todas as tuas diligências, e serás impenetrável.","page":24},{"type":"paragraph","text":"Aqueles que combatem devem elevar-se nas alturas; ou seja, devem combater de tal forma que o universo inteiro vibre com o estrépito de sua glória.","page":24},{"type":"paragraph","text":"Em ambos os casos, deve-se visar à própria integridade física.","page":24},{"type":"paragraph","text":"Deves procurar conhecer a arte de vencer dos que trilharam esse caminho com honra. Querer suplantar a todos, e procurar requintar-se nas","page":25},{"type":"paragraph","text":"artes militares, significa correr o risco de não igualar os grandes mestres, significa expor-se a ficar infinitamente aquém pois, nesse caso, o ótimo é","page":25},{"type":"paragraph","text":"inimigo do bom.","page":25},{"type":"paragraph","text":"Conseguir vitórias por meio de combates foi considerado em todos os tempos, pelo universo inteiro, como algo bom. Ouso dizer-te, todavia, que esse","page":25},{"type":"paragraph","text":"é mais um caso em que o \"excelente\" geralmente é pior que o \"ruim\". Predizer uma vitória que o vulgo pode prever, e ser considerado universalmente sábio,","page":25},{"type":"paragraph","text":"não significa ter habilidade bélica. Pois não requer muita força levantar a penugem dos coelhos no outono. Não são necessários olhos penetrantes para","page":25},{"type":"paragraph","text":"distinguir o sol da lua. Nem se requer ouvido apurado para ouvir o ronco do trovão. Nada mais natural, nada mais fácil, nada mais simples do que isso.","page":25},{"type":"paragraph","text":"Os hábeis guerreiros não encontram dificuldades maiores do que estas nos combates; eles agem de forma que vencem a batalha depois de terem","page":25},{"type":"paragraph","text":"criado as condições apropriadas.","page":25},{"type":"paragraph","text":"Eles prevêem todas as eventualidades. Conhecem a situação do inimigo, conhecem-lhes as forças, e não ignoram o que podem fazer e até onde","page":25},{"type":"paragraph","text":"podem ir. A vitória é uma decorrência natural desse saber.","page":25},{"type":"paragraph","text":"Assim, as vitórias obtidas por um mestre na arte da guerra não lhe garantiriam nem a reputação de sábio, nem o mérito de homem de valor.","page":25},{"type":"paragraph","text":"O homem comum não compreende que uma vitória seja obtida antes que a situação se cristalize.","page":25},{"type":"paragraph","text":"Eis por que o artífice de tal conquista não se reveste, para o vulgo, de nenhuma reputação de sagacidade. Antes que a lâmina de seu gládio se","page":25},{"type":"paragraph","text":"manche de sangue, o Estado inimigo já está subjugado.","page":25},{"type":"paragraph","text":"Antes de desfechar o combate, os mestres antigos procuravam humilhar seus inimigos, mortificavam-nos, fatigavam-nos de mil maneiras. Seus próprios","page":25},{"type":"paragraph","text":"acampamentos eram lugares sempre ao abrigo de toda surpresa, sempre impenetráveis. Esses generais acreditavam que, para vencer, as tropas deviam","page":25},{"type":"paragraph","text":"aspirar ao combate com entusiasmo, e estavam persuadidos que, mesmo quando essas mesmas tropas buscavam com veemência a vitória, geralmente","page":25},{"type":"paragraph","text":"eram vencidas.","page":25},{"type":"paragraph","text":"Por isso, com segurança, ousavam prever a vitória ou a derrota, antes mesmo de terem dado um passo para conquistar a primeira ou evitar a última.","page":26},{"type":"paragraph","text":"Assim eram os nossos ancestrais. Nada lhes era mais fácil do que vencer. Não acreditavam que os elogios derrisórios, como \"corajosos\", \"heróis\"","page":26},{"type":"paragraph","text":"ou \"invencíveis\", fossem um tributo que tivessem merecido. Atribuíam seu sucesso ao cuidado extremo que tinham em evitar o menor deslize.","page":26},{"type":"paragraph","text":"Não cometer erros significa que - faça o que fizer - o general hábil conquistará a vitória. Ele conquista um inimigo já derrotado. Nos planos, jamais","page":26},{"type":"paragraph","text":"um deslocamento inútil; na estratégia, jamais um passo em vão. O comandante hábil assume uma posição tal que não pode sofrer nenhuma derrota; não","page":26},{"type":"paragraph","text":"negligencia nenhuma circunstância que lhe garanta o controle do inimigo.","page":26},{"type":"paragraph","text":"Um exército vitorioso ganha antes de ter deflagrado a batalha; um exército fadado à derrota combate na esperança de ganhar.","page":26},{"type":"paragraph","text":"Aqueles que são zelosos na arte da guerra cultivam o Tao e aderem à sua doutrina; são, portanto, capazes de formular políticas de vitória.","page":26},{"type":"paragraph","text":"Eles não permitem que as tropas mostrem uma confiança demasiado cega, uma confiança que degenera em presunção. As tropas que sonham com","page":26},{"type":"paragraph","text":"a vitória são tímidas, presunçosas ou debilitadas pela preguiça. Ao contrário, aquelas que, sem pensar na vitória, exigem o combate, são tropas enrijecidas","page":26},{"type":"paragraph","text":"no trabalho, aguerridas, destinadas a vencer.","page":26},{"type":"paragraph","text":"Agora, eis os cinco elementos da arte da guerra:","page":26},{"type":"paragraph","text":"I. A medida do espaço;","page":26},{"type":"paragraph","text":"II. A avaliação das quantidades;","page":26},{"type":"paragraph","text":"III. As regras de cálculo;","page":26},{"type":"paragraph","text":"IV. As comparações;","page":26},{"type":"paragraph","text":"V. As chances de vitória.","page":26},{"type":"paragraph","text":"As medidas do espaço derivam do terreno; as quantidades derivam da medida;","page":26},{"type":"paragraph","text":"os números emanam das quantidades; as comparações decorrem dos números,","page":26},{"type":"paragraph","text":"e a vitória é o fruto das comparações.","page":26},{"type":"paragraph","text":"É pela disposição das forças que um general vitorioso é capaz de levar seus homens ao combate, soerguendo-os ao patamar de águas represadas","page":26},{"type":"paragraph","text":"que, súbito liberadas, mergulham num abismo incomensurável.","page":26},{"type":"paragraph","text":"Tu, que estás à testa dos exércitos, deves tornar-te digno do ofício que exerces. Avalia as medidas que contêm as quantidades, e as que determinam","page":27},{"type":"paragraph","text":"as dimensões: lembra-te das regras de cálculo. Considera os efeitos da balança. A vitória não é senão o fruto de um cálculo exato.","page":27},{"type":"paragraph","text":"As considerações sobre as diferentes medidas te conduzirão ao conhecimento do que a terra pode oferecer de útil para ti. Saberás o que ela","page":27},{"type":"paragraph","text":"produz, e usufruirás sempre seus frutos; não ignorarás os diferentes caminhos que terás que percorrer para atingir, de forma segura, o alvo fixado.","page":27},{"type":"paragraph","text":"Pelo cálculo, estima se o inimigo pode ser atacado, e somente depois mobiliza a população e recruta as tropas. Aprende a distribuir, de forma","page":27},{"type":"paragraph","text":"eqüitativa, munições e provisões. Aprende a nunca cair nos excessos do demais ou do muito pouco.","page":27},{"type":"paragraph","text":"Enfim, se tiveres em mente as vitórias obtidas em épocas remotas, e todas as circunstâncias que a acompanharam, não ignorarás os diversos usos","page":27},{"type":"paragraph","text":"a que serviram, e saberás que vantagens ou prejuízos trouxeram aos próprios vencedores.","page":27},{"type":"paragraph","text":"Um Y ultrapassa um Tchu1. Nos pratos de uma balança, o Y vence o","page":27},{"type":"paragraph","text":"Tchu. Sê para teus inimigos o que o Y é para o Tchu.","page":27},{"type":"paragraph","text":"Depois de uma primeira vantagem, não esmoreças nem dês a tuas tropas um repouso precipitado. Empunha a espada com a mesma rapidez de","page":27},{"type":"paragraph","text":"uma torrente que se precipita de um despenhadeiro. Que teu inimigo não tenha tempo sequer de se dar conta do que está ocorrendo. E só recolhe os louros da","page":27},{"type":"paragraph","text":"vitória quando a derrota completa do inimigo te colocar em condição de fazê-Io com segurança, vagar e tranqüilidade.","page":27},{"type":"paragraph","text":"1 Um Y pesa cerca de 700 gramas; um Tchu não atinge sequer um grama.","page":27},{"type":"heading","id":"h_suntzu_7","lvl":1,"title":"Capítulo V — Do Confronto Direto e Indireto","page":28},{"type":"paragraph","text":"CAPÍTULO V","page":28},{"type":"paragraph","text":"DO CONFRONTO DIRETO E INDIRETO","page":28},{"type":"paragraph","text":"Sun Tzu diz: Comandar muitos é o mesmo que comandar poucos. Tudo é uma questão de organização. Controlar muitos ou poucos é uma mesma e","page":28},{"type":"paragraph","text":"única coisa. É apenas uma questão de formação e sinalizações.","page":28},{"type":"paragraph","text":"Lembra os nomes de todos os oficiais e subalternos. Inscreve-os num catálogo, anotando-lhes o talento e a capacidade individuais, a fim de","page":28},{"type":"paragraph","text":"aproveitar o potencial de cada um, quando tiveres oportunidade. Age de tal forma que todos os que deves comandar estejam persuadidos que teu principal","page":28},{"type":"paragraph","text":"cuidado é preservá-los de toda desgraça.","page":28},{"type":"paragraph","text":"As tropas que farás avançar contra o inimigo devem ser como pedras que arremetes contra ovos. De ti até o inimigo, não deve haver outra diferença","page":28},{"type":"paragraph","text":"senão a do forte ao fraco, do cheio ao vazio.","page":28},{"type":"paragraph","text":"A certeza de sustentar o ataque do inimigo sem sofrer uma derrota baseia-se na combinação de forças diretas e indiretas2 .","page":28},{"type":"paragraph","text":"Utiliza forças diretas para desfechar a batalha, e forças indiretas para consolidá-Ia. Os recursos dos que são hábeis na utilização de forças indiretas","page":28},{"type":"paragraph","text":"são tão infinitos quanto os do céu e da terra, e tão inesgotáveis quanto os mananciais.","page":28},{"type":"paragraph","text":"Ataca a descoberto, mas vence em sigilo. Eis, em poucas palavras, em que consiste a habilidade e a perfeição do comando das tropas. As luzes e as","page":28},{"type":"paragraph","text":"trevas, o aparente e o secreto: eis toda a arte. Aqueles que a possuem assemelham-se ao céu e à terra, cujos movimentos nunca são aleatórios.","page":28},{"type":"paragraph","text":"Assemelham-se aos caudais e aos mares inexauríveis. Mesmo mergulhados nas trevas da morte, podem revi ver. Como o sol e a lua, eles têm um tempo","page":28},{"type":"paragraph","text":"para aparecer, e um tempo para desaparecer. Como as quatro estações, revestem-se de mil nuanças. Só há cinco notas musicais, mas quem jamais","page":28},{"type":"paragraph","text":"ouviu todas as melodias que podem resultar de sua combinação? Só há cinco cores primárias, mas quem jamais viu o espetáculo de todas as cores","page":28},{"type":"paragraph","text":"2 Direta: fixar e distrair. Indireta: irromper onde o golpe não é previsto.","page":28},{"type":"paragraph","text":"matizadas? Só há cinco paladares, mas deles podem resultar infinitos sabores.","page":29},{"type":"paragraph","text":"Quem jamais experimentou todos?","page":29},{"type":"paragraph","text":"Na arte militar, e na do bom comando das tropas, há apenas duas espécies de forças. Suas combinações, entretanto, são ilimitadas. Ninguém","page":29},{"type":"paragraph","text":"pode abarcá-Ias. Essas forças interagem. Assemelham-se, na prática, a uma cadeia de operações interligadas, como anéis múltiplos, ou como a roda em","page":29},{"type":"paragraph","text":"movimento, que não se sabe onde principia nem também onde termina.","page":29},{"type":"paragraph","text":"Na arte militar, cada operação particular tem partes que exigem a luz do dia, e outras que pedem as trevas do segredo. Não posso determiná-Ias de","page":29},{"type":"paragraph","text":"antemão. Só as circunstâncias podem ditá-Ias. Opomos grandes blocos de pedra às corredeiras que queremos represar. Empregamos redes frágeis e","page":29},{"type":"paragraph","text":"miúdas para capturar pequenos pássaros. Entretanto, o caudal rompe algumas vezes seus diques, após tê-Ios minado aos poucos, e os pássaros, as peias","page":29},{"type":"paragraph","text":"que os aprisionam, à força de se debaterem.","page":29},{"type":"paragraph","text":"É por seu ímpeto que a água das torrentes corrói os rochedos. É regulando a distância que o falcão se orienta para estraçalhar a presa.","page":29},{"type":"paragraph","text":"Possuem verdadeiramente a arte de bem comandar aqueles que souberam e sabem potencializar sua força, que adquiriram uma autoridade","page":29},{"type":"paragraph","text":"ilimitada, que não se deixam abater por nenhum acontecimento, por mais desagradável que seja; que nunca agem com precipitação; que se conduzem,","page":29},{"type":"paragraph","text":"mesmo quando surpreendidos, com o sangue-frio que têm habitualmente nas ações meditadas e nos casos previstos antecipadamente, e agem sempre com","page":29},{"type":"paragraph","text":"a rapidez, fruto da habilidade, aliada a uma longa experiência. Assim, o ímpeto de quem é hábil na arte da guerra é irrefreável, e seu ataque é regulado com","page":29},{"type":"paragraph","text":"precisão.","page":29},{"type":"paragraph","text":"O potencial desse tipo de guerreiro é como o dos arcos retesados. Tudo verga sob seus golpes, tudo é derribado. Como um globo que apresenta","page":29},{"type":"paragraph","text":"perfeita esfericidade em todos os pontos de sua superfície, eles são igualmente resistentes em toda a parte; em todos os pontos, sua energia é a mesma. No","page":29},{"type":"paragraph","text":"auge de uma confusão e de uma desordem aparente, sabem conservar uma disciplina de ferro. Fazem brotar a força no seio da fraqueza. Despertam a","page":29},{"type":"paragraph","text":"coragem e a determinação no meio da covardia e da pusilanimidade.","page":29},{"type":"paragraph","text":"Mas saber manter uma ordem impecável, inclusive no meio da desordem, exige profunda reflexão sobre todos os acontecimentos que podem","page":30},{"type":"paragraph","text":"suceder.","page":30},{"type":"paragraph","text":"Transformar a fraqueza em força só é dado àqueles que têm uma energia absoluta e uma autoridade ilimitada. Pela palavra \"força\" não se deve","page":30},{"type":"paragraph","text":"entender \"dominação\", mas sim a faculdade que permite que se transforme em ato tudo aquilo que se propõe. Saber engendrar a coragem e o valor no meio","page":30},{"type":"paragraph","text":"da covardia e da pusilanimidade significa tornar-se herói e, mais do que isso, colocar-se acima dos mais intrépidos.","page":30},{"type":"paragraph","text":"Um comandante hábil busca a vitória baseando-se nas circunstâncias e não a exige de seus subordinados.","page":30},{"type":"paragraph","text":"Por mais maravilhoso que tudo isso pareça, exijo algo mais dos que comandam as tropas: é a arte de manipular o deslocamento dos inimigos.","page":30},{"type":"paragraph","text":"Aqueles que dominam essa arte admirável dispõem de ascendência sobre o próprio exército, de tal forma que manipulam o inimigo sempre que julgarem","page":30},{"type":"paragraph","text":"apropriado. Sabem ser liberais quando convém. Agem da mesma forma em relação aos que querem vencer: dão e o inimigo recebe; abandonam e o","page":30},{"type":"paragraph","text":"inimigo recolhe. Estão prestes a tudo. Aproveitam-se de todas as circunstâncias. Sempre desconfiados, vigiam os subordinados e, desconfiando","page":30},{"type":"paragraph","text":"destes também, não descuram de nenhum meio que lhes possa ser útil.","page":30},{"type":"paragraph","text":"Consideram os homens que devem combater como pedras ou troncos que tivessem que despencar de um penhasco.","page":30},{"type":"paragraph","text":"A pedra e a madeira não têm movimento próprio. Uma vez em repouso, não se mexem por si mesmos, mas seguem o movimento recebido. Se são","page":30},{"type":"paragraph","text":"quadrados, mantêm-se parados. Se redondos, rolam até encontrar uma resistência mais forte do que a força recebida.","page":30},{"type":"paragraph","text":"Age de forma que o inimigo seja, entre tuas mãos, como uma pedra redonda que terias que precipitar de um penhasco: a força necessária é","page":30},{"type":"paragraph","text":"insignificante; os resultados, espetaculares. É nesse ponto que se reconhecerá tua força e autoridade.","page":30},{"type":"heading","id":"h_suntzu_8","lvl":1,"title":"Capítulo VI — Do Cheio e do Vazio","page":31},{"type":"paragraph","text":"CAPÍTULO VI","page":31},{"type":"paragraph","text":"DO CHEIO E DO VAZIO","page":31},{"type":"paragraph","text":"Sun Tzu diz: Uma das tarefas essenciais que deves realizar antes do combate é escolher criteriosamente o terreno do campo de batalha. Para isso,","page":31},{"type":"paragraph","text":"é preciso agir rápido. Não permitas que o inimigo tome a dianteira. Ocupa o terreno antes que ele tenha tempo de te reconhecer, antes mesmo que ele","page":31},{"type":"paragraph","text":"possa estar ciente de tua marcha. Qualquer negligência nesse sentido pode ter conseqüências nefastas. Em geral, só há desvantagem em ocupar o terreno","page":31},{"type":"paragraph","text":"depois do adversário.","page":31},{"type":"paragraph","text":"O comandante de um exército não deve se fiar em ninguém para uma escolha de tal relevância. Ele deve fazer algo mais. Se for verdadeiramente","page":31},{"type":"paragraph","text":"hábil, escolherá tanto o próprio local do acampamento quanto controlará todos os movimentos do inimigo.","page":31},{"type":"paragraph","text":"Quem consegue fazer com que o inimigo venha espontaneamente oferece-lhe alguma vantagem. Quem deseja impedi-Io, prejudica-o. Um grande","page":31},{"type":"paragraph","text":"general não é arrastado ao combate; ao contrário, sabe impô-Io ao inimigo. Se quiseres que o inimigo marche, de livre e espontânea vontade, para lugares","page":31},{"type":"paragraph","text":"aonde queres precisamente atraí-Io, procura dirimir todas as dificuldades e suspender todos os obstáculos; pois deves prever que, alarmado pelo temor,","page":31},{"type":"paragraph","text":"ou pelos inconvenientes demasiado evidentes, ele renuncie a seu projeto.","page":31},{"type":"paragraph","text":"A grande sabedoria é obter do adversário tudo o que desejas, fazendo com seus atos redundem em benefícios para ti.","page":31},{"type":"paragraph","text":"Decidido o lugar de teu acampamento e o do inimigo, espera tranqüilamente que ele faça as primeiras movimentações. Mas, aguardando,","page":31},{"type":"paragraph","text":"procura aguçar-lhe a fome no meio da abundância; submetê-Io ao barulho quando ele descansa, e angustiá-Io quando está tranqüilo.","page":31},{"type":"paragraph","text":"Se, depois de esperar muito tempo, observas que o inimigo não se dispõe a sair de seu campo, sai do teu. Mediante teu movimento, provoca o","page":31},{"type":"paragraph","text":"dele. Alarma-o freqüentemente. Procura induzi-Io a cometer alguma imprudência da qual poderás tirar proveito.","page":31},{"type":"paragraph","text":"Quando vigiares, vigia atentamente: não durmas. Quando avançares, avança resolutamente, trilhando com segurança caminhos que só tu conheces.","page":31},{"type":"paragraph","text":"Desloca-te para lugares onde o inimigo não desconfie que pretendas ir.","page":32},{"type":"paragraph","text":"Surge de repente onde ele não te aguarda e arremete quando ele menos espera.","page":32},{"type":"paragraph","text":"Para teres certeza de que tomarás posse daquilo que atacas, deves atacar um local desprotegido. Para teres certeza de conservar o que defendes,","page":32},{"type":"paragraph","text":"deves defender um lugar que o inimigo não ataca.","page":32},{"type":"paragraph","text":"Se em tuas marchas e contramarchas percorreste muitas léguas sem sofrer nenhum revés, sem ter sido interceptado nenhuma vez, algumas","page":32},{"type":"paragraph","text":"conclusões se impõem: o inimigo ignora teus projetos; ele tem medo de ti; ou ainda, ele não vigia os postos que podem ser importantes para ele. Evita cair","page":32},{"type":"paragraph","text":"em erro semelhante.","page":32},{"type":"paragraph","text":"A grande arte de um general é fazer com que o inimigo ignore sempre o lugar onde terá que combater, impedindo que conheça os postos relevantes. O","page":32},{"type":"paragraph","text":"general que conseguir isso, e puder, ademais, camuflar todos os seus passos, não é apenas hábil e extraordinário, é um prodígio. Sem ser visto, vê; sem ser","page":32},{"type":"paragraph","text":"ouvido, ouve. Age em silêncio e tem em suas mãos o destino dos inimigos.","page":32},{"type":"paragraph","text":"Uma vez dispostos os exércitos, se não notares um vazio que possa te favorecer, não tentes investir contra os batalhões inimigos. Se, ao fugirem ou","page":32},{"type":"paragraph","text":"recuarem, eles agirem com extrema presteza e de forma ordenada, não os persigas. Perseguindo-os, nunca vás longe demais nem em territórios","page":32},{"type":"paragraph","text":"desconhecidos.","page":32},{"type":"paragraph","text":"Quando pretenderes iniciar o combate, se os inimigos permanecerem em suas trincheiras, não os ataques ali, sobretudo se estiverem bem","page":32},{"type":"paragraph","text":"entrincheirados, ou protegidos por fossos profundos ou por muralhas elevadas.","page":32},{"type":"paragraph","text":"Ao contrário, se pensas que não convém travar combate e queres evitá-Io, permanece em tuas trincheiras, preparando-te para responder ao ataque e","page":32},{"type":"paragraph","text":"realizar algumas ofensivas úteis.","page":32},{"type":"paragraph","text":"Deixa que os inimigos se cansem. Espera que fiquem em desordem ou em pânico. Então, poderás sair e atacá-Ios com vantagem.","page":32},{"type":"paragraph","text":"Jamais dividas os diferentes corpos de teus exércitos. Faz com que possam sempre socorrer-se mutuamente. Por outro lado, faz com que o inimigo","page":32},{"type":"paragraph","text":"se divida ao máximo. Se ele se dividir em dez corpos, ataca cada um deles separadamente com teu exército inteiro. É o verdadeiro método de combater","page":32},{"type":"paragraph","text":"sempre com vantagem. Dessa forma, por menor que seja teu exército, estarás sempre em maioria.","page":33},{"type":"paragraph","text":"Que o inimigo nunca saiba como pretendes combater, nem como vais atacá-Io, ou defender-te. Ignorando tuas intenções, o inimigo fará grandes","page":33},{"type":"paragraph","text":"preparativos, tentará fortalecer-se de todos os lados, dividindo as forças, e isso o levará inevitavelmente à derrocada. Pois, preparando-se na vanguarda, sua","page":33},{"type":"paragraph","text":"retaguarda ficará vulnerável. Preparando-se na retaguarda, sua vanguarda se debilitará. Preparando-se à esquerda, sua direita ficará vulnerável. Preparando-","page":33},{"type":"paragraph","text":"se em todas as direções, ficará vulnerável em todas elas.","page":33},{"type":"paragraph","text":"Quanto a ti, faz exatamente o contrário: que tuas principais forças concentrem-se todas do mesmo lado. Se quiseres atacar de frente, escolhe um","page":33},{"type":"paragraph","text":"setor e coloca à frente de tuas tropas o que tens de melhor. Resiste-se raramente a uma primeira arremetida, pois quem leva a pior, dificilmente se","page":33},{"type":"paragraph","text":"recupera. O exemplo dos valentes é suficiente para encorajar os covardes.","page":33},{"type":"paragraph","text":"Estes seguem facilmente o caminho apontado, mas não poderiam por si mesmos descobri-Ios. Se quiseres atacar pela ala esquerda, concentra todos","page":33},{"type":"paragraph","text":"os teus preparativos desse lado, colocando na ala direita o que tens de mais fraco. Se quiseres vencer pela ala direita, que seja também na ala direita que","page":33},{"type":"paragraph","text":"estejam tuas melhores tropas e toda a tua vigilância.","page":33},{"type":"paragraph","text":"Quem dispõe de poucos homens, deve preparar-se contra o inimigo.","page":33},{"type":"paragraph","text":"Quem tem muitos, deve forçar o inimigo a preparar-se.","page":33},{"type":"paragraph","text":"Isso não é tudo. Assim como é essencial que conheças a fundo o lugar em que deves combater, não é menos importante que saibas o dia, a hora, o","page":33},{"type":"paragraph","text":"momento exato do combate. Trata-se de um cálculo que não convém negligenciar. Se o inimigo está longe de ti, procura informar-te, diariamente, do","page":33},{"type":"paragraph","text":"caminho que ele faz. Segue-o passo a passo, embora em aparência permaneças imóvel em teu campo. Perscruta todos os seus atos, embora teus","page":33},{"type":"paragraph","text":"olhos não possam alcançá-Io. Escuta todos os seus discursos, embora não possas ouvi-Io. Sê testemunha de toda a sua conduta. Penetra mesmo no","page":33},{"type":"paragraph","text":"Íntimo de seu coração, para ali leres os temores e as esperanças recônditas.","page":33},{"type":"paragraph","text":"Tendo pleno conhecimento de todos os projetos, de todos os movimentos, de todas as ações do inimigo, farás com que, a cada dia, ele","page":33},{"type":"paragraph","text":"venha precisamente onde queres que ele venha. Nesse caso, tu o obrigarás a acampar de forma tal que a vanguarda de seu exército não possa receber","page":33},{"type":"paragraph","text":"reforço da retaguarda, que a ala direita não possa ajudar a esquerda, e tu o combaterás assim, no lugar e no momento que estipulares.","page":34},{"type":"paragraph","text":"Antes do dia determinado para o combate, não estejas nem longe nem perto demais do inimigo. O espaço de algumas léguas é o limite mais próximo,","page":34},{"type":"paragraph","text":"e dez léguas inteiras é o maior espaço que deves deixar entre teu exército e o do inimigo.","page":34},{"type":"paragraph","text":"Não procures ter um exército numeroso demais. Amiúde, a excessiva quantidade de gente é mais nociva do que útil. Um pequeno exército bem","page":34},{"type":"paragraph","text":"disciplinado é invencível, sob o comando de um bom general. Para que serviram ao rei de Yue as belas e numerosas coortes de que dispunha, na","page":34},{"type":"paragraph","text":"guerra contra o rei de Wu? Este, com poucas tropas, com um punhado de gente, o venceu, o derrotou, não lhe deixando, de todos os seus Estados,","page":34},{"type":"paragraph","text":"senão a lembrança amarga, e a vergonha eterna por tê-Ios tão mal governado.","page":34},{"type":"paragraph","text":"Digo que a vitória pode ser forjada. Mesmo quando o inimigo é numeroso, posso impedi-Io de iniciar o combate; pois, se ele ignora minha","page":34},{"type":"paragraph","text":"força, posso fazer com que ele se concentre em sua própria preparação: assim, tiro-lhe a tranqüilidade de fazer planos para me derrotar.","page":34},{"type":"paragraph","text":"I. Sonda os planos do inimigo e saberás qual estratégia será coroada de êxito e qual está fadada ao fracasso.","page":34},{"type":"paragraph","text":"II. Perturba o inimigo e faz com que ele revele seus movimentos.","page":34},{"type":"paragraph","text":"III. Descobre a disposição tática do inimigo e faz com que ele exponha seu local de batalha.","page":34},{"type":"paragraph","text":"IV. Coloca-o à prova e descobre onde sua força é pujante e onde é deficiente.","page":34},{"type":"paragraph","text":"V. A suprema tática consiste em dispor as tropas sem forma aparente. Então, os espiões mais penetrantes nada podem","page":34},{"type":"paragraph","text":"farejar, nem os sábios mais experientes poderão fazer planos contra ti.","page":34},{"type":"paragraph","text":"VI. Estabeleço planos para a vitória segundo essas táticas, mas o vulgo tem dificuldades em compreendê-Ias. Todos são capazes","page":34},{"type":"paragraph","text":"de ver os aspectos exteriores, mas ninguém pode compreender o caminho segundo o qual forjei a vitória.","page":34},{"type":"paragraph","text":"VII. Jamais repitas uma tática vitoriosa, mas responde às circunstâncias segundo uma variedade infinita de métodos.","page":34},{"type":"paragraph","text":"Entretanto, se teu exército for pequeno, não vás inadvertidamente medir- te com um exército numeroso. Deves tomar muitas precauções antes de","page":35},{"type":"paragraph","text":"chegar a esse ponto. Quando se tem os conhecimentos de que falei acima, sabe-se quando convém atacar, ou manter-se na defensiva. Sabe-se quando é","page":35},{"type":"paragraph","text":"preciso ficar calmo, e quando é tempo de colocar-se em movimento. Forçado a combater, sabe-se quem vencerá e quem será vencido. Pela simples análise","page":35},{"type":"paragraph","text":"do comportamento dos inimigos, pode-se concluir pela sua vitória ou sua derrota. Repito: se quiseres atacar primeiro, não o faças antes de examinar se","page":35},{"type":"paragraph","text":"tens tudo para triunfar.","page":35},{"type":"paragraph","text":"No momento de deflagrar a ação, perscruta os olhares de teus soldados.","page":35},{"type":"paragraph","text":"Atenta a seus primeiros movimentos. Pelo entusiasmo ou pelo temor que ostentarem, conclui pelo sucesso ou pela derrota. A primeira atitude de um","page":35},{"type":"paragraph","text":"exército prestes. a iniciar o combate é reveladora. Certos exércitos conseguiram retumbantes vitórias, mas teriam sido derrotados caso a batalha","page":35},{"type":"paragraph","text":"tivesse acontecido um dia antes, ou algumas horas depois.","page":35},{"type":"paragraph","text":"As tropas devem ser comparadas à água corrente. Da mesma forma que a água que corre evita as alturas e se precipita nas planícies, assim um","page":35},{"type":"paragraph","text":"exército evita a força e ataca a fraqueza.","page":35},{"type":"paragraph","text":"Se a nascente for elevada, as águas correm rapidamente. Se estiver ao rés do chão, seus movimentos são imperceptíveis. Ao se deparar com algum","page":35},{"type":"paragraph","text":"vazio, a água o preenche, assim que encontra qualquer escoadouro que a favoreça. Se encontrar lugares cheios, tenta naturalmente espraiar-se em","page":35},{"type":"paragraph","text":"outros locais.","page":35},{"type":"paragraph","text":"Ao percorrer as fileiras de teu exército, se notares algum vazio, preenche-o. Se encontrares superabundância, reduz. Se perceberes algo alto","page":35},{"type":"paragraph","text":"demais, abaixa. Se houver algo excessivamente baixo, eleva.","page":35},{"type":"paragraph","text":"Ao longo de seu curso, a água molda-se ao terreno onde corre. Da mesma forma, teu exército deve adaptar-se ao terreno onde se move. A água","page":35},{"type":"paragraph","text":"sem queda não pode correr; tropas mal conduzidas não podem vencer.","page":35},{"type":"paragraph","text":"O general hábil tirará partido de todas as circunstâncias, inclusive as mais perigosas e as mais críticas. Sabe manipular não somente o exército que","page":35},{"type":"paragraph","text":"comanda, mas também o dos inimigos.","page":35},{"type":"paragraph","text":"As tropas, quaisquer que sejam, não têm qualidades constantes que as tornem invencíveis. Os piores soldados podem transformar-se, revelando-se","page":36},{"type":"paragraph","text":"excelentes guerreiros.","page":36},{"type":"paragraph","text":"Segue esse princípio. Não deixes escapar nenhuma oportunidade. Os cinco elementos não se encontram sempre juntos, tampouco são igualmente","page":36},{"type":"paragraph","text":"puros. As quatro estações não se sucedem da mesma maneira a cada ano. O alvorecer e o poente não estão sempre no mesmo ponto do horizonte. Alguns","page":36},{"type":"paragraph","text":"dias são longos; outros, curtos. A lua cresce e decresce e nem sempre é brilhante. Um exército bem comandado e bem disciplinado imita todas essas","page":36},{"type":"paragraph","text":"variedades, apresentando-se multifacetado, em função das circunstâncias e dos inimigos.","page":36},{"type":"heading","id":"h_suntzu_9","lvl":1,"title":"Capítulo VII — Da Arte do Confronto","page":37},{"type":"paragraph","text":"CAPÍTULO VII","page":37},{"type":"paragraph","text":"DA ARTE DO CONFRONTO","page":37},{"type":"paragraph","text":"Sun Tzu diz: Depois de receber do soberano a ordem de manter a campanha, o general deve concentrar as tropas e mobilizar o povo. Ele","page":37},{"type":"paragraph","text":"transforma o exército em um conjunto harmonioso. Depois, esforça-se para instalar as tropas em acampamentos vantajosos, pois isso é essencial para o","page":37},{"type":"paragraph","text":"sucesso de seus projetos e ofensivas. Trata-se de algo cuja execução não é tão fácil quanto se imagina. Amiúde, surgem dificuldades inumeráveis e","page":37},{"type":"paragraph","text":"variadas. É preciso não descurar nenhum detalhe para dirimi-Ias e vencê-Ias.","page":37},{"type":"paragraph","text":"Assim que as tropas estiverem instaladas, deve-se examinar o perto e o longe, as vantagens e as perdas, o trabalho e o repouso, a diligência e a","page":37},{"type":"paragraph","text":"morosidade. Isso significa que é preciso tornar próximo o que está distante, transformar em lucro as próprias perdas, substituir um ócio nocivo por um","page":37},{"type":"paragraph","text":"trabalho útil, converter a lentidão em presteza.","page":37},{"type":"paragraph","text":"É preciso estares perto quando o inimigo acredita que estás longe; teres uma vantagem real quando o inimigo pensa ter-te infringido algumas perdas; te","page":37},{"type":"paragraph","text":"ocupares de algum trabalho útil quando ele acredita que estás paralisado no repouso, e usares todo tipo de diligência quando ele só percebe em ti","page":37},{"type":"paragraph","text":"morosidade. Assim, logrando-o, poderás atacá-lo quando ele menos espera, e sem que ele possa reagir.","page":37},{"type":"paragraph","text":"A arte de utilizar o perto e o longe consiste em manter o inimigo afastado do lugar que escolheste para teu acampamento, e de todos os postos que te","page":37},{"type":"paragraph","text":"parecem relevantes. Essa arte consiste em afastar do inimigo tudo o que lhe poderia ser vantajoso, e em aproximar-te de tudo o que te poderia trazer","page":37},{"type":"paragraph","text":"alguma vantagem. Consiste ainda em te manteres em constante vigilância para não seres surpreendido, e em vigiares incessantemente, para aproveitar o","page":37},{"type":"paragraph","text":"momento azado de surpreender o adversário.","page":37},{"type":"paragraph","text":"Assim, elege uma via indireta e confunde o inimigo, enganando-o. Dessa forma, poderás colocar-te a caminho depois dele e chegar antes. Aquele que","page":37},{"type":"paragraph","text":"for capaz disso, compreende o significado da abordagem direta e indireta.","page":37},{"type":"paragraph","text":"Não te engajes jamais em pequenas ações cujo desfecho é incerto; evita-as, se a elas não fores forçado. Sobretudo, evita te engajares em uma","page":37},{"type":"paragraph","text":"ação geral se não estiveres seguro de uma vitória completa. É muito perigoso precipitar-se em casos semelhantes. Uma batalha travada de forma","page":37},{"type":"paragraph","text":"intempestiva pode arruinar-te completamente. O mínimo que pode acontecer, se o desfecho for duvidoso, ou se obtiveres um sucesso apenas parcial, é ver-","page":38},{"type":"paragraph","text":"te frustrado da maior parte de tuas esperanças e não poderes atingir teus alvos.","page":38},{"type":"paragraph","text":"Antes de te engajares num combate definitivo, é preciso que o tenhas previsto, e te preparado com muita antecipação. Nunca contes com o acaso.","page":38},{"type":"paragraph","text":"Depois de teres decidido começar a batalha, quando os preparativos já estiverem prontos, deixa em lugar seguro os equipamentos ociosos, faz com","page":38},{"type":"paragraph","text":"que teus homens se despojem de tudo o que poderia atrapalhá-los ou sobrecarregá-los. O mesmo vale em relação às armas: que só levem as que","page":38},{"type":"paragraph","text":"eles conseguirem carregar facilmente.","page":38},{"type":"paragraph","text":"Toma precaução, quando abandonares teu acampamento na esperança de uma vantagem provável, para que o benefício a alcançar supere as","page":38},{"type":"paragraph","text":"provisões que terás seguramente abandonado.","page":38},{"type":"paragraph","text":"Se o caminho a percorrer é longo, marcha dia e noite; dobra o ritmo da marcha; que a elite de tuas tropas esteja à frente. Coloca os mais fracos na","page":38},{"type":"paragraph","text":"retaguarda.","page":38},{"type":"paragraph","text":"Prevê tudo, dispõe de tudo. E cai sobre o inimigo quando ele crê que estás muito distante: nesse caso, anuncio-te a vitória.","page":38},{"type":"paragraph","text":"Mas se o inimigo estiver a cem léguas e só avançares cinqüenta, e ele, por sua vez, tiver avançado em número igual, deves calcular da seguinte","page":38},{"type":"paragraph","text":"forma: em dez possibilidades, há cinco de seres derrotado; em três, há duas de seres vitorioso. Se o inimigo descobre que vais combatê-Io quando te restam","page":38},{"type":"paragraph","text":"apenas trinta léguas para alcançá-Io, é difícil que ele possa tomar todas as providências e se preparar adequadamente, no tempo que lhe resta.","page":38},{"type":"paragraph","text":"Assim que chegares, não proteles o ataque, sob pretexto de permitir que teus homens descansem. Inimigo surpreendido é inimigo meio vencido. O","page":38},{"type":"paragraph","text":"mesmo não acontece se ele tiver tempo de reagir. Em seguida, talvez ele encontre recursos para escapar ou até para te derrotar.","page":38},{"type":"paragraph","text":"Não negligencies nada do que pode contribuir para a disciplina, a saúde e a segurança de teus soldados. Zela para que suas armas estejam sempre em","page":38},{"type":"paragraph","text":"bom estado. Faz com que os víveres sejam saudáveis e abundantes. Se as tropas estiverem mal armadas, se os víveres escassearem, e se não tiveres","page":38},{"type":"paragraph","text":"previamente todos os suprimentos necessários, dificilmente vencerás.","page":39},{"type":"paragraph","text":"Busca entendimento secreto com os ministros estrangeiros, e mantém-te informado dos projetos dos príncipes aliados ou vassalos. Informa-te também","page":39},{"type":"paragraph","text":"das boas ou más intenções dos conselheiros do príncipe, pois tais indivíduos podem influenciá-Io na promulgação de ordens e proibições que poderiam","page":39},{"type":"paragraph","text":"contrariar teus objetivos e neutralizar todos os teus esforços.","page":39},{"type":"paragraph","text":"Tua prudência e teu valor não poderiam resistir, por muito tempo, às intrigas de conselheiros mal-intencionados. Para contornar esse inconveniente,","page":39},{"type":"paragraph","text":"consulta-os em certas ocasiões, fingindo necessitar de sua opinião. Transforma todos os amigos deles em teus amigos. Jamais tenhas pendência com esses","page":39},{"type":"paragraph","text":"bajuladores. Cede nas pequenas coisas. Em suma: mantém a união mais estreita possível.","page":39},{"type":"paragraph","text":"Conhece perfeitamente o meio que te cerca. Sabe onde pode se deparar com floresta, bosque, rio, terreno árido e pedregoso, pântano, montanha,","page":39},{"type":"paragraph","text":"colina, morro, vale, precipício, desfiladeiro, planície, enfim, tudo o que pode servir ou prejudicar as tropas que comandas. Se não puderes informar-te","page":39},{"type":"paragraph","text":"pessoalmente da vantagem ou desvantagem do terreno, procura guias locais que te informem com segurança.","page":39},{"type":"paragraph","text":"A força militar baseia-se na dissimulação.","page":39},{"type":"paragraph","text":"Movimenta-te quando estiveres em posição vantajosa, e provoca mudanças na situação, dispersando ou concentrando as forças.","page":39},{"type":"paragraph","text":"Há ocasiões em que deves manter-te calmo, em que reinará em teu acampamento uma tranqüilidade semelhante à do interior das mais espessas","page":39},{"type":"paragraph","text":"florestas. Ao contrário, quando precisares fazer movimentos e barulho, imita o fragor do trovão. Se for preciso ficar firme em teu posto, fica imóvel como uma","page":39},{"type":"paragraph","text":"montanha. Se tiveres que sair para pilhar, age rápido como o fogo. Se for preciso ofuscar o inimigo, sê como o relâmpago. Se for preciso esconder teus","page":39},{"type":"paragraph","text":"projetos, sê obscuro como as trevas. Evita movimentos inúteis. Quando decidires enviar algum destacamento, que seja sempre na esperança, ou","page":39},{"type":"paragraph","text":"melhor, na certeza de uma vantagem real. Para evitar os descontentamentos, reparte sempre, de forma meticulosa e justa, todos os despojos.","page":39},{"type":"paragraph","text":"Quem conhece a arte da aproximação direta e indireta será vitorioso. Eis a arte do confronto.","page":39},{"type":"paragraph","text":"A tudo o que acabo de dizer, convém acrescentar a maneira de dar ordens e de fazer com que sejam executadas. Há ocasiões e acampamentos","page":40},{"type":"paragraph","text":"em que a maior parte de teus homens não poderá te ver nem te ouvir. Os tambores, os estandartes e as bandeiras podem substituir tua voz e tua","page":40},{"type":"paragraph","text":"presença. Informa as tropas de todos os códigos que pretendes empregar. Se tiveres que fazer evoluções durante a noite, que o rufar dos tambores seja o","page":40},{"type":"paragraph","text":"emissário de tuas ordens. Ao contrário, se tiveres que agir durante o dia, emprega as bandeiras e os estandartes para transmitir tuas mensagens.","page":40},{"type":"paragraph","text":"Durante a noite, o clamor dos tambores servirá para espalhar o pânico entre teus inimigos e recobrar o ânimo de teus soldados. Durante o dia, o","page":40},{"type":"paragraph","text":"tremular das bandeiras, a multiplicidade de suas evoluções, a diversidade de suas cores e a estranheza do conjunto, ao mesmo tempo que informam teus","page":40},{"type":"paragraph","text":"homens, mantendo-os de prontidão, ocupando-os e distraindo-os, semeiam a dúvida e a perplexidade no seio do inimigo.","page":40},{"type":"paragraph","text":"Assim, além da vantagem de transmitir prontamente tuas ordens ao exército inteiro, no mesmo momento, poderás ainda exasperar teu inimigo,","page":40},{"type":"paragraph","text":"preocupando-o com tuas intenções, angustiando-o com dúvidas sobre a conduta que premeditas, e inspirando-lhe constantes temores.","page":40},{"type":"paragraph","text":"Não permitas que nenhum soldado temerário abandone as fileiras para provocar, sozinho, o inimigo. Raramente tal homem volta são e salvo. Perece","page":40},{"type":"paragraph","text":"pelo vulgo, pela traição, ou fulminado pelas tropas.","page":40},{"type":"paragraph","text":"Quando tuas tropas estiverem bem dispostas, aproveita seu entusiasmo:","page":40},{"type":"paragraph","text":"cabe ao general criar as ocasiões e discernir quando são favoráveis. Mas nem por isso negligencies a opinião dos oficiais, nem desdenhes sua clarividência,","page":40},{"type":"paragraph","text":"sobretudo se tiverem o bem comum como alvo.","page":40},{"type":"paragraph","text":"Pode-se despojar um exército de seu espírito e de sua destreza, da mesma forma que se pode solapar a coragem de seu comandante.","page":40},{"type":"paragraph","text":"De manhã, os espíritos são penetrantes; à tarde, enfraquecem, e, à noite, querem voltar para casa.","page":40},{"type":"paragraph","text":"Mei Yao-tchen afirma que manhã, tarde e noite representam. As fases de uma longa campanha.","page":40},{"type":"paragraph","text":"Portanto, quando atacares o inimigo, escolhe, para fazê-Io com vantagem, o momento em que presumes que ele esteja fragilizado ou","page":40},{"type":"paragraph","text":"esgotado. Terás tomado antes todas as precauções e tuas tropas, descansadas e rápidas, contarão com a vantagem da força e do vigor. Este é o","page":40},{"type":"paragraph","text":"controle do fator moral.","page":41},{"type":"paragraph","text":"Se vires que a ordem reina nas fileiras inimigas, espera que a desordem irrompa. Se a demasiada proximidade das tropas inimigas te perturba ou te","page":41},{"type":"paragraph","text":"incomoda, afasta-te, a fim de recobrares a serenidade. Este é o controle do fator mental.","page":41},{"type":"paragraph","text":"Se percebes que os adversários estão animados, espera que o entusiasmo arrefeça e eles se verguem sob o peso do tédio ou do cansaço.","page":41},{"type":"paragraph","text":"Este é o controle do fator físico.","page":41},{"type":"paragraph","text":"Se fugirem para lugares elevados, não os persigas. Se tu mesmo estiveres em terreno desfavorável, movimenta-te. Não inicies o combate","page":41},{"type":"paragraph","text":"quando o inimigo, com suas bandeiras bem ordenadas, apresenta-se em formações impecáveis. Este é o controle do fator de mudança das","page":41},{"type":"paragraph","text":"circunstâncias.","page":41},{"type":"paragraph","text":"Se, reduzidos ao desespero, os inimigos vêm dispostos a vencer ou a morrer, evita o embate.","page":41},{"type":"paragraph","text":"Deixa uma saída a um inimigo acossado; caso contrário, ele lutará até a morte.","page":41},{"type":"paragraph","text":"Se os inimigos, reduzidos ao extremo, abandonam o acampamento, franqueando uma passagem para acampar em outro local, não os interceptes.","page":41},{"type":"paragraph","text":"Se são ágeis e lestos, não lhes corras ao encalço. Se lhes falta tudo, previne-te de seu desespero.","page":41},{"type":"paragraph","text":"Não te encarnices contra um inimigo derrotado.","page":41},{"type":"paragraph","text":"Eis o que tinha a dizer sobre as diferentes vantagens que deves tentar obter quando, no comando do exército, terás que medir-te com inimigos talvez","page":41},{"type":"paragraph","text":"tão prudentes e valorosos quanto tu. Eles não poderão ser vencidos, a menos que uses os pequenos estratagemas que acabo de indicar.","page":41},{"type":"heading","id":"h_suntzu_10","lvl":1,"title":"Capítulo VIII — Da Arte das Mudanças","page":42},{"type":"paragraph","text":"CAPÍTULO VIII","page":42},{"type":"paragraph","text":"DA ARTE DAS MUDANÇAS","page":42},{"type":"paragraph","text":"Sun Tzu diz: Geralmente o comando dos exércitos cabe ao general, depois que o soberano lhe deu o mandato para mobilizar o povo e recrutar as","page":42},{"type":"paragraph","text":"tropas.","page":42},{"type":"paragraph","text":"I. Conhece o terreno. Se estiveres em lugares pantanosos, passíveis de inundação, cobertos de espessas florestas, cheios","page":42},{"type":"paragraph","text":"de desfiladeiros, inundados, desertos e áridos, ou seja, em lugares onde não poderás obter reforço com facilidade, e onde","page":42},{"type":"paragraph","text":"não terás nenhum apoio, tenta sair o mais rápido possível.","page":42},{"type":"paragraph","text":"Procura instalar tuas tropas em lugar espaçoso e vasto, de onde possam se retirar facilmente e onde tens aliados possam, sem","page":42},{"type":"paragraph","text":"dificuldade, aportar-te a ajuda providencial.","page":42},{"type":"paragraph","text":"II. Evita, com extrema atenção, acampar em lugares isolados. Se a necessidade te obrigar, só permaneças o tempo necessário para","page":42},{"type":"paragraph","text":"escapulir. Toma rapidamente medidas eficazes para safar-te de forma segura e ordenada.","page":42},{"type":"paragraph","text":"III. Encontrando-te em lugares afastados de fontes, riachos ou poços, onde dificilmente encontrarás víveres e forragem, não demores","page":42},{"type":"paragraph","text":"para fugir. Antes de levantar acampamento, observa se o lugar que escolheste está abrigado por alguma montanha, que te","page":42},{"type":"paragraph","text":"colocará a salvo das surpresas do inimigo. Verifica as vias de acesso, e se tens as facilidades necessárias para conseguir","page":42},{"type":"paragraph","text":"víveres e outras provisões. Em caso positivo, não hesites em tomar posse do terreno.","page":42},{"type":"paragraph","text":"IV. Encontrando-te em um campo de morte, busca o combate.","page":42},{"type":"paragraph","text":"Chamo de lugar de morte esses ermos onde não há nenhum recurso, onde se definha inelutavelmente pela insalubridade do","page":42},{"type":"paragraph","text":"ar, onde as provisões mínguam sem esperança de serem repostas; onde as doenças começam a grassar no exército,","page":42},{"type":"paragraph","text":"prenunciando grandes flagelos. Se te encontrares em tais circunstâncias, precipita-te em deflagrar o combate. Asseguro-te","page":42},{"type":"paragraph","text":"que tuas tropas se mostrarão intrépidas no combate. Morrer pela mão do inimigo lhes parecerá suave em comparação com todos","page":43},{"type":"paragraph","text":"os males que as atormentam.","page":43},{"type":"paragraph","text":"V. Se, por acaso ou por erro, teu exército se encontrar em lugares inóspitos, cercado de desfiladeiros, onde o inimigo facilmente","page":43},{"type":"paragraph","text":"poderia colocar emboscadas, de onde seria difícil fugir em caso de perseguição, onde poderiam interceptar teus víveres e armar","page":43},{"type":"paragraph","text":"ciladas nos caminhos, evita com cuidado atacar em tal terreno.","page":43},{"type":"paragraph","text":"Mas, se o inimigo te encurralar em semelhante local, combata até a morte. Não te contentes com uma 'pequena vantagem ou com","page":43},{"type":"paragraph","text":"meia vitória. Isso poderia ser um engodo para te fulminar por completo. Permanece de sobreaviso, mesmo depois de obteres","page":43},{"type":"paragraph","text":"todas as aparências de uma vitória completa.","page":43},{"type":"paragraph","text":"VI. Sabendo que uma cidade, por menor que seja, está bem fortificada e tem munições e víveres em abundância, evita sitiá-Ia.","page":43},{"type":"paragraph","text":"Se só fores informado da situação depois de começado o cerco, não te obstines em prossegui-Io. Corres o risco de ver todas as","page":43},{"type":"paragraph","text":"tuas forças fracassarem contra essa praça, e serás constrangido a abandoná-Ia vergonhosamente.","page":43},{"type":"paragraph","text":"VII. Não desprezes nenhuma pequena vantagem que puderes obter de forma segura e sem nenhuma perda. Essas pequenas","page":43},{"type":"paragraph","text":"vantagens, quando negligenciadas, geram prejuízos irreparáveis.","page":43},{"type":"paragraph","text":"VIII. Antes de pensar em conseguir alguma vantagem, compara-a com o trabalho, a fadiga, as despesas e as perdas humanas e de","page":43},{"type":"paragraph","text":"munições que ela poderá ocasionar. Avalia se poderás conservá-","page":43},{"type":"paragraph","text":"Ia facilmente. Só depois de ponderar é que te decidirás a aproveitar ou a abandonar tal vantagem, guiando-te por uma","page":43},{"type":"paragraph","text":"sábia prudência.","page":43},{"type":"paragraph","text":"IX. Nas ocasiões em que for necessário tomar imediatamente uma decisão, não esperes as ordens do príncipe. Se tiveres que","page":43},{"type":"paragraph","text":"desobedecer ordens recebidas, não hesites, age sem medo. A principal intenção do príncipe que te colocou à frente dos","page":43},{"type":"paragraph","text":"exércitos é venceres o inimigo. Se ele tivesse previsto as circunstâncias em que te encontras, certamente tomaria a","page":43},{"type":"paragraph","text":"decisão que queres tomar.","page":44},{"type":"paragraph","text":"Essas são as nove variáveis ou nove circunstâncias principais que devem te engajar a mudar o comando ou a posição de teu exército, a mudar a","page":44},{"type":"paragraph","text":"situação, a ir ou vir, a atacar ou se defender, a agir ou permanecer em repouso.","page":44},{"type":"paragraph","text":"Um bom general não deve jamais dizer: Aconteça o que acontecer, farei tal coisa. Irei lá, atacarei o inimigo, sitiarei tal praça. Somente as circunstâncias","page":44},{"type":"paragraph","text":"devem ditar a conduta. Ele não deve ater-se a um sistema geral, nem a uma maneira única de comandar. Cada dia, cada ocasião, cada circunstância requer","page":44},{"type":"paragraph","text":"uma aplicação particular dos mesmos princípios. Os princípios são bons em si mesmos; sua aplicação os torna amiúde nefastos.","page":44},{"type":"paragraph","text":"O general deve conhecer a arte das mudanças. Se ele se fixa em um conhecimento vago de certos princípios, em uma aplicação rotineira das regras","page":44},{"type":"paragraph","text":"da arte bélica, se seus métodos de comando são inflexíveis, se examina as situações de acordo com esquemas prévios, se toma suas resoluções de","page":44},{"type":"paragraph","text":"maneira mecânica, é indigno de comandar.","page":44},{"type":"paragraph","text":"Um general é um homem que, pelo nível que ocupa, se encontra acima de uma multidão de outros homens. Por conseguinte, deve saber governar os","page":44},{"type":"paragraph","text":"homens. É preciso que saiba conduzi-Ios. É preciso que esteja verdadeiramente acima deles, não apenas por sua dignidade, mas por seu","page":44},{"type":"paragraph","text":"espírito, por seu saber, por sua capacidade, por sua conduta, por sua firmeza, por sua coragem e por suas virtudes. É preciso que saiba distinguir as","page":44},{"type":"paragraph","text":"vantagens verdadeiras das falsas; as perdas reais das aparentes; que saiba aplicar a arte da compensação e tirar partido de tudo. É preciso que saiba","page":44},{"type":"paragraph","text":"empregar corretamente certos artifícios para enganar o inimigo, e se mantenha sempre alerta para não ser enganado.","page":44},{"type":"paragraph","text":"Um general não deve ignorar nenhuma armadilha que podem lhe colocar. Deve decifrar todos os artifícios do inimigo, quaisquer que sejam, mas","page":44},{"type":"paragraph","text":"nem por isso deve querer adivinhar.","page":44},{"type":"paragraph","text":"Mantém-te de prontidão, vê quando o inimigo chega, perscruta suas atitudes e sua conduta e tira conclusões. Procedendo assim, não corres o risco","page":44},{"type":"paragraph","text":"de te enganares e de seres ludibriado ou vitimado por conjeturas precipitadas.","page":44},{"type":"paragraph","text":"Se não quiseres ser esmagado pela infinidade de trabalhos e sofrimentos, prepara-te sempre para o pior. Trabalha sem cessar para","page":44},{"type":"paragraph","text":"prejudicar o inimigo. Poderás fazê-Io de diferentes formas, mas eis o que há de essencial neste tópico.","page":45},{"type":"paragraph","text":"Lança mão de tudo para corromper seus melhores homens: oferendas, presentes, afeição, nada omitas. Se preciso for, suborna. Engaja pessoas","page":45},{"type":"paragraph","text":"dignas do campo adversário para praticarem ações vergonhosas e indignas de sua reputação, ações das quais elas se envergonharão quando descobertas, e","page":45},{"type":"paragraph","text":"não deixes de divulgá-Ias amplamente.","page":45},{"type":"paragraph","text":"Mantém ligações secretas com os elementos mais corruptos do campo inimigo; serve-te deles para alcançar teus fins, agregando outros corrompidos.","page":45},{"type":"paragraph","text":"Contraria o comando do inimigo, semeia a dissensão entre seus chefes, fornece motivos de cólera a uns contra outros, faz com que murmurem contra","page":45},{"type":"paragraph","text":"seus oficiais, amotina os oficiais subalternos contra seus superiores. Intercepta- lhes víveres e munições. Semeia entre eles melodias voluptuosas para lhes","page":45},{"type":"paragraph","text":"estiolar o coração. Envia-Ihes mulheres para acabar de corrompê-los. Faz com que saiam quando conviria que ficassem acampados, e permaneçam tranqüilos","page":45},{"type":"paragraph","text":"quando urgiria que atacassem. Dissemina ininterruptamente falsos alarmas e falsos avisos. Conquista, para tua causa, os governadores de províncias","page":45},{"type":"paragraph","text":"inimigas. Eis aproximadamente o que deves fazer, se queres ludibriar, usando habilidade e astúcia.","page":45},{"type":"paragraph","text":"Os generais que brilhavam entre os antigos eram homens sábios, previdentes, intrépidos e afeitos ao trabalho. Tinham sempre os sabres à mão.","page":45},{"type":"paragraph","text":"Jamais presumiam que o inimigo não viria, estavam prontos para qualquer eventualidade. Tornavam-se invencíveis e, deparando-se com o inimigo, não","page":45},{"type":"paragraph","text":"necessitavam esperar reforço para bater-se. As tropas que comandavam eram bem disciplinadas, e sempre dispostas a investir, ao primeiro sinal do","page":45},{"type":"paragraph","text":"comandante.","page":45},{"type":"paragraph","text":"Entre eles, a leitura e o estudo precediam a guerra e os preparavam para ela. Defendiam com cuidado suas fronteiras, e fortificavam suas cidades.","page":45},{"type":"paragraph","text":"Não investiam contra o inimigo, quando sabiam que este estava preparado.","page":45},{"type":"paragraph","text":"Atacavam pelo lado mais fraco, quando suas tropas estavam indolentes e ociosas.","page":45},{"type":"paragraph","text":"Antes de terminar este capítulo, devo te prevenir contra cinco defeitos que, embora pareçam inócuos, são perniciosos e representam obstáculos","page":45},{"type":"paragraph","text":"funestos que derrotaram a prudência e a bravura mais de uma vez.","page":45},{"type":"paragraph","text":"I. O primeiro é o entusiasmo excessivo em afrontar a morte, atitude temerária que se honra 'Com o nome de \"coragem\", \"intrepidez\" e","page":46},{"type":"paragraph","text":"\"valor\" mas, no fundo, só merece o de \"covardia\". Um general que se expõe sem necessidade, como se fosse simples soldado, que","page":46},{"type":"paragraph","text":"parece buscar os perigos da morte, que combate e manda combater até o limite, é um homem que merece morrer. É um","page":46},{"type":"paragraph","text":"homem precipitado, incapaz de encontrar recursos para safar-se de um mau momento. É um covarde, incapaz de sofrer o menor revés","page":46},{"type":"paragraph","text":"sem se frustrar, acreditando que tudo está perdido, se não sair exatamente como planejara.","page":46},{"type":"paragraph","text":"II. O segundo perigo é o cuidado exorbitante em conservar a vida.","page":46},{"type":"paragraph","text":"Acreditando-se necessário ao exército inteiro, o general dá mostras de covardia. Não ousa, por essa razão, abastecer-se às custas do","page":46},{"type":"paragraph","text":"inimigo. Tem medo de tudo, até da própria sombra. Hesita, à espera de uma ocasião mais favorável. Perde a que aparece, não","page":46},{"type":"paragraph","text":"toma nenhuma iniciativa. Mas o inimigo, que está sempre à espreita, aproveita-se, fazendo com que um general assim","page":46},{"type":"paragraph","text":"temeroso perca toda a esperança. O adversário o enredará, lhe interceptará o abastecimento e o fará perecer pelo amor demasiado","page":46},{"type":"paragraph","text":"que tinha em preservar a própria vida.","page":46},{"type":"paragraph","text":"III. O terceiro perigo é a cólera. Um general que não sabe se controlar, que não tem império sobre si mesmo, e se deixa arrebatar pela ira","page":46},{"type":"paragraph","text":"ou pela cólera, será ludibriado pelos inimigos. Estes o provocarão, lhe armarão mil emboscadas que sua irascibilidade impedirá de","page":46},{"type":"paragraph","text":"reconhecer, e nas quais infalivelmente cairá.","page":46},{"type":"paragraph","text":"IV. O quarto perigo é a excessiva suscetibilidade. Um general não deve se ofender de forma intempestiva e despropositada. Por","page":46},{"type":"paragraph","text":"querer reparar a honra apenas levemente ofendida, corre o risco de perdê-Ia irremediavelmente. Deve dissimular. Não deve se","page":46},{"type":"paragraph","text":"desencorajar depois de alguns fracassos, nem acreditar que tudo está perdido porque cometeu algum erro ou sofreu algum revés.","page":46},{"type":"paragraph","text":"V. O quinto perigo é a complacência ou a compaixão desmedida em relação aos soldados. Um general que não ousa punir, que fecha","page":46},{"type":"paragraph","text":"os olhos para a desordem, que teme que os seus soldados estejam sempre vergados sob o peso do trabalho, não ousando, por essa","page":46},{"type":"paragraph","text":"razão, impor-Ihes novas tarefas, é um general fadado ao fracasso.","page":47},{"type":"paragraph","text":"Os subordinados devem sempre ser punidos. É preciso que sofram provações. Se quiseres tirar partido do serviço dos soldados,","page":47},{"type":"paragraph","text":"mantém-nos sempre ocupados, não permitas que fiquem ociosos.","page":47},{"type":"paragraph","text":"Pune-os com severidade, mas sem rigor excessivo. Ministra castigos e trabalho, com discernimento.","page":47},{"type":"paragraph","text":"Um general hábil evita todos esses defeitos. Sem procurar desesperadamente viver ou morrer, deve conduzir-se com prudência e","page":47},{"type":"paragraph","text":"coragem, segundo as circunstâncias.","page":47},{"type":"paragraph","text":"Se há justas razões para se encolerizar, que o faça, mas não imite a ferocidade do tigre.","page":47},{"type":"paragraph","text":"Se crê que sua honra está maculada e quer repará-Ia, que siga as regras da sabedoria, e não a suscetibilidade advinda de uma reputação","page":47},{"type":"paragraph","text":"comprometida.","page":47},{"type":"paragraph","text":"Que ame seus soldados e os poupe, mas com moderação.","page":47},{"type":"paragraph","text":"Combatendo, movimentando-se, sitiando cidades, fazendo ofensivas, deve conjugar a astúcia à valentia, a sabedoria à força das armas. Deve saber","page":47},{"type":"paragraph","text":"reparar seus erros, quando tiver a infelicidade de cometê-los, aproveitando todos os erros do inimigo e induzindo-o a cometer outros.","page":47},{"type":"heading","id":"h_suntzu_11","lvl":1,"title":"Capítulo IX — Da Importância da Geografia","page":48},{"type":"paragraph","text":"CAPÍTULO IX","page":48},{"type":"paragraph","text":"DA IMPORTÂNCIA DA GEOGRAFIA","page":48},{"type":"paragraph","text":"Sun Tzu diz: Antes de ordenar o acampamento, informa-te da posição de teus inimigos. Analisa o terreno e escolhe o mais vantajoso. As diferentes","page":48},{"type":"paragraph","text":"situações que encontrarás podem-se reduzir a quatro principais.","page":48},{"type":"paragraph","text":"I. Se estiveres próximo de alguma montanha, procura ocupar o lado que dá para o sol. Essa localização tem grandes vantagens.","page":48},{"type":"paragraph","text":"Estende-te com segurança das encostas até a proximidade dos vales. Ali encontrarás água e forragem em abundância.","page":48},{"type":"paragraph","text":"Rejubilarás com a vista do sol, te aquecerás com seus raios e o ar que respirarás será muito mais saudável do que do outro lado.","page":48},{"type":"paragraph","text":"Se os inimigos irromperem por trás da montanha, informado por sentinelas, fugirás a tempo, se julgares que estás despreparado.","page":48},{"type":"paragraph","text":"Julgando que podes vencer sem muito risco, espera-os resolutamente para combatê-Ios. Entretanto, não combatas em","page":48},{"type":"paragraph","text":"terras elevadas, a menos que sejas obrigado. Sobretudo, nunca persigas o inimigo em terras altas.","page":48},{"type":"paragraph","text":"II. Se estiveres perto de algum rio, aproxima-te o máximo da nascente. Tenta conhecer todos os baixios e vaus. Tendo que","page":48},{"type":"paragraph","text":"cruzar o rio, jamais o atravesses em presença do inimigo. Mas se os inimigos mais intrépidos, ou menos prudentes que tu,","page":48},{"type":"paragraph","text":"arriscarem a travessia, só ataques quando a metade da tropa inimiga estiver do outro lado. Estarás, então, em vantagem de","page":48},{"type":"paragraph","text":"dois contra um. Mesmo nas imediações dos rios, procura sempre os lugares elevados, a fim de descortinares o longe. Não esperes","page":48},{"type":"paragraph","text":"o inimigo perto das margens; não te antecipes. Fica de sobreaviso, temendo que, em caso de surpresa, não possas bater","page":48},{"type":"paragraph","text":"em retirada.","page":48},{"type":"paragraph","text":"III. Se estiveres em lugares escorregadios, úmidos, pantanosos e insalubres, sai o mais rápido possível. Permanecendo, corres","page":48},{"type":"paragraph","text":"muitos riscos. A penúria de víveres e as doenças viriam em breve te assolar. Se fores obrigado a permanecer ali, tenta ocupar as","page":48},{"type":"paragraph","text":"orlas. Evita adentrar-te no terreno. Se houver florestas nas cercanias, situa-te de costas para elas.","page":49},{"type":"paragraph","text":"IV. Se estiveres em planícies, em lugares uniformes e secos, mantém sempre tua esquerda a descoberto. Procura ter na retaguarda","page":49},{"type":"paragraph","text":"alguma elevação, para que teus homens possam descortinar o longe. Quando a vanguarda de teu acampamento se deparar com","page":49},{"type":"paragraph","text":"um exército disposto a matar ou a morrer, toma todas as precauções para que o terreno da retaguarda te ofereça","page":49},{"type":"paragraph","text":"segurança em caso extremo.","page":49},{"type":"paragraph","text":"Estas são as vantagens dos diferentes acampamentos. Vantagens preciosas, de que depende a maior parte dos sucessos militares. Foi por","page":49},{"type":"paragraph","text":"conhecer a fundo a arte dos acampamentos que o Imperador Amarelo derrotou seus inimigos e submeteu todos os príncipes vizinhos de seu Estado.","page":49},{"type":"paragraph","text":"De tudo o que acabo de falar, deve-se concluir que os lugares elevados são em geral mais salutares às tropas do que os lugares baixos e profundos.","page":49},{"type":"paragraph","text":"Mesmo em lugares elevados, cabe acampar sempre do lado do sol, pois é onde encontramos abundância e fertilidade. Um acampamento dessa natureza","page":49},{"type":"paragraph","text":"é um prenúncio de vitória. O contentamento sob céu puro e a saúde, decorrentes de boa alimentação, dão coragem e força ao soldado, ao passo","page":49},{"type":"paragraph","text":"que a tristeza, o descontentamento e as doenças o esgotam, o enervam, o desencorajam.","page":49},{"type":"paragraph","text":"Convém concluir ainda que os acampamentos perto dos rios apresentam tanto vantagens quanto desvantagens que não se devem negligenciar. Repito o","page":49},{"type":"paragraph","text":"que já disse: situa-te na cabeceira do rio, deixa as corredeiras para os inimigos.","page":49},{"type":"paragraph","text":"Perto da nascente, os vaus são mais freqüentes, as águas mais puras e mais saudáveis.","page":49},{"type":"paragraph","text":"Quando as chuvas tiverem formado uma torrente ou tiverem engrossado o caudal cujas margens ocupas, espera algum tempo antes de colocar-te em","page":49},{"type":"paragraph","text":"marcha. Sobretudo, não arrisques a travessia. Espera que as águas retomem a seu curso ordinário. Saberás o momento exato, quando cessar certo rumor","page":49},{"type":"paragraph","text":"surdo, quando não houver mais espumas à tona, e quando a terra ou a areia não mais correrem junto com a água.","page":49},{"type":"paragraph","text":"Quanto a desfiladeiros, lugares pantanosos, escorregadios, estreitos e cobertos de vegetação ou entrecortados por precipícios e rochedos, se a","page":49},{"type":"paragraph","text":"necessidade ou o acaso ali te conduziram, afasta-te o mais rápido possível. Se estiveres longe, o inimigo estará perto. Se fugires, o inimigo te perseguirá e","page":50},{"type":"paragraph","text":"talvez caia nos perigos que acabas de esquivar.","page":50},{"type":"paragraph","text":"Acautela-te também com outros tipos de terreno. Há lugares cobertos de matos e de pequenos bosques. Outros são acidentados, cheios de altos e","page":50},{"type":"paragraph","text":"baixos. Esses lugares prestam-se a emboscadas. O inimigo pode irromper a cada instante, te surpreender, cair sobre ti e te esmagar. Estando longe desses","page":50},{"type":"paragraph","text":"locais, não te aproximes. Estando perto, não te movimentes antes de fazer um reconhecimento em todas as imediações. Se o inimigo vem te atacar, procura","page":50},{"type":"paragraph","text":"enredá-Io no terreno desvantajoso. Quanto a ti, só o ataques quando o vires a descoberto.","page":50},{"type":"paragraph","text":"Enfim, independente de o acampamento ser bom ou ruim, tens que tirar partido do fato. Não fiques ocioso, nem inativo. Decifra todos os movimentos do","page":50},{"type":"paragraph","text":"adversário. Mantém espiões ao longo do caminho, inclusive no acampamento inimigo, e até na tenda do general. Nada negligencies do que pode render-te","page":50},{"type":"paragraph","text":"algo. Atenta a tudo.","page":50},{"type":"paragraph","text":"Se os homens que enviaste para sondar o terreno informarem que, apesar da calmaria, as árvores estão se mexendo, conclui que o inimigo está","page":50},{"type":"paragraph","text":"avançando. Pode ser que queira atacar-te. Prepara-te para enfrentá-Io de maneira adequada. Toma a dianteira.","page":50},{"type":"paragraph","text":"Se te informam que os campos estão cobertos de mato alto, acautela-te.","page":50},{"type":"paragraph","text":"Fica vigilante, prevendo alguma emboscada.","page":50},{"type":"paragraph","text":"Se te dizem que viram bandos de pássaros esvoaçando, desconfia.","page":50},{"type":"paragraph","text":"Espionam-te ou estendem-te armadilhas. Mas se, além dos pássaros, viram ainda grande número de animais correndo assustados pelo campo, como se","page":50},{"type":"paragraph","text":"não tivessem covil, é sinal que os inimigos estão de tocaia.","page":50},{"type":"paragraph","text":"Se te informam que viram ao longe nuvens de poeira elevarem-se nos ares, conclui que os inimigos estão em marcha. Em lugares onde a poeira é","page":50},{"type":"paragraph","text":"baixa e espessa, vem a infantaria. Em lugares onde é menos espessa e mais elevada, aproximam-se a cavalaria e os veículos.","page":50},{"type":"paragraph","text":"Se te advertem que os inimigos estão dispersos e só marcham por pelotões, é indício que tiveram que atravessar algum bosque, que abateram","page":50},{"type":"paragraph","text":"alguma caça, e estão cansados. Estão procurando juntar-se.","page":50},{"type":"paragraph","text":"Se te informam que se avistam no campo pessoas a pé e um vaivém de homens montados, dispersos em pequenos bandos, trata-se de um engodo.","page":51},{"type":"paragraph","text":"Não duvides que os inimigos estão acampados.","page":51},{"type":"paragraph","text":"Deves aproveitar tais indícios, tanto para saber a posição dos inimigos, quanto para sabotar seus projetos, e te precaveres de toda surpresa.","page":51},{"type":"paragraph","text":"Eis outros pontos a que deves atentar:","page":51},{"type":"paragraph","text":"Quando teus espiões infiltrados no território inimigo te informarem que ali falam baixo, de forma misteriosa e agem discretamente, conclui que","page":51},{"type":"paragraph","text":"premeditam uma ação geral e se preparam: avança contra eles sem demora.","page":51},{"type":"paragraph","text":"Eles querem te surpreender, surpreende primeiro.","page":51},{"type":"paragraph","text":"Se, ao contrário, te informam que eles se mostram barulhentos, orgulhosos e altivos em seus discursos, fica certo de que premeditam bater em","page":51},{"type":"paragraph","text":"retirada e não pretendem cair em tuas mãos.","page":51},{"type":"paragraph","text":"Quando te informam que viram grande quantidade de veículos leves preceder o exército inimigo, prepara-te para combater, pois ele avança,","page":51},{"type":"paragraph","text":"decidido a lutar.","page":51},{"type":"paragraph","text":"Não dês ouvidos às propostas de paz ou de aliança que os inimigos poderiam te propor. Pode ser um artifício deles.","page":51},{"type":"paragraph","text":"Se eles fazem marchas forçadas, acreditam correr à vitória. Se vão e vêm, se avançam e recuam, querem induzir-te ao combate. Se, a maior parte","page":51},{"type":"paragraph","text":"do tempo, permanecem inativos, usando suas armas como cajados, estão esfomeados e pensam conseguir algo para sobreviver. Se, passando perto de","page":51},{"type":"paragraph","text":"algum rio, correm todos em debandada a se saciar, estão sedentos. Se não souberam ou não quiseram tirar proveito de uma vantagem, estão exaustos ou","page":51},{"type":"paragraph","text":"temerosos. Se não têm coragem de avançar, embora as circunstâncias o exijam, estão hesitantes, inquietos e temerosos.","page":51},{"type":"paragraph","text":"Além do que acabo de dizer, procura conhecer todos os seus diferentes acampamentos. Poderás conhecê-Ios por intermédio dos pássaros que verás","page":51},{"type":"paragraph","text":"em bando sobrevoando determinados lugares. E se os acampamentos forem freqüentes, poderás concluir que eles têm pouca habilidade no conhecimento","page":51},{"type":"paragraph","text":"dos terrenos. O vôo dos pássaros ou os seus trinados podem indicar a presença de emboscadas.","page":51},{"type":"paragraph","text":"Se fores informado que, no campo inimigo, há muitas festas, que ali se come e bebe em grande algazarra, tranqüiliza-te: é prova infalível de que seus","page":52},{"type":"paragraph","text":"generais não têm autoridade.","page":52},{"type":"paragraph","text":"Se seus estandartes mudam de lugar freqüentemente, é prova de que estão desnorteados e a desordem impera.","page":52},{"type":"paragraph","text":"Se os soldados se juntam em pequenos grupos, cochichando, o general perdeu a confiança de seu exército.","page":52},{"type":"paragraph","text":"Se há excesso de recompensas e de punições, o comando está no limite e em grande desalento.","page":52},{"type":"paragraph","text":"Se o exército chega a ponto de destruir seus pertences e quebrar seus utensílios, é a prova de que está acossado e se baterá até a morte.","page":52},{"type":"paragraph","text":"Se os oficiais subalternos estão inquietos e descontentes, irritando-se por qualquer coisa, é prova de que estão entediados ou exaustos.","page":52},{"type":"paragraph","text":"Se nos diferentes destacamentos matam-se furtivamente cavalos para alimentação, é prova de que as provisões estão no fim.","page":52},{"type":"paragraph","text":"Deves atentar a todas essas atitudes dos inimigos. Tal minúcia nos detalhes pode te parecer supérflua, mas minha intenção é de te prevenir de","page":52},{"type":"paragraph","text":"tudo, e te convencer que nada do que pode contribuir para a vitória é irrelevante. A experiência me ensinou, ela te ensinará também. Desejo que não","page":52},{"type":"paragraph","text":"seja às tuas custas.","page":52},{"type":"paragraph","text":"Mais uma vez, perscruta todos os passos do inimigo quaisquer que sejam. Mas vigia também tuas próprias tropas. Fica de olho em tudo, inteira-te","page":52},{"type":"paragraph","text":"de tudo, impede os roubos, as pilhagens, a devassidão, a embriaguez, os descontentamentos, as intrigas, a preguiça e a ociosidade.","page":52},{"type":"paragraph","text":"Sem precisar que te informem, eis como poderás saber, por ti mesmo, quais dos teus homens incorrem nesses delitos.","page":52},{"type":"paragraph","text":"Se alguns soldados, ao trocarem de posto ou de guarnição, derrubarem algo sem se darem ao trabalho de recolher, se esqueceram algum objeto em","page":52},{"type":"paragraph","text":"seu posto, e não o reclamaram de volta, conclui que são ladrões. Pune-os como tais.","page":52},{"type":"paragraph","text":"Se em teu exército há encontros secretos, se ali amiúde se fala em surdina, se há coisas que não ousam dizer senão a meia voz, conclui que o","page":52},{"type":"paragraph","text":"medo se espalhou entre os soldados, que os descontentamentos virão em seguida e as conspirações não tardarão a eclodir. Apressa-te em restabelecer","page":52},{"type":"paragraph","text":"a ordem.","page":53},{"type":"paragraph","text":"Se tuas tropas parecem pobres, carecendo algumas vezes até do necessário, além do soldo ordinário, distribui algum dinheiro, mas evita ser","page":53},{"type":"paragraph","text":"muito liberal. Geralmente, a abundância de dinheiro é mais funesta do que vantajosa, mais prejudicial do que útil. Pelo abuso a que se presta, torna-se","page":53},{"type":"paragraph","text":"fonte da corrupção e matriz de todos os vícios.","page":53},{"type":"paragraph","text":"Se teus soldados de audaciosos se tornaram tímidos e temerosos, se neles a fraqueza tomou o lugar da força, a baixeza o da magnanimidade, fica","page":53},{"type":"paragraph","text":"certo de que o coração deles se corrompeu. Procura a causa da degradação e extirpa-a pela raiz.","page":53},{"type":"paragraph","text":"Se, sob diversos pretextos, alguns soldados solicitam o desligamento, é porque não têm vontade de combater. Não recuses desligamento a todos. Mas,","page":53},{"type":"paragraph","text":"concedendo-o a vários, que seja em condições infamantes.","page":53},{"type":"paragraph","text":"Se eles vêm em grupos te pedir justiça, com tom sedicioso e colérico, escuta suas razões, leva-as em consideração. Mas, satisfazendo suas","page":53},{"type":"paragraph","text":"reivindicações de um lado, pune-os de forma extremamente severa de outro.","page":53},{"type":"paragraph","text":"Se, quando mandares chamar um subordinado, ele não obedecer prontamente, se custar a acatar tuas ordens e se, após teres terminado de","page":53},{"type":"paragraph","text":"falar, ele não se retirar, desconfia, fica alerta.","page":53},{"type":"paragraph","text":"Em suma, o comando das tropas exige atenção contínua do general.","page":53},{"type":"paragraph","text":"Sem perder de vista o exército inimigo, ele precisa sondar o seu.","page":53},{"type":"paragraph","text":"Informa-te quando o contingente dos inimigos aumenta, informa-te da morte ou deserção de teu mais reles soldado.","page":53},{"type":"paragraph","text":"Se o exército inimigo é inferior ao teu e, por isso, não ousa tomar a iniciativa, vai atacá-lo incontinente, não permitas que ele se fortaleça. Uma","page":53},{"type":"paragraph","text":"única batalha é decisiva nessas ocasiões. Mas se, desconhecendo a situação presente dos inimigos, e sem estar preparado, ousares instigá-Ios para a luta,","page":53},{"type":"paragraph","text":"corres o risco de cair em suas armadilhas, ser batido, e perder-te irremediavelmente.","page":53},{"type":"paragraph","text":"Não mantendo uma disciplina rígida em teu exército, não punindo com rigor a menor infração, em breve deixarás de ser respeitado, teu prestígio se","page":53},{"type":"paragraph","text":"abalará, e os castigos que empregares em seguida, em lugar de coibir os delitos, só servirão para aumentar o número de culpados. Ora, se não és nem","page":53},{"type":"paragraph","text":"temido nem respeitado, se só usufruis de uma frágil autoridade, de que não sabes servir-te sem perigo, como poderás comandar um exército? Como","page":54},{"type":"paragraph","text":"poderás enfrentar os inimigos do Estado?","page":54},{"type":"paragraph","text":"Necessitando punir, age rápido e à medida que as infrações ocorram. Só dês ordens se tiveres certeza de que serás obedecido. Instrui tuas tropas, mas","page":54},{"type":"paragraph","text":"instrui-as adequadamente. Não as aborreças, nem as fatigues sem necessidade. Tudo o que elas podem fazer, para o bem ou para o mal, está em","page":54},{"type":"paragraph","text":"tuas mãos.","page":54},{"type":"paragraph","text":"Na guerra, a superioridade numérica isolada não confere vantagem. Não avances, contando apenas com a força militar. Um exército integrado pelos","page":54},{"type":"paragraph","text":"mesmos homens pode ser irrisório se comandado por determinado general, ou invencível se comandado por outro.","page":54},{"type":"heading","id":"h_suntzu_12","lvl":1,"title":"Capítulo X — Da Topografia","page":55},{"type":"paragraph","text":"CAPÍTULO X","page":55},{"type":"paragraph","text":"DA TOPOGRAFIA","page":55},{"type":"paragraph","text":"Sun Tzu diz: A superfície da Terra apresenta uma variedade infinita de lugares. Deves fugir de uns e buscar outros. Todavia, deves conhecer todos os","page":55},{"type":"paragraph","text":"terrenos com perfeição.","page":55},{"type":"paragraph","text":"Deves evitar os que só oferecem passagens estreitas, que são cercados de escarpas ou precipícios, que não dão acesso fácil aos espaços livres de","page":55},{"type":"paragraph","text":"onde pode chegar reforço. Se fores o primeiro a ocupar tal terreno, bloqueia as passagens e espera o inimigo, não o persigas, a menos que ele tenha","page":55},{"type":"paragraph","text":"bloqueado completamente as passagens. Conhece a fundo o terreno para não engajares teu exército inoportunamente.","page":55},{"type":"paragraph","text":"Procura, ao contrário, um lugar onde há uma montanha suficientemente alta para te abrigar de toda surpresa, onde se pode ir e vir por vários caminhos","page":55},{"type":"paragraph","text":"que deves conhecer perfeitamente, onde há víveres em abundância, onde os mananciais são perenes, o ar é saudável e o terreno em si apresenta muitas","page":55},{"type":"paragraph","text":"vantagens. Tal lugar deve ser objeto de tua mais veemente busca. Mas, seja para apoderar-te de terreno vantajoso, seja para evitar lugares perigosos ou","page":55},{"type":"paragraph","text":"desfavoráveis, usa de extrema diligência, pois o inimigo tem o mesmo objetivo que tu.","page":55},{"type":"paragraph","text":"Se o lugar que desejas está ao alcance tanto do inimigo quanto de ti, se ele pode ocupá-lo tão facilmente quanto tu, toma a dianteira. Para tanto,","page":55},{"type":"paragraph","text":"marcha a noite inteira, mas interrompe a marcha ao amanhecer, se possível sobre um outeiro, para avistar ao longe. Aguarda que cheguem os comboios.","page":55},{"type":"paragraph","text":"Se o inimigo te atacar, enfrenta-o com brio, e poderás obter vantagem.","page":55},{"type":"paragraph","text":"Nunca optes por lugares de fácil acesso mas de saída extremamente difícil. Se o inimigo abandona um terreno assim, ele procura ludibriar-te. Evita","page":55},{"type":"paragraph","text":"avançar, mas engana-o, levantando acampamento. Se ele for imprudente a ponto de seguir-te, será obrigado a atravessar esse terreno escabroso. Quando","page":55},{"type":"paragraph","text":"ele tiver engajado a metade de suas tropas, ataca-o e vencerás sem muito trabalho.","page":55},{"type":"paragraph","text":"Uma vez acampado em terreno vantajoso, espera calmamente que o inimigo tome suas primeiras disposições e se movimente. Se o inimigo","page":55},{"type":"paragraph","text":"avançar, com intenção de lutar, só vás a seu encontro quando perceberes que ele não poderá retroceder facilmente.","page":56},{"type":"paragraph","text":"Um inimigo bem preparado, contra o qual teu ataque fracassou na primeira investida, é perigoso. Não tentes uma segunda ofensiva. Se puderes,","page":56},{"type":"paragraph","text":"retira-te para teu acampamento, e só saias quando tiveres certeza de que não corres perigo. Certamente o inimigo negaceará para te desalojar. Neutraliza","page":56},{"type":"paragraph","text":"todos os artifícios que ele empregar.","page":56},{"type":"paragraph","text":"Se teu rival te precedeu e acampou no lugar em que deverias ter acampado, isto é, no lugar mais vantajoso, não percas tempo querendo","page":56},{"type":"paragraph","text":"desalojá-Io, mediante estratagemas comuns. Teu trabalho será inútil. Se a distância entre ambos é considerável, e os dois exércitos se equivalem, teu","page":56},{"type":"paragraph","text":"inimigo não morderá facilmente as iscas que lhe estenderás para atraí-Io para o combate. Não percas tempo em vão.","page":56},{"type":"paragraph","text":"Adota, por princípio, que teu inimigo empenha-se em obter vantagens com tanta premência quanto tu. Emprega toda tua argúcia para ludibriá-Io.","page":56},{"type":"paragraph","text":"Sobretudo, não o ataques diretamente. Lembra que há diversos modos de enganar e ser enganado. Só te lembrarei dos seis principais, porque são as","page":56},{"type":"paragraph","text":"fontes de todos os outros.","page":56},{"type":"paragraph","text":"O primeiro consiste na marcha das tropas.","page":56},{"type":"paragraph","text":"O segundo, em suas diferentes formações.","page":56},{"type":"paragraph","text":"O terceiro, em sua disposição em lugares pantanosos.","page":56},{"type":"paragraph","text":"O quarto, em sua desordem.","page":56},{"type":"paragraph","text":"O quinto, em seu enfraquecimento.","page":56},{"type":"paragraph","text":"O sexto, em sua fuga.","page":56},{"type":"paragraph","text":"Um general que fracassar, por desconhecer esses estratagemas, se equivoca em acusar o Céu de sua infelicidade. Ele deve atribuir a si mesmo","page":56},{"type":"paragraph","text":"toda a culpa.","page":56},{"type":"paragraph","text":"Se quem comanda os exércitos negligencia conhecer a fundo as tropas que deve levar ao combate e as que deve combater; se não conhece","page":56},{"type":"paragraph","text":"perfeitamente o terreno onde se encontra no momento; nem aquele para onde vai, nem aquele onde se refugiar em caso de revés, nem aquele onde pode","page":56},{"type":"paragraph","text":"simular ir, sem outra intenção senão a de arrastar o inimigo, e se tampouco conhece o terreno onde pode ser forçado a parar, de uma hora para outra; se","page":56},{"type":"paragraph","text":"movimenta seu exército inadvertidamente, se não está informado de todos os movimentos do exército inimigo e dos projetos de seu comandante; se divide","page":56},{"type":"paragraph","text":"suas tropas sem necessidade, sem ser forçado a isso pela natureza do terreno, sem ter previsto todos os inconvenientes que poderiam resultar, ou sem ter","page":57},{"type":"paragraph","text":"certeza de qualquer vantagem real resultante dessa dispersão; se permite que a desordem se insinue aos poucos em seu exército, ou se, baseado em sinais","page":57},{"type":"paragraph","text":"incertos, se persuade com muita facilidade que a desordem reina no exército inimigo, agindo em conseqüência; se o exército definha visivelmente, sem que","page":57},{"type":"paragraph","text":"ele providencie um remédio imediato; tal general será enganado pelos inimigos, que o ludibriarão mediante fugas planejadas, marchas dissimuladas, e por uma","page":57},{"type":"paragraph","text":"série de atos de que o general será a vítima.","page":57},{"type":"paragraph","text":"As máximas seguintes devem te orientar em todas as tuas ações:","page":57},{"type":"paragraph","text":"Se teu exército e o do inimigo se equivalem, é preciso que, de dez partes das vantagens do terreno, nove estejam de teu lado. Aplica-te a fundo,","page":57},{"type":"paragraph","text":"emprega todos os teus esforços e toda a tua argúcia para consegui-Ias.","page":57},{"type":"paragraph","text":"Conseguindo-as, teu inimigo será obrigado a recuar e a bater em retirada assim que apareceres. Se ele for imprudente a ponto de te atacar, tu o","page":57},{"type":"paragraph","text":"combaterás com a vantagem de dez contra um. O contrário acontecerá se, por negligência ou inaptidão, tiveres permitido que ele consiga o que te falta.","page":57},{"type":"paragraph","text":"Em qualquer posição que estiveres, se teus soldados forem fortes e corajosos, mas teus oficiais fracos e covardes, teu exército estará em","page":57},{"type":"paragraph","text":"desvantagem. Ao contrário, se a força e a coragem se concentrarem unicamente nos oficiais, ao passo que a fraqueza e a covardia dominarem o","page":57},{"type":"paragraph","text":"coração dos soldados, teu exército será em breve desbaratado.","page":57},{"type":"paragraph","text":"No primeiro caso, soldados valentes e temerários não quererão se desonrar, e buscarão aquilo que oficiais covardes e tímidos não poderiam lhes","page":57},{"type":"paragraph","text":"dar; no segundo, oficiais valentes e intrépidos com certeza serão desobedecidos por soldados tímidos e covardes.","page":57},{"type":"paragraph","text":"Se os oficiais se irritam com facilidade, se não sabem dissimular nem refrear a cólera, por qualquer motivo que seja, eles se engajarão por conta","page":57},{"type":"paragraph","text":"própria em ações ou em pequenos combates dos quais não se sairão com honra, porque os terão iniciado com precipitação, e não terão previsto todos os","page":57},{"type":"paragraph","text":"inconvenientes e todas as conseqüências. Algumas vezes, agirão inclusive contra a intenção expressa do general, sob diversos pretextos que tentarão","page":57},{"type":"paragraph","text":"tornar plausíveis. É assim que, de uma ação particular, deflagrada irreí1etidamente e contra todas as regras, pode-se chegar a um conflito","page":57},{"type":"paragraph","text":"generalizado, que beneficiará o campo inimigo. Vigia tais oficiais, mantém-nos a teu lado. Por mais qualidades que tenham, eles te causarão enormes","page":58},{"type":"paragraph","text":"prejuízos, talvez até a perda de todo o teu exército.","page":58},{"type":"paragraph","text":"Se um general é pusilânime, não terá a coragem que convém a uma pessoa de seu nível, carecendo do talento essencial de incutir entusiasmo às","page":58},{"type":"paragraph","text":"tropas. Ele lhes solapará a coragem, quando deveria revigorá-Ia. Não poderá instruí-Ias nem prepará-Ias adequadamente. Desdenhará a clarividência, a","page":58},{"type":"paragraph","text":"coragem e a habilidade dos oficiais subalternos. Os próprios oficiais não saberão o quê esperar. Tal general fará com que as tropas executem falsos","page":58},{"type":"paragraph","text":"movimentos, dispondo-as ora de uma forma, ora de outra, sem nenhum sistema, sem nenhum método. Hesitará em todas as circunstâncias, não se","page":58},{"type":"paragraph","text":"decidirá em nenhuma oportunidade, vendo em tudo motivos de temor. Então, a desordem, e uma desordem generalizada, reinará em seu exército.","page":58},{"type":"paragraph","text":"Se um general ignora o ponto fraco e o forte do inimigo que deve combater, se não conhece a fundo o terreno que ele ocupa no momento, nem","page":58},{"type":"paragraph","text":"os que pode ocupar em função das circunstâncias, talvez contraponha ao que há de melhor no exército inimigo o que há de pior no seu; ou escale suas","page":58},{"type":"paragraph","text":"tropas fracas contra tropas inimigas fortes, e tropas aguerridas contra tropas desprezíveis.","page":58},{"type":"paragraph","text":"Em virtude desse desconhecimento, talvez escolha tropas de ,elite para a vanguarda, ataque por onde não convém, deixe perecer, por falta de socorro,","page":58},{"type":"paragraph","text":"seus soldados que estão fora de combate, defenda-se inadequadamente em lugar perigoso, ceda levianamente um posto de extrema importância. Nessas","page":58},{"type":"paragraph","text":"ocasiões, ele contará com alguma vantagem imaginária, que será apenas efeito da astúcia do inimigo, ou então se desencorajará após um fracasso que","page":58},{"type":"paragraph","text":"poderia ser evitado.","page":58},{"type":"paragraph","text":"Desconhecendo o inimigo e o terreno, ele será perseguido sem estar preparado e será enredado. Será combatido sem quartel, dando-se por feliz se","page":58},{"type":"paragraph","text":"puder salvar-se fugindo.","page":58},{"type":"paragraph","text":"Assim, para retomar o tema deste capítulo, um bom general deve conhecer todos os terrenos passíveis de serem o teatro da guerra, tão","page":58},{"type":"paragraph","text":"profundamente quanto conhece os cantos e recantos dos jardins e dos rios de sua propriedade.","page":58},{"type":"paragraph","text":"Repito que o conhecimento exato do terreno é o material essencial de que o general dispõe para arquitetar uma vitória tão relevante para a","page":59},{"type":"paragraph","text":"tranqüilidade e a glória do Estado. Assim, um homem, que o berço ou os acontecimentos destinaram à dignidade de general, deve empregar todos as","page":59},{"type":"paragraph","text":"diligências e envidar todos os esforços para se tornar hábil nessa esfera da arte da guerra.","page":59},{"type":"paragraph","text":"Com o conhecimento exato do terreno, um general pode safar-se das mais críticas circunstâncias. Pode obter a ajuda que lhe falta; impedir que","page":59},{"type":"paragraph","text":"reforços cheguem ao inimigo; avançar, recuar e manipular todos os seus passos, como julgar oportuno. Pode controlar os movimentos do inimigo,","page":59},{"type":"paragraph","text":"obrigando-o a avançar ou a bater em retirada. Pode fustigá-Ia sem medo de ser surpreendido. Pode importuná-Ia de mil maneiras, e neutralizar, a seu turno,","page":59},{"type":"paragraph","text":"todos os danos que ele quiser infringir.","page":59},{"type":"paragraph","text":"Calcular as distâncias e os graus de dificuldade do terreno é controlar a vitória. Aquele que combate com pleno conhecimento desses fatores, vencerá","page":59},{"type":"paragraph","text":"com certeza. Pode acabar ou prolongar a campanha, segundo julgar mais oportuno para sua glória ou para seus interesses.","page":59},{"type":"paragraph","text":"Contarás com a vitória se conheceres os cantos e recantos, os altos e baixos, os acessos e as saídas de todos os lugares que os dois exércitos","page":59},{"type":"paragraph","text":"podem ocupar, do mais próximo ao mais remoto. Com esse conhecimento, saberás como formar os diferentes destacamentos. Saberás, com toda certeza,","page":59},{"type":"paragraph","text":"quando será oportuno combater ou adiar a batalha. Saberás interpretar a vontade do soberano segundo as circunstâncias, quaisquer que sejam as","page":59},{"type":"paragraph","text":"ordens recebidas. Tu o servirás com lealdade, guiando-te por tua clarividência presente. Não contrairás nenhuma mancha que possa arranhar tua reputação,","page":59},{"type":"paragraph","text":"e não estarás exposto a perecer ignominiosamente por ter obedecido.","page":59},{"type":"paragraph","text":"Um general infeliz é sempre um general culpado.","page":59},{"type":"paragraph","text":"Deves ter como objetivo servir teu príncipe, obter vantagens para o","page":59},{"type":"paragraph","text":"Estado e a felicidade dos povos. Executa esse tríplice desiderato e terás atingido o alvo.","page":59},{"type":"paragraph","text":"Em qualquer terreno que estiveres, deves considerar. tuas tropas como crianças que ignoram tudo e não podem dar um passo por si sós. É preciso","page":59},{"type":"paragraph","text":"conduzi-Ias. Deves olhar teus soldados, repito, como se fossem teus próprios filhos. Tu mesmo deves conduzi-Ios. Assim, se tiverem que enfrentar o acaso,","page":59},{"type":"paragraph","text":"não estarão sozinhos, e só o enfrentarão depois de ti. Se tiverem que morrer, morre com eles.","page":60},{"type":"paragraph","text":"Digo que deves amar todos os que estão sob teu comando como se fossem teus filhos. Entretanto, não os transforme em crianças mimadas. Eles","page":60},{"type":"paragraph","text":"se tornariam mimados, se não os corrigisses quando merecessem. Embora cheio de atenção, de deferência e de ternura por eles, se não os dominares,","page":60},{"type":"paragraph","text":"eles se mostrarão insubordinados e reticentes em acatarem tuas ordens.","page":60},{"type":"paragraph","text":"Em qualquer tipo de terreno que estiveres, se o conheceres a fundo, se souberes por onde deves atacar o inimigo, mas se ignorares se ele está","page":60},{"type":"paragraph","text":"vulnerável no momento, ou se está preparado para enfrentar-te, tuas chances de vitória reduzem-se pela metade.","page":60},{"type":"paragraph","text":"Se conheceres perfeitamente todos os terrenos, se souberes que os inimigos podem ser atacados, e de que lado devem sê-Io, se não tiveres","page":60},{"type":"paragraph","text":"indícios seguros de que tuas próprias tropas podem atacar com vantagem, ouso dizer, tuas chances de vitória reduzem-se pela metade.","page":60},{"type":"paragraph","text":"Se estiveres ciente do estado atual dos dois exércitos, se souberes que tuas tropas estão prontas para atacar com vantagem, que as do inimigo são","page":60},{"type":"paragraph","text":"inferiores em força e em número, mas se não conheceres o terreno, ignorarás se és invulnerável ao ataque, asseguro-te, tuas chances de vitória reduzem-se","page":60},{"type":"paragraph","text":"pela metade.","page":60},{"type":"paragraph","text":"Quem é verdadeiramente hábil na arte militar efetua todas as marchas sem desvantagem, todos os movimentos ordenados, todos os ataques","page":60},{"type":"paragraph","text":"certeiros, todas as defesas sem surpresa, todos os acampamentos com critério, todas as retiradas com sistema e método. Conhece as próprias forcas","page":60},{"type":"paragraph","text":"e as do inimigo. Conhece perfeitamente o terreno.","page":60},{"type":"paragraph","text":"Portanto, repito: Conhece-te a ti mesmo, conhece teu inimigo. Tua vitória jamais correrá risco. Conhece o lugar, conhece o tempo. Então, tua vitória será","page":60},{"type":"paragraph","text":"total.","page":60},{"type":"heading","id":"h_suntzu_13","lvl":1,"title":"Capítulo XI — Dos Nove Tipos de Terrenos","page":61},{"type":"paragraph","text":"CAPÍTULO XI","page":61},{"type":"paragraph","text":"DOS NOVE TIPOS DE TERRENOS","page":61},{"type":"paragraph","text":"Sun Tzu diz: Há nove tipos de terrenos que podem ser usados com vantagem ou desvantagem por um ou outro exército.","page":61},{"type":"paragraph","text":"Lugares dispersivos;","page":61},{"type":"paragraph","text":"Lugares leves;","page":61},{"type":"paragraph","text":"Lugares disputados;","page":61},{"type":"paragraph","text":"Lugares de reunião;","page":61},{"type":"paragraph","text":"Lugares cheios e unidos;","page":61},{"type":"paragraph","text":"Lugares com várias saídas;","page":61},{"type":"paragraph","text":"Lugares graves;","page":61},{"type":"paragraph","text":"Lugares deteriorados;","page":61},{"type":"paragraph","text":"Lugares mortíferos.","page":61},{"type":"paragraph","text":"I. Chamo de lugares dispersivos os que se situam perto de nossas fronteiras. Tropas ociosas que permanecem muito tempo na","page":61},{"type":"paragraph","text":"proximidade de seus lares compõem-se de homens que têm mais vontade de perpetuar a raça do que ,se expor à morte. Ao","page":61},{"type":"paragraph","text":"primeiro sinal da aproximação dos inimigos, ou de qualquer batalha iminente, o general não saberá que decisão tomar,","page":61},{"type":"paragraph","text":"quando vir esse grande contingente militar se dissipar e se evaporar, como uma nuvem varrida pelos ventos.","page":61},{"type":"paragraph","text":"II. Chamo lugares leves os que, apesar de próximos das fronteiras, avançam em território inimigo. Nesses lugares é difícil fixar as","page":61},{"type":"paragraph","text":"tropas. Como o retorno é muito fácil, na primeira oportunidade nasce o desejo de retroceder: a inconstância e o capricho aqui","page":61},{"type":"paragraph","text":"vão de par.","page":61},{"type":"paragraph","text":"III. Chamo de disputados os lugares convenientes para os dois exércitos, onde tanto o inimigo quanto nós mesmos estaremos","page":61},{"type":"paragraph","text":"em vantagem, onde se pode instalar um acampamento cuja posição, independentemente de sua utilidade própria, pode","page":61},{"type":"paragraph","text":"prejudicar o adversário, e impedir-lhe a visibilidade. Esses lugares podem e devem ser disputados. São terrenos-chave.","page":61},{"type":"paragraph","text":"IV. Por lugares de reunião entendo aqueles onde é quase inevitável que tanto nós quanto o inimigo transitemos. São lugares onde o","page":62},{"type":"paragraph","text":"inimigo - tão ao alcance de suas fronteiras quanto tu das tuas - estaria em segurança em caso de infortúnio ou poderia perseguir","page":62},{"type":"paragraph","text":"sua boa estrela, caso de início tivesse triunfado. São lugares que comunicam com o exército inimigo e com zonas de retirada.","page":62},{"type":"paragraph","text":"V. Chamo de cheios e unidos os terrenos que, por sua configuração e suas dimensões, permitem a utilização pelos dois exércitos,","page":62},{"type":"paragraph","text":"mas, como estão enquistados profundamente em território inimigo, não devem te incitar a travar batalha, a menos que a","page":62},{"type":"paragraph","text":"necessidade ou o inimigo te obriguem.","page":62},{"type":"paragraph","text":"VI. Os lugares com várias saídas são os que permitem a junção entre os diferentes Estados contíguos. Esses lugares estão na","page":62},{"type":"paragraph","text":"encruzilhada onde os príncipes vizinhos podem aportar reforços à facção que lhes aprouver favorecer.","page":62},{"type":"paragraph","text":"VII. Os lugares graves são os que, situados no interior de Estados inimigos, apresentam em todas as direções cidades, fortalezas,","page":62},{"type":"paragraph","text":"montanhas, desfiladeiros, pântanos, pontes, campos áridos, ou outros obstáculos.","page":62},{"type":"paragraph","text":"VIII. Os lugares onde tudo míngua, onde uma parte do exército não consegue ver a outra nem socorrê-Ia, onde há lagos, atoleiros,","page":62},{"type":"paragraph","text":"torrentes, rios traiçoeiros, onde só se pode avançar por pequenos pelotões, com grandes esforços e muita dificuldade, são os que","page":62},{"type":"paragraph","text":"chamo de deteriorados.","page":62},{"type":"paragraph","text":"IX. Enfim, por lugares mortíferos entendo todos aqueles onde nos encontramos de tal forma fragilizados que, independente de","page":62},{"type":"paragraph","text":"qualquer atitude que tomarmos, sempre estamos em perigo. São lugares onde, combatendo-se, corre-se o risco de ser vencido;","page":62},{"type":"paragraph","text":"ficando-se tranqüilo, corre-se o risco de sucumbir de fome ou de doença. São lugares, em suma, onde não se deve permanecer e","page":62},{"type":"paragraph","text":"onde só se pode sobreviver com muita dificuldade, combatendo com a força do desespero.","page":62},{"type":"paragraph","text":"Esses são os nove tipos de terrenos de que queria falar-te. Aprende a conhecê-Ios, para evitá-Ios ou aproveitá-Ios.","page":62},{"type":"paragraph","text":"Quando estiveres em lugares dispersivos, controla bem tuas tropas; mas, sobretudo, jamais traves batalha, por mais favoráveis que as","page":63},{"type":"paragraph","text":"circunstâncias se apresentem. A vista da terra natal e a facilidade de retorno ocasionariam muitas deserções: em breve os campos estariam coalhados de","page":63},{"type":"paragraph","text":"desertores.","page":63},{"type":"paragraph","text":"Se estiveres em lugares leves, não estabeleças ali teu acampamento.","page":63},{"type":"paragraph","text":"Como teu exército ainda não tomou nenhuma cidade, nenhuma fortaleza, nenhum posto importante em território inimigo, e não tem na retaguarda","page":63},{"type":"paragraph","text":"nenhum dique que possa contê-Io, prevendo dificuldades, agruras e obstáculos para avançar, é provável que prefira o que lhe parece mais fácil ao que lhe","page":63},{"type":"paragraph","text":"parece difícil, e bata em retirada.","page":63},{"type":"paragraph","text":"Se tiveres reconhecido lugares que te parecem chave, apodera-te deles.","page":63},{"type":"paragraph","text":"Não permitas que o inimigo os reconheça. Emprega toda tua diligência. Não permitas que as guarnições se separem. Esforça-te ao máximo para consolidar","page":63},{"type":"paragraph","text":"a posse do terreno, mas não traves combate para expulsar o inimigo. Se ele tomou a dianteira, negaceia para desalojá-Io. Se ocupaste o terreno primeiro,","page":63},{"type":"paragraph","text":"não te desalojes.","page":63},{"type":"paragraph","text":"Com relação aos lugares de reunião, tenta preceder o inimigo. Faz com que te comuniques livremente de todos os lados, que teus cavalos, teus","page":63},{"type":"paragraph","text":"veículos e todos os teus equipamentos possam transitar sem perigo. Nada negligencies, na medida do possível, para conquistar a boa vontade dos povos","page":63},{"type":"paragraph","text":"vizinhos. Busca aliança, solicita-a, suborna, obtém-na custe o que custar. Ela te é necessária e apenas por seu intermédio teu exército poderá conseguir tudo o","page":63},{"type":"paragraph","text":"que necessita. Excesso de teu lado, penúria do lado inimigo.","page":63},{"type":"paragraph","text":"Em lugares plenos e unidos, estende-te à vontade, instala-te com largueza, faz trincheiras para colocar-te a salvo de toda surpresa, e espera","page":63},{"type":"paragraph","text":"tranqüilamente que o tempo e as circunstâncias ditem o momento oportuno de uma grande ação.","page":63},{"type":"paragraph","text":"Se estiveres perto de lugares que têm várias saídas, vários acessos, conhece-os bem. Alia-te com os Estados vizinhos, que nada escape a tuas","page":63},{"type":"paragraph","text":"pesquisas. Apodera-te de todas as rotas, não negligencies nenhuma, por mais insignificante que possa parecer, e vigia-as com muito cuidado.","page":63},{"type":"paragraph","text":"Se te encontrares em lugares graves, domina tudo o que te cerca, não deixes, em tua passagem, de conquistar o menor posto. Sem essa precaução,","page":63},{"type":"paragraph","text":"corres o risco de faltarem os víveres necessários para a manutenção de teu exército, ou de veres o inimigo em teu encalço quando menos pensares, e","page":64},{"type":"paragraph","text":"seres atacado por vários lados ao mesmo tempo.","page":64},{"type":"paragraph","text":"Se estiveres em lugares deteriorados, não tomes a dianteira, retrocede, foge o mais rápido possível.","page":64},{"type":"paragraph","text":"Se estiveres em lugares mortíferos, não hesites em combater, ataca o inimigo, quanto antes melhor.","page":64},{"type":"paragraph","text":"Assim agiam nossos guerreiros antigamente. Esses homens notáveis, hábeis e experimentados em sua arte, tinham por princípio que a maneira de","page":64},{"type":"paragraph","text":"atacar e de se defender não devia ser necessariamente a mesma, mas devia emanar da natureza do terreno e da posição do exército. Diziam ademais que a","page":64},{"type":"paragraph","text":"vanguarda e a retaguarda de um exército não devem ser comandadas da mesma forma, que é preciso combater a vanguarda e romper a retaguarda; que","page":64},{"type":"paragraph","text":"o muito e o pouco não concordam por muito tempo, que o forte e o fraco, quando juntos, não tardam em se desentender; que o alto e o baixo não podem","page":64},{"type":"paragraph","text":"ser igualmente úteis, que as tropas estreitamente unidas podem facilmente se dividir, e as divididas dificilmente se reúnem novamente. Repetiam que um","page":64},{"type":"paragraph","text":"exército jamais deveria se mobilizar sem estar seguro de alguma vantagem real, e quando não houvesse nada a ganhar, devia-se ficar tranqüilo e proteger","page":64},{"type":"paragraph","text":"o acampamento.","page":64},{"type":"paragraph","text":"Em resumo, afirmo que toda a tua conduta militar deve calcar-se nas circunstâncias, que deves atacar ou te defender, levando em conta se o teatro","page":64},{"type":"paragraph","text":"da guerra se desenrola em teus domínios ou nos do inimigo.","page":64},{"type":"paragraph","text":"Se a guerra se faz em teu próprio país, e se o inimigo, sem ter permitido que te prepares, vem atacar-te com um exército bem ordenado, visando invadir","page":64},{"type":"paragraph","text":"o país, anexá-Io, ou devastá-Io, reúne prontamente o máximo de tropas, busca socorro junto aos vizinhos e aliados, apodera-te de alguns lugares que o","page":64},{"type":"paragraph","text":"inimigo ambiciona, e ele acederá a teus desejos. Coloca-o na defensiva, para ganhar tempo. A rapidez é a seiva da guerra.","page":64},{"type":"paragraph","text":"Percorre rotas imprevistas. Procura impedir que o exército inimigo seja abastecido, barra todos os seus caminhos ou, pelo menos, faz com que todos","page":64},{"type":"paragraph","text":"tenham emboscadas ou exijam muito esforço para serem conquistados.","page":64},{"type":"paragraph","text":"Os camponeses podem ser muito úteis e te servir melhor do que tuas próprias tropas: mostra-Ihes que eles devem impedir que injustos saqueadores","page":65},{"type":"paragraph","text":"venham pilhar seus bens e seqüestrar-Ihes pai, mãe, mulher e filhos.","page":65},{"type":"paragraph","text":"Não te mantenhas somente na defensiva; envia partidários para interceptar os comboios, atormenta, fatiga, ataca em todas as frentes. Força","page":65},{"type":"paragraph","text":"teu injusto agressor a se arrepender de sua temeridade. Constrange-o a bater em retirada, só levando como troféu a ignomínia da derrota.","page":65},{"type":"paragraph","text":"Se travares a guerra em país inimigo, evita dividir tuas tropas, ou melhor, nunca as divida. Que elas estejam sempre reunidas e solidárias. Cuida para","page":65},{"type":"paragraph","text":"que elas sempre estejam em lugares férteis e abundantes.","page":65},{"type":"paragraph","text":"Se as tropas viessem a passar fome, a miséria e as doenças causariam mais devastação do que os longos anos da espada inimiga.","page":65},{"type":"paragraph","text":"Obtém pacificamente todos os reforços necessários. Só empregues a força quando os outros meios tiverem sido infrutíferos. Faz com que os aldeães","page":65},{"type":"paragraph","text":"e os camponeses julguem interessante vir por conta própria te oferecer víveres.","page":65},{"type":"paragraph","text":"Mas, repito, jamais dividas as tropas.","page":65},{"type":"paragraph","text":"Todo o resto permanecendo igual, o exército que combate em terreno próprio é duplamente mais forte.","page":65},{"type":"paragraph","text":"Se combates em território inimigo, presta atenção nesta máxima, sobretudo se tiveres avançado em suas terras: conduz teu exército inteiro;","page":65},{"type":"paragraph","text":"realiza todas as operações militares no maior sigilo, torna-te inescrutável.","page":65},{"type":"paragraph","text":"Apenas tu deves saber o que fazer, quando chegar a hora.","page":65},{"type":"paragraph","text":"Às vezes podes estar reduzido a não saber aonde ir, nem para que lado recorrer. Nesse caso, não te precipites. Espera tudo do tempo e das","page":65},{"type":"paragraph","text":"circunstâncias. Sê inquebrantável onde estiveres.","page":65},{"type":"paragraph","text":"Se te engajaste inadequadamente, evita fugir. A fuga causaria tua perda.","page":65},{"type":"paragraph","text":"Perece em vez de recuar. Pelo menos, morrerás com bravura. Comanda com brio. Teu exército, acostumado a ignorar teus desígnios, ignora o perigo que o","page":65},{"type":"paragraph","text":"ameaça. Acreditará que tiveste tuas razões para agir como agiste, e combaterá com tanta disciplina e coragem como se estivesse longamente preparado para","page":65},{"type":"paragraph","text":"a batalha.","page":65},{"type":"paragraph","text":"Se triunfares, a força, a coragem e a determinação de teus soldados redobrará. Tua reputação crescerá na mesma proporção do risco incorrido. Teu","page":65},{"type":"paragraph","text":"exército se acreditará invencível sob teu comando.","page":65},{"type":"paragraph","text":"Por mais crítica que seja a situação e as circunstâncias em que te encontrares, não te desesperes. Nas ocasiões em que tudo inspira temor, nada","page":66},{"type":"paragraph","text":"deves temer. Quando estiveres cercado de todos os perigos, não deves temer nenhum. Quando estiveres sem nenhum recurso, deves contar com todos.","page":66},{"type":"paragraph","text":"Quando fores surpreendido, surpreende o inimigo.","page":66},{"type":"paragraph","text":"Instrui de tal forma tuas tropas que elas estejam prontas sem preparativos; que encontrem grandes vantagens onde não esperem encontrar;","page":66},{"type":"paragraph","text":"que, sem nenhuma ordem particular de tua parte, improvisem decisões a tomar; que, sem proibição expressa, se furtem a tudo que contraria a disciplina.","page":66},{"type":"paragraph","text":"Impede que se espalhem boatos falsos, corta pela raiz queixas e murmúrios, não permitas que se façam augúrios sinistros baseados em algum","page":66},{"type":"paragraph","text":"evento extraordinário.","page":66},{"type":"paragraph","text":"Se os adivinhos e os astrólogos do exército predisseram boa fortuna, acata seu oráculo. Se falam de forma obscura, interpreta bem. Se hesitam ou","page":66},{"type":"paragraph","text":"não dizem coisas vantajosas, não lhes dês ouvidos, ordena que se calem.","page":66},{"type":"paragraph","text":"Ama tuas tropas, e propicia-Ihes toda a ajuda, todas as comodidades que necessitarem. Se estão exaustas, não é porque lhes apraz; se passam","page":66},{"type":"paragraph","text":"fome, não significa que desdenhem comer, se se expõem à morte, não significa que detestem a vida. Se teus oficiais não desfrutam de riquezas supérfluas,","page":66},{"type":"paragraph","text":"não significa que desprezem os bens terrenos. Reflete seriamente em tudo isso.","page":66},{"type":"paragraph","text":"Depois de teres preparado o teu exército e teres dado tuas ordens, se vires que as tropas negligentemente ociosas mostram-se abatidas, beirando as","page":66},{"type":"paragraph","text":"lágrimas, retira-as prontamente desse estado depressivo. Proporciona-Ihes festas, faz com que ouçam o rufar de tambores e de outros instrumentos","page":66},{"type":"paragraph","text":"militares; exercita-as; faz com que façam evoluções; que mudem de lugar; leva- as a terrenos inóspitos, onde tenham que mourejar. Imita a conduta de Chuan","page":66},{"type":"paragraph","text":"Chu e de Ts'ao-Kuei, muda o coração de teus soldados, acostuma-os ao trabalho, eles se fortalecerão. Em seguida, tudo lhes parecerá mais fácil.","page":66},{"type":"paragraph","text":"Os animais estacam quando sobrecarregados; tornam-se inúteis quando forçados. Os pássaros, ao contrário, necessitam ser forçados para renderem","page":66},{"type":"paragraph","text":"mais. Os homens ficam a meio termo entre uns e outros. É preciso sobrecarregá-Ias, mas não a ponto de vergarem. É preciso forçá-Ias com","page":66},{"type":"paragraph","text":"discernimento e medida.","page":66},{"type":"paragraph","text":"Se quiseres tirar o máximo de teu exército, se quiseres que ele seja invencível, faz com que se assemelhe a Chuai Jen, uma grande serpente que","page":67},{"type":"paragraph","text":"se encontra no Monte Chang Chan. Golpeada na cabeça, imediatamente sua cauda ataca, e revida. Golpeada na cauda, a cabeça corre, defendê-Ia.","page":67},{"type":"paragraph","text":"Golpeada no meio ou em qualquer outra parte do corpo, tanto a cabeça quanto a cauda atacam. Um exército pode imitar semelhante coordenação? Afirmo que","page":67},{"type":"paragraph","text":"pode e deve.","page":67},{"type":"paragraph","text":"Alguns soldados do reino de Wu faziam a travessia de um rio ao mesmo tempo que soldados inimigos do reino de Yue. Um vento impetuoso soprou e","page":67},{"type":"paragraph","text":"virou os barcos. Todos teriam perecido, se não tivessem se ajudado mutuamente. Eles esqueceram que eram inimigos; ao contrário, agiram como","page":67},{"type":"paragraph","text":"se fossem amigos ternos e sinceros. Eles se ajudaram, como a mão direita coopera com a esquerda.","page":67},{"type":"paragraph","text":"Recordo esse fato histórico para que entendas que os diferentes destacamentos de teu exército devem se auxiliar mutuamente, mas ainda que","page":67},{"type":"paragraph","text":"é preciso que socorras teus aliados, que socorras inclusive os povos vencidos que necessitarem; pois, se eles se submeteram, é porque não puderam fazer","page":67},{"type":"paragraph","text":"de modo diferente; se o soberano deles te declarou guerra, eles não são culpados. Sê prestativo, chegará a tua vez de ser recompensado.","page":67},{"type":"paragraph","text":"Em qualquer país onde estiveres, independente do terreno que ocupares, se em teu exército há estrangeiros, ou se, entre os povos vencidos,","page":67},{"type":"paragraph","text":"tiveres escolhido soldados para aumentar o contingente de tuas tropas, não permitas que nos corpos que integram eles sejam os mais fortes ou a maioria.","page":67},{"type":"paragraph","text":"Quando se prendem vários cavalos em uma mesma estaca, deve-se evitar colocar juntos os indômitos, ou colocá-Ias com outros em menor número. Eles","page":67},{"type":"paragraph","text":"semeariam a desordem. Uma vez domesticados, imitarão facilmente os companheiros.","page":67},{"type":"paragraph","text":"Em qualquer posição que estiveres, se teu exército é inferior ao do inimigo, unicamente por tua conduta, se ela for adequada, podes conquistar a","page":67},{"type":"paragraph","text":"vitória. Não basta contar com cavalos mancos ou carros enlameados. O que adiantaria estar em vantagem se não soubesses tirar partido de tua posição?","page":67},{"type":"paragraph","text":"Para que servem a bravura sem a prudência; a coragem sem a astúcia?","page":67},{"type":"paragraph","text":"Um bom general tira partido de tudo, e só é capaz disso porque age com o maior sigilo, conserva o sangue-frio e comanda com retidão, mas de tal forma","page":67},{"type":"paragraph","text":"que fascina os olhos, mas engana os ouvidos de seu exército. Se seus próprios soldados ignoram-lhe os projetos, como os inimigos poderiam desvendá-Ios?","page":68},{"type":"paragraph","text":"Um general hábil sabe que suas tropas ignoram o que devem fazer, bem como as ordens que receberão. Se os acontecimentos mudam, ele altera os","page":68},{"type":"paragraph","text":"planos. Se seus métodos e seu sistema apresentam inconvenientes, ele os corrige a contento.","page":68},{"type":"paragraph","text":"Um general hábil sabe antecipadamente tudo o que deve fazer.","page":68},{"type":"paragraph","text":"Qualquer outra pessoa, além dele, deve ignorar tais projetos. Essa era a prática dos antigos guerreiros que mais se distinguiram na arte sublime do","page":68},{"type":"paragraph","text":"comando. Se queriam tomar de assalto uma cidade, só falavam quando estavam aos pés das muralhas. Eram os primeiros a escalar, todos os","page":68},{"type":"paragraph","text":"seguiam. Quando já estavam alojados sobre a muralha, ordenavam que as escadas fossem rompidas. Mesmo em território aliado, reduplicavam a atenção","page":68},{"type":"paragraph","text":"e o sigilo.","page":68},{"type":"paragraph","text":"Em toda a parte, conduziam seus exércitos como um pastor conduz seu rebanho. Conduziam-nos onde lhes aprazia, fazendo-os ir e vir sem murmúrio,","page":68},{"type":"paragraph","text":"sem que um único soldado se rebelasse.","page":68},{"type":"paragraph","text":"A principal ciência de um general consiste em conhecer perfeitamente os nove tipos de terrenos, a fim de efetuar adequadamente as nove mudanças.","page":68},{"type":"paragraph","text":"Toda a arte consiste em saber instalar e retirar as tropas de acordo com os terrenos e as circunstâncias, a trabalhar eficazmente para dissimular as","page":68},{"type":"paragraph","text":"próprias intenções e descobrir as do inimigo, a ter por princípio que tropas bem avançadas em território inimigo tornam-se solidárias, mas se dispersam","page":68},{"type":"paragraph","text":"facilmente, quando permanecem nas fronteiras; que elas já conseguiram meia vitória quando se apossaram de todos os acessos e de todas as saídas, tanto","page":68},{"type":"paragraph","text":"do lugar onde devem acampar quanto das imediações do campo inimigo; que é um começo de vitória estar acampado em terreno vasto, espaçoso e aberto de","page":68},{"type":"paragraph","text":"todos os lados; mas já é quase ter vencido quando se apossaram de todos os pequenos postos, de todos os caminhos, de todos os vilarejos em terras","page":68},{"type":"paragraph","text":"inimigas e, mediante sua civilidade, conquistaram o respeito dos que desejam vencer, ou dos vencidos.","page":68},{"type":"paragraph","text":"Instruído pela experiência e por minhas próprias reflexões, tentei, quando comandava os exércitos, praticar tudo o que te recomendo aqui.","page":68},{"type":"paragraph","text":"Quando estava em lugares dispersivos, trabalhava para a união dos corações e para a uniformidade dos sentimentos. Quando estava em lugares leves, reunia","page":68},{"type":"paragraph","text":"meus homens e os ocupava utilmente. Quando estava em lugares disputados, tentava me apoderar do terreno, quando possível. Se o inimigo me tivesse","page":69},{"type":"paragraph","text":"precedido, usava de todos os subterfúgios para desalojá-Io. Quando estava em lugares de reunião, observava com extrema vigilância, e espreitava o inimigo.","page":69},{"type":"paragraph","text":"Em terreno pleno e unido, me instalava à vontade e impedia que o inimigo se instalasse. Em lugares de várias saídas, quando não conseguia ocupar todas","page":69},{"type":"paragraph","text":"elas, eu ficava de sobreaviso, observava o inimigo, não o perdia de vista. Em lugares graves, alimentava bem a tropa, era pródigo em ternura. Em lugares","page":69},{"type":"paragraph","text":"deteriorados, tentava sair do embaraço, seja fazendo desvios, seja preenchendo os vazios. Enfim, em lugares mortíferos, fazia com que o inimigo","page":69},{"type":"paragraph","text":"acreditasse que eu não poderia escapar.","page":69},{"type":"paragraph","text":"As tropas bem disciplinadas resistem quando estão cercadas; reduplicam esforços em situações extremas, afrontam o perigo sem temor,","page":69},{"type":"paragraph","text":"batem-se até a morte quando não há alternativa, e obedecem cegamente. Se as que tu comandas não são dessa estirpe, a culpa é tua. Não mereces","page":69},{"type":"paragraph","text":"comandá-Ias.","page":69},{"type":"paragraph","text":"Se ignoras os planos dos Estados vizinhos, não poderás preparar tuas alianças no momento oportuno; se não sabes qual é o contingente inimigo que","page":69},{"type":"paragraph","text":"deves combater, se não conheces seu ponto forte e fraco, não te prepararás nem tomarás as providências necessárias para comandar teu exército. Não","page":69},{"type":"paragraph","text":"mereces comandar.","page":69},{"type":"paragraph","text":"Se ignoras onde há montanhas e colinas, lugares secos ou úmidos, lugares escarpados ou pantanosos, lugares cheios de desfiladeiros ou de","page":69},{"type":"paragraph","text":"perigos, não poderás dar ordens convenientes, não saberás conduzir teu exército. És indigno de comandar.","page":69},{"type":"paragraph","text":"Se não conheces todos os caminhos, se não tens cuidada de te cercar de guias seguras e fiéis para te conduzir pelas estradas desconhecidas, não.","page":69},{"type":"paragraph","text":"atingirás aquilo. que te propões, serás vítima das inimigas. Não. mereces comandar.","page":69},{"type":"paragraph","text":"Quando. um Rei Hegemônico ataca um Estado poderoso, ele impede que a inimiga se concentre. Intimida-a e intercepta as reforços das aliadas.","page":69},{"type":"paragraph","text":"Então, deduz-se que a Rei Hegemônico não combate alianças poderosas de","page":69},{"type":"paragraph","text":"Estados e não encoraja o poder de outros Estados. Ele se apóia, para a consecução de seus fins, na capacidade de intimidar as adversárias. Assim, ele","page":69},{"type":"paragraph","text":"pode tomar as cidades inimigas e derrubar o Estado inimiga.","page":70},{"type":"paragraph","text":"Se não conheces a arte das alianças, tuas tropas não poderão. valer-se da força dos vassalos e feudatárias. Quando. estes tinham que enfrentar algum","page":70},{"type":"paragraph","text":"grande príncipe, uniam-se, tentavam perturbar toda o Universo, colocavam em seu campo a maior número possível de soldados, procuravam sobretudo","page":70},{"type":"paragraph","text":"conquistar a amizade de seus vizinhas, pagando-a bem caro, se preciso fosse.","page":70},{"type":"paragraph","text":"Não davam ao inimigo tempo de se preparar, ainda menos de recorrer aos aliados e reunir todas as suas forças. Atacavam o inimigo despreparado.","page":70},{"type":"paragraph","text":"Assim, se sitiavam uma cidade, com certeza a dominavam. Se queriam conquistar uma província, realizavam seu intento. Por mais vantagens que já","page":70},{"type":"paragraph","text":"tivessem conseguido, não dormiam sobre os louras da vitória. Jamais permitiam que a ócio ou a devassidão enfraquecessem o exército. Mantinham","page":70},{"type":"paragraph","text":"uma estrita disciplina, punindo severamente, sempre que necessário.","page":70},{"type":"paragraph","text":"Recompensavam com prodigalidade, quando as ocasiões a exigiam.","page":70},{"type":"paragraph","text":"Além das leis ordinárias da guerra, promulgavam outras, em função da tempo e da lugar.","page":70},{"type":"paragraph","text":"Queres vencer? Toma por modelo a conduta que acaba de traçar.","page":70},{"type":"paragraph","text":"Considera teu exército coma se fosse um único homem que tivesses que conduzir. Não reveles jamais teu móbil. Alardeia todas as vantagens, mas","page":70},{"type":"paragraph","text":"oculta cuidadosamente a menor perda. Toma todas as decisões no maior sigilo. Coloca-os numa situação perigosa e eles sobreviverão, pois um exército","page":70},{"type":"paragraph","text":"que combate num campo de morte poderá transformar o revés em vitória.","page":70},{"type":"paragraph","text":"Recompensa, sem seguires normas rotineiras, publica ordens sem levar em conta as precedentes, assim poderás te servir da exército inteiro como de","page":70},{"type":"paragraph","text":"um único homem.","page":70},{"type":"paragraph","text":"Vislumbra todas as providências da inimiga, toma medidas eficazes para atingir o general inimigo. O general estando morto, só combaterás contra","page":70},{"type":"paragraph","text":"rebeldes.","page":70},{"type":"paragraph","text":"O nó das operações militares depende de tua faculdade de simular que acatas o desejo do inimigo.","page":70},{"type":"paragraph","text":"Jamais dividas tuas forças; a concentração te permite matar o general inimigo, mesmo a uma grande distância. Essa é uma forma engenhosa de","page":70},{"type":"paragraph","text":"atingires teu objetivo.","page":70},{"type":"paragraph","text":"Quando o inimigo te oferecer uma oportunidade, aproveita rapidamente a vantagem; toma a dianteira, apropriando-te de algo relevante para ele, e","page":71},{"type":"paragraph","text":"avança segundo um plano fixado em segredo.","page":71},{"type":"paragraph","text":"A doutrina da guerra consiste em acompanhar a situação do inimigo, a fim de decidir a batalha.","page":71},{"type":"paragraph","text":"Assim que teu exército tiver cruzado as fronteiras, bloqueia as estradas, inutiliza as instruções que estiverem em tuas mãos e impede a circulação de","page":71},{"type":"paragraph","text":"notícias. Rompe as relações com os inimigos, reúne teu conselho e exorta-o a executar o plano traçado. Em seguida, ataca o inimigo.","page":71},{"type":"paragraph","text":"Antes de começar a campanha, sê como uma jovem que não sai de casa; ela ocupa-se das tarefas caseiras, cuida de tudo, vê tudo, ouve tudo, mas","page":71},{"type":"paragraph","text":"aparentemente não se intromete em nada. Uma vez a campanha começada, imita a rapidez de uma lebre que, perseguida pelos caçadores, tenta, por mil","page":71},{"type":"paragraph","text":"desvios, refugiar-se, com toda a segurança, em seu covil.","page":71},{"type":"heading","id":"h_suntzu_14","lvl":1,"title":"Capítulo XII — Da Pirotecnia","page":72},{"type":"paragraph","text":"CAPÍTULO XII","page":72},{"type":"paragraph","text":"DA PIROTECNIA","page":72},{"type":"paragraph","text":"Sun Tzu diz: Há cinco maneiras de combater com fogo. A primeira consiste em queimar homens; a segunda, em queimar provisões; a terceira, em","page":72},{"type":"paragraph","text":"queimar equipamentos; a quarta, em queimar arsenais e depósitos; a quinta, em utilizar bombas incendiárias.","page":72},{"type":"paragraph","text":"Antes de empreender esse tipo de combate, deve-se prever tudo:","page":72},{"type":"paragraph","text":"identificar a posição do inimigo; conhecer todos os caminhos por onde ele poderia escapar ou receber ajuda; munir-se do material necessário para a","page":72},{"type":"paragraph","text":"execução do projeto; aguardar que o tempo e as circunstâncias estejam favoráveis.","page":72},{"type":"paragraph","text":"Prepara primeiramente todos os materiais combustíveis que irás usar.","page":72},{"type":"paragraph","text":"Depois de ateado o fogo, cuidado com a fumaça. Há um dia para atear fogo e outro para alastrá-lo. Não confundas as duas coisas. Deve-se atear fogo","page":72},{"type":"paragraph","text":"quando tudo está tranqüilo sob o céu, e a serenidade parece duradoura. O dia de alastrá-lo é quando a lua se encontra sob uma das quatro constelações, Qi,","page":72},{"type":"paragraph","text":"Pi, Y, Chen. Nesses dias, o vento sopra, geralmente com força.","page":72},{"type":"paragraph","text":"As cinco maneiras de combater com fogo exigem que varies segundo as circunstâncias. Essas variações se reduzem a cinco. Vou indicá-Ias, a fim de","page":72},{"type":"paragraph","text":"que possas empregá-Ias apropriadamente.","page":72},{"type":"paragraph","text":"I. Se não notas nenhum rumor no campo adversário, se o inimigo permanece tranqüilo, algum tempo depois de teres ateado fogo,","page":72},{"type":"paragraph","text":"fica também calmo, mantém a própria posição. Atacar imprudentemente significa ser derrotado. Sabes que o fogo","page":72},{"type":"paragraph","text":"pegou, é o bastante. Enquanto isso, deves supor que o fogo age sub-repticiamente. Seus efeitos serão tanto mais funestos quanto","page":72},{"type":"paragraph","text":"mais o fogo arda no interior. Espera que ele estale e as labaredas crepitem. Então, poderás lançar-te contra aqueles que só pensam","page":72},{"type":"paragraph","text":"em escapar.","page":72},{"type":"paragraph","text":"II. Se, pouco depois de teres ateado fogo, vês que se levantam altas labaredas, não dês ao inimigo tempo de apagá-lo. Envia homens","page":72},{"type":"paragraph","text":"para avivá-lo, prepara-te rápido e corre ao combate.","page":72},{"type":"paragraph","text":"III. Se, apesar de todas as providências e artifícios empregados, teus homens não conseguiram penetrar no acampamento inimigo, e","page":73},{"type":"paragraph","text":"fores obrigado, então, a atear fogo do lado de fora, observa de que lado sopra o vento. Começa o incêndio e ataca a favor do","page":73},{"type":"paragraph","text":"vento. Nessas duas ocasiões, jamais combatas contra o vento.","page":73},{"type":"paragraph","text":"IV. Se o vento soprou continuamente durante o dia, fica certo de que durante a noite ele cessará: toma tuas precauções e tuas","page":73},{"type":"paragraph","text":"disposições.","page":73},{"type":"paragraph","text":"V. Um general que, para combater seus inimigos, sabe utilizar-se do fogo de forma adequada é um homem verdadeiramente","page":73},{"type":"paragraph","text":"esclarecido. Um general que sabe usar a água e á inundação para o mesmo fim é um homem excelente. Entretanto, só se deve","page":73},{"type":"paragraph","text":"empregar a água com moderação. Serve-te da água no início da contenda, apenas para obstruir os caminhos por onde os inimigos","page":73},{"type":"paragraph","text":"poderiam escapar ou receber socorro.","page":73},{"type":"paragraph","text":"As diferentes maneiras de combater com fogo, que acabo de indicar, proporcionam uma plena vitória, de que é preciso saber colher os frutos. O","page":73},{"type":"paragraph","text":"mais considerável de todos, e aquele sem o qual terias perdido teus cuidados e teus sofrimentos, é reconhecer o mérito de todos os que se distinguiram, e","page":73},{"type":"paragraph","text":"recompensá-Ios conforme suas ações. Geralmente, os homens agem por interesse. Se tuas tropas só se deparam com dificuldades e trabalhos, não as","page":73},{"type":"paragraph","text":"empregarás duas vezes com vantagens.","page":73},{"type":"paragraph","text":"A guerra deve ser a última solução. Os combates, quaisquer que sejam os resultados, têm sempre um gosto amargo mesmo para os próprios","page":73},{"type":"paragraph","text":"vencedores. Só se deve travá-Ios quando não houver outra saída.","page":73},{"type":"paragraph","text":"Dominado pela cólera ou pela vingança, um soberano não deve mobilizar as tropas. Tendo no coração idênticos sentimentos, um general deve","page":73},{"type":"paragraph","text":"evitar o combate. Para ambos, os tempos são nebulosos. Devem aguardar dias serenos para ponderar e tomar decisões.","page":73},{"type":"paragraph","text":"Se prevês algum lucro, coloca em movimento teu exército. Se não prevês nenhuma vantagem, fica impassível. Por mais razões que tenhas para","page":73},{"type":"paragraph","text":"ficar irritado, por mais provocações ou insultos que recebeste, para tomar decisões espera que o fogo da cólera se dissipe e sentimentos pacíficos","page":73},{"type":"paragraph","text":"brotem em teu coração. Nunca esqueças que teu objetivo, ao desencadear a guerra, deve ser o de conseguir para o Estado a glória, o esplendor e a paz, e","page":73},{"type":"paragraph","text":"não o de semear o tumulto, a desolação e a morte.","page":74},{"type":"paragraph","text":"Lembra-te que defendes não interesses pessoais, mas os do teu país.","page":74},{"type":"paragraph","text":"Tuas virtudes e teus vícios, tuas qualidades e teus defeitos influem igualmente no ânimo daqueles que representas. Teus menores erros têm sempre nefastas","page":74},{"type":"paragraph","text":"conseqüências. Geralmente, os grandes são irreparáveis e funestos. É difícil sustentar um reino que terás levado à beira da ruína. Depois de destruí-Ia, é","page":74},{"type":"paragraph","text":"impossível reerguê-lo. Tampouco se ressuscitam os mortos.","page":74},{"type":"paragraph","text":"Da mesma forma que um príncipe sábio e esclarecido se empenha em bem governar, um general hábil emprega toda a sua energia em preservar o","page":74},{"type":"paragraph","text":"exército e empregá-Ia na salvaguarda do Estado.","page":74},{"type":"heading","id":"h_suntzu_15","lvl":1,"title":"Capítulo XIII — Da Arte de Semear a Discórdia","page":75},{"type":"paragraph","text":"CAPÍTULO XIII","page":75},{"type":"paragraph","text":"DA ARTE DE SEMEAR A DISCÓRDIA","page":75},{"type":"paragraph","text":"Sun Tzu diz: Se, tendo recrutado um exército de cem mil homens, deves conduzi-Ia muito longe, é preciso contar que, dentro e fora, haverá comoção e","page":75},{"type":"paragraph","text":"rumor. As cidades e as aldeias de onde saíram os homens que compõem tuas tropas, os lugarejos e os campos dos quais terás tirado as provisões e todos os","page":75},{"type":"paragraph","text":"suprimentos, o vaivém de pessoas nos caminhos, tudo isso só poderia acontecer ao preço do desalento de muitas famílias, do abandono de muitas","page":75},{"type":"paragraph","text":"terras e de muitas despesas para o Estado.","page":75},{"type":"paragraph","text":"Milhares de famílias subitamente privadas de arrimo se encontram sem condições de se dedicar a seus trabalhos quotidianos; as terras desprovidas","page":75},{"type":"paragraph","text":"dos braços que as cultivavam diminuem - proporcionalmente aos cuidados recusados - a quantidade e a qualidade de seus frutos.","page":75},{"type":"paragraph","text":"Os vencimentos de tantos oficiais, o soldo diário de tantos soldados e a manutenção de todo o exército desgastam aos poucos os celeiros e os cofres","page":75},{"type":"paragraph","text":"do príncipe e do povo, até exauri-Ios por completo.","page":75},{"type":"paragraph","text":"Observar os inimigos ou travar a guerra durante anos consecutivos não significa amar o povo. Significa, antes, ser o inimigo de todo o país.","page":75},{"type":"paragraph","text":"Geralmente, todas as despesas, todos os sofrimentos, todos os trabalhos e todas as agruras de vários anos de guerra limitam-se, para os próprios","page":75},{"type":"paragraph","text":"vencedores, a um único dia de triunfo e de glória: o dia da vitória. Utilizar-se, para vencer, de cercos e batalhas significa que tanto o soberano quanto o","page":75},{"type":"paragraph","text":"general ignoram seu dever: um não sabe governar; o outro não sabe servir o","page":75},{"type":"paragraph","text":"Estado.","page":75},{"type":"paragraph","text":"Assim, tendo optado pela guerra e tendo aliciado e preparado as tropas, emprega os artifícios.","page":75},{"type":"paragraph","text":"Procura obter todas as informações sobre o inimigo. Informa-te exatamente de todas as suas relações, suas ligações e interesses recíprocos.","page":75},{"type":"paragraph","text":"Não poupes grandes somas de dinheiro. Não lamentes o dinheiro empregado seja no campo inimigo, para conseguir traidores ou obter conhecimentos","page":75},{"type":"paragraph","text":"exatos, seja para o pagamento dos teus soldados: quanto mais gastares, mais ganharás. É um dinheiro que renderá juros elevados.","page":75},{"type":"paragraph","text":"Mantém espiões por toda a parte. Informa-te de tudo, nada negligencies do que descobrires. Mas, tendo descoberto algo, sê extremamente discreto.","page":76},{"type":"paragraph","text":"Quando usares algum artifício, não é pela invocação de espíritos nem pelas conjeturas que alcançarás a vitória. Ela virá apenas do conhecimento","page":76},{"type":"paragraph","text":"exato - baseado no relatório fiel dos teus subordinados - da disposição dos inimigos, em relação àquilo que esperas que eles façam.","page":76},{"type":"paragraph","text":"Quando um hábil general se põe em movimento, o inimigo já está vencido. Quando ele combate, deve realizar sozinho mais do que todo o seu","page":76},{"type":"paragraph","text":"exército junto, não pela força de seu braço, mas por sua prudência, por seu brio e, sobretudo, por sua argúcia. É preciso que, ao primeiro sinal, uma parte","page":76},{"type":"paragraph","text":"do exército inimigo passe para o seu campo, para combater sob seus estandartes. É preciso que o general seja sempre o árbitro que estipula as","page":76},{"type":"paragraph","text":"condições da paz.","page":76},{"type":"paragraph","text":"O grande segredo para vencer sempre consiste na arte de semear a divisão: nas cidades e nas aldeias, no exterior, entre inferiores e superiores, de","page":76},{"type":"paragraph","text":"morte, e de vida.","page":76},{"type":"paragraph","text":"Os cinco tipos de divisão são apenas os galhos de um mesmo tronco.","page":76},{"type":"paragraph","text":"Aquele que sabe empregá-Ios é um homem verdadeiramente digno de comandar. É o tesouro de seu soberano e o sustentáculo do império.","page":76},{"type":"paragraph","text":"Chamo divisão nas cidades e nas aldeias aquela mediante a qual se consegue conquistar os habitantes das cidades e das aldeias que estão sob","page":76},{"type":"paragraph","text":"dominação inimiga, envolvendo-os para que possam ser usados com segurança, em caso de necessidade.","page":76},{"type":"paragraph","text":"Chamo divisão exterior aquela mediante a qual se consegue aliciar os oficiais que servem no exército inimigo.","page":76},{"type":"paragraph","text":"Pela divisão entre inferiores e superiores entendo a que nos coloca em condições de aproveitar a dissensão que semeamos entre os aliados, entre as","page":76},{"type":"paragraph","text":"diferentes guarnições, ou entre os oficiais dos diversos escalões do exército inimigo.","page":76},{"type":"paragraph","text":"A divisão de morte é aquela pela qual, após dar falsos avisos sobre o estado de nossas forças, espalhamos rumores tendenciosos, inclusive na corte","page":76},{"type":"paragraph","text":"do soberano inimigo, o qual, acreditando na veracidade dos boatos, toma atitudes condizentes com as falsas informações recebidas.","page":76},{"type":"paragraph","text":"A divisão de vida é aquela mediante a qual se distribui dinheiro em abundância, para todos os desertores do campo inimigo.","page":77},{"type":"paragraph","text":"Se souberes infiltrar traidores nas cidades e nos vilarejos inimigos, em breve terás ali muitas pessoas inteiramente devotadas. Conhecerás, por seu","page":77},{"type":"paragraph","text":"intermédio, as disposições da maioria em relação a ti. Esses traidores sugerirão a maneira e os meios que deves empregar para conquistar seus mais","page":77},{"type":"paragraph","text":"temíveis compatriotas; e quando chegar o momento de efetuar o cerco, poderás vencer sem dar o assalto, sem desferir nenhum golpe, sem","page":77},{"type":"paragraph","text":"desembainhar a espada.","page":77},{"type":"paragraph","text":"Se os oficiais inimigos estão em constante desacordo; se desconfianças mútuas, inveja, interesses pessoais os mantêm divididos, poderás facilmente","page":77},{"type":"paragraph","text":"cooptar uma parte deles, pois, por mais virtuosos e mais devotados a seus soberanos, a promessa de vingança, de riquezas ou de postos eminentes","page":77},{"type":"paragraph","text":"bastará para atiçar-Ihes a cobiça. E quando esta estiver acesa em seus corações, tudo farão para satisfazê-Ia.","page":77},{"type":"paragraph","text":"Se os diferentes destacamentos do exército inimigo não se apóiam mutuamente, se perdem tempo em se vigiar uns aos outros, se procuram se","page":77},{"type":"paragraph","text":"prejudicar, será fácil manter o desentendimento e fomentar a divisão. Eles se destruirão aos poucos, sem que nenhum deles tome abertamente o teu partido.","page":77},{"type":"paragraph","text":"Todos te servirão involuntariamente, à revelia.","page":77},{"type":"paragraph","text":"Se tiveres espalhado boatos falsos junto à corte e ao conselho do príncipe inimigo, dando a entender que deténs informações errôneas sobre","page":77},{"type":"paragraph","text":"eles; se tiveres disseminado suspeitas a respeito da lealdade dos súditos mais fiéis ao príncipe, em breve verás que, entre os inimigos, a desconfiança tomou","page":77},{"type":"paragraph","text":"o lugar da confiança, as recompensas substituíram os castigos e vice-versa, e os mais leves indícios serão considerados provas convincentes, passíveis de","page":77},{"type":"paragraph","text":"levar à morte qualquer suspeito.","page":77},{"type":"paragraph","text":"Então, os melhores oficiais, os ministros mais esclarecidos desanimarão, seu zelo diminuirá, e vendo-se sem esperança de melhor sorte, se refugiarão","page":77},{"type":"paragraph","text":"sob tuas bandeiras para se livrar dos temores que os angustiavam em permanência, e também para salvar a pele.","page":77},{"type":"paragraph","text":"Seus pais, seus aliados ou seus amigos serão acusados, perseguidos, condenados à morte. As conspirações se formarão, a ambição vicejará, só","page":77},{"type":"paragraph","text":"haverá perfídias, execuções, desordens e revoltas generalizadas.","page":77},{"type":"paragraph","text":"O que estás esperando para apoderar-te de um reino cujos habitantes já te consideram como senhor?","page":78},{"type":"paragraph","text":"Se recompensares aqueles que passaram para teu campo para se livrarem dos justos temores que os agitavam em permanência, e para salvarem","page":78},{"type":"paragraph","text":"a vida; se lhes deres emprego, seus pais, aliados, amigos serão outros súditos que conquistarás para teu príncipe.","page":78},{"type":"paragraph","text":"Se espalhares dinheiro à vontade, se tratares bem a todos, se impedires que teus soldados devastem os lugares por onde passarem, se os povos","page":78},{"type":"paragraph","text":"vencidos não sofrerem nenhum prejuízo, assegura-te que eles já foram conquistados, e a tua boa reputação atrairá mais súditos para teu soberano e","page":78},{"type":"paragraph","text":"mais cidades para seu domínio do que as mais brilhantes vitórias.","page":78},{"type":"paragraph","text":"Sê vigilante e esclarecido. Mostra, no exterior, segurança, simplicidade e impassibilidade. Fica sempre de sobreaviso, embora aparentes serenidade.","page":78},{"type":"paragraph","text":"Desconfia de tudo, apesar de pareceres confiante. Sê extremamente secreto, embora pareças fazer tudo a descoberto. Mantém espiões por toda a parte. Em","page":78},{"type":"paragraph","text":"vez de palavras, emprega sinais. Vê pela boca, fala pelos olhos. Isso não é fácil, é muito difícil. Algumas vezes a gente se engana quando acredita","page":78},{"type":"paragraph","text":"enganar os outros. Só um homem de uma prudência consumada, um homem extremamente esclarecido, um sábio de primeira linha pode usar","page":78},{"type":"paragraph","text":"adequadamente e com sucesso o artifício das divisões. Se não fores tal homem, deves renunciar. O uso que farás das divisões se voltará contra ti.","page":78},{"type":"paragraph","text":"Após teres engendrado algum projeto, se ficares sabendo que teu segredo vazou, condena à morte sem remissão tanto os que o divulgaram","page":78},{"type":"paragraph","text":"quanto os que tiveram acesso a ele. Estes últimos são inocentes, mas poderiam tornar-se culpados. A morte dos envolvidos salvará a vida de","page":78},{"type":"paragraph","text":"milhares de homens e assegurará a fidelidade de maior número ainda.","page":78},{"type":"paragraph","text":"Pune severamente, recompensa com prodigalidade, multiplica os espiões, espalha-os em toda a parte, no próprio palácio do inimigo, nos","page":78},{"type":"paragraph","text":"aposentos de seus ministros, sob as tendas de seus generais. Mantém uma lista dos principais oficiais que estão a seu serviço. Conhece seus nomes,","page":78},{"type":"paragraph","text":"sobrenomes, o número de seus filhos, de seus parentes, de seus amigos, de seus servos. Que nada se passe na casa deles sem que estejas informado.","page":78},{"type":"paragraph","text":"Manterás espiões por toda a parte. Deves supor que o inimigo fará o mesmo. Se chegas a descobri-Ias, evita condená-Ias à morte. Seus dias","page":78},{"type":"paragraph","text":"devem ser-te infinitamente preciosos. Os espiões dos inimigos te servirão eficazmente, se controlares tuas próprias atitudes, tuas palavras e todas as","page":79},{"type":"paragraph","text":"tuas ações. Assim, eles só darão falsas pistas aos seus mandatários.","page":79},{"type":"paragraph","text":"Enfim, um bom general deve tirar partido de tudo. Nada deve surpreendê-Ia, aconteça o que acontecer. Mas, acima de tudo, deve colocar","page":79},{"type":"paragraph","text":"em prática os cinco tipos de divisão. Nada é impossível a quem lança mão do artifício da divisão.","page":79},{"type":"paragraph","text":"Defender os Estados de seu soberano, ampliá-Ias, realizar diariamente novas conquistas, exterminar os inimigos, fundar até mesmo novas dinastias,","page":79},{"type":"paragraph","text":"tudo isso pode ser o efeito de dissensões semeadas adequadamente.","page":79},{"type":"paragraph","text":"Este foi o caminho que permitiu o advento das dinastias Yin e Cheu, onde trânsfugas contribuíram para sua elevação.","page":79},{"type":"paragraph","text":"Que livro faz a apologia desses grandes ministros? A História chamou- os alguma vez de traidores da pátria, ou considerou-os como rebeldes a seus","page":79},{"type":"paragraph","text":"soberanos? Somente um príncipe esclarecido e um general digno podem aliciar os espíritos mais penetrantes e realizar feitos notáveis. Um exército sem","page":79},{"type":"paragraph","text":"agentes secretos é um homem cego e surdo.","page":79},{"type":"image","src":"_sistema/biblioteca_data/images/a_arte_da_guerra_sun_tzu/img_p80_161.jpeg","page":80,"width":362,"height":632}];
